import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Track } from '../types';

interface PlayerProps {
  track: Track;
  isPlaying: boolean;
  onTogglePlay: () => void;
  onNext: () => void;
  onPrev: () => void;
}

const Player: React.FC<PlayerProps> = ({ track, isPlaying, onTogglePlay, onNext, onPrev }) => {
  const [progress, setProgress] = useState(35);
  const [volume, setVolume] = useState(65);
  const [reps, setReps] = useState(108);
  const [resumeFromBreak, setResumeFromBreak] = useState(true);
  const [showSettings, setShowSettings] = useState(false);

  // Timer States
  const [showTimerMenu, setShowTimerMenu] = useState(false);
  const [remainingSeconds, setRemainingSeconds] = useState<number | null>(null);

  const timerPresets = [
    { label: '15分', value: 15 * 60 },
    { label: '30分', value: 30 * 60 },
    { label: '60分', value: 60 * 60 },
    { label: '90分', value: 90 * 60 },
  ];

  useEffect(() => {
    let interval: any;
    if (isPlaying) {
      interval = setInterval(() => {
        setProgress(prev => (prev < 100 ? prev + 0.1 : 0));
      }, 100);
    }
    return () => clearInterval(interval);
  }, [isPlaying]);

  // Countdown Logic
  useEffect(() => {
    let timerId: any;
    if (isPlaying && remainingSeconds !== null && remainingSeconds > 0) {
      timerId = setInterval(() => {
        setRemainingSeconds(prev => {
          if (prev !== null && prev <= 1) {
            onTogglePlay(); // Stop playing when time is up
            return null;
          }
          return prev !== null ? prev - 1 : null;
        });
      }, 1000);
    }
    return () => {
      if (timerId) clearInterval(timerId);
    };
  }, [isPlaying, remainingSeconds, onTogglePlay]);

  const adjustReps = (delta: number) => {
    setReps(Math.max(1, reps + delta));
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const startTimer = (seconds: number) => {
    setRemainingSeconds(seconds);
    setShowTimerMenu(false);
    if (!isPlaying) onTogglePlay();
  };

  const cancelTimer = () => {
    setRemainingSeconds(null);
    setShowTimerMenu(false);
  };

  return (
    <main className="flex-1 flex flex-col justify-center px-6 relative z-10 pb-28">
      {/* Serene Zen Background Texture */}
      <div 
        className="absolute inset-0 z-0 opacity-10 pointer-events-none mix-blend-overlay"
        style={{
          backgroundImage: "url('https://images.unsplash.com/photo-1541701494587-cb58502866ab?q=80&w=2000&auto=format&fit=crop')",
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          filter: 'sepia(0.4)'
        }}
      />

      <div className="relative flex flex-col items-center mb-6 z-10">
        <div className="w-full max-w-[360px] relative flex items-center justify-center">
          <button 
            onClick={onPrev}
            className="absolute -left-2 z-20 metal-btn rounded-full p-3 text-gold-dark hover:text-gold-main active:scale-95 transition-all"
          >
            <span className="material-symbols-outlined text-[32px]">chevron_left</span>
          </button>

          <div className="relative w-[280px] h-[280px] rounded-full gold-ring shadow-gold-glow">
            <div className="w-full h-full rounded-full overflow-hidden bg-[#0c0805] relative flex items-center justify-center halo-effect border-4 border-[#1A0F08]">
              <div className="absolute inset-0 bg-radial-gradient from-amber-900/20 to-transparent opacity-50"></div>
              {/* Buddha image stays static and forward-facing as requested */}
              <img 
                alt={track.title}
                className="w-[85%] h-[85%] object-contain relative z-10 drop-shadow-2xl rounded-full transition-all duration-700" 
                src={track.imageUrl} 
              />
              <div className="absolute inset-0 rounded-full shadow-inner-gold pointer-events-none z-20"></div>
            </div>
          </div>

          <button 
            onClick={onNext}
            className="absolute -right-2 z-20 metal-btn rounded-full p-3 text-gold-dark hover:text-gold-main active:scale-95 transition-all"
          >
            <span className="material-symbols-outlined text-[32px]">chevron_right</span>
          </button>
        </div>

        <div className="mt-8 text-center space-y-2">
          <div className="inline-flex items-center px-3 py-0.5 border border-gold-dark/30 rounded-full bg-[#1c1209]/50 backdrop-blur-sm">
            <span className="text-gold-dark text-[10px] tracking-[0.2em] uppercase font-serif">NO. {track.code}</span>
          </div>
          <div>
            <h2 className="text-gold-light text-xl font-semibold tracking-wide font-serif drop-shadow-md">{track.title}</h2>
            <p className="text-stone-400 text-xs mt-1 font-light tracking-[0.3em] font-serif opacity-75">{track.subtitle}</p>
          </div>
        </div>
      </div>

      <div className="mt-4 max-w-[340px] mx-auto w-full space-y-6 z-10">
        {/* Playback Controls */}
        <div className="flex items-center justify-between px-4">
          <button 
            onClick={() => setShowSettings(!showSettings)}
            className={`w-12 h-12 rounded-full metal-btn flex items-center justify-center active:scale-95 transition-all ${showSettings ? 'border-gold-main shadow-[0_0_15px_rgba(212,175,55,0.3)]' : ''}`}
          >
            <span className={`material-symbols-outlined text-[24px] ${showSettings ? 'text-gold-main' : 'text-gold-dark/70'}`}>sync</span>
          </button>

          <div className="flex flex-col items-center gap-2 relative">
            <div className={`absolute inset-0 bg-gold-main blur-xl opacity-20 rounded-full transform scale-150 transition-opacity duration-1000 ${isPlaying ? 'opacity-30' : 'opacity-0'}`}></div>
            <button 
              onClick={onTogglePlay}
              className="relative w-20 h-20 rounded-full bg-gold-metal flex items-center justify-center shadow-hard-shadow active:scale-95 active:brightness-95 transition-all border-4 border-[#2C1E12] z-10"
            >
              <span className="material-symbols-outlined text-[#3d2b1f] text-[48px] fill-1 ml-1">
                {isPlaying ? 'pause' : 'play_arrow'}
              </span>
            </button>
          </div>

          <div className="relative">
            <button 
              onClick={(e) => {
                e.stopPropagation();
                setShowTimerMenu(!showTimerMenu);
              }}
              className={`w-12 h-12 rounded-full metal-btn flex items-center justify-center active:scale-95 transition-all ${remainingSeconds !== null ? 'border-gold-main text-gold-main shadow-[0_0_10px_rgba(212,175,55,0.4)]' : 'text-gold-dark/70'}`}
            >
              {remainingSeconds !== null ? (
                <span className="text-[10px] font-bold font-display">{formatTime(remainingSeconds)}</span>
              ) : (
                <span className="material-symbols-outlined text-[24px]">timer</span>
              )}
            </button>

            {/* Timer Selection Menu */}
            {showTimerMenu && (
              <div className="absolute bottom-full right-0 mb-4 bg-[#1a1208] border border-gold-dark/30 rounded-2xl shadow-2xl p-2 min-w-[120px] flex flex-col gap-1 z-50 backdrop-blur-xl animate-in fade-in slide-in-from-bottom-2 duration-300">
                <p className="text-[10px] text-gold-dark/60 text-center py-1 uppercase tracking-widest font-serif">选择定时</p>
                {timerPresets.map(preset => (
                  <button
                    key={preset.value}
                    onClick={() => startTimer(preset.value)}
                    className="px-4 py-2 hover:bg-gold-main/10 rounded-xl text-xs text-gold-light text-left transition-colors font-serif"
                  >
                    {preset.label}
                  </button>
                ))}
                {remainingSeconds !== null && (
                  <button
                    onClick={cancelTimer}
                    className="px-4 py-2 mt-1 border-t border-white/5 text-red-400 text-xs text-left font-serif"
                  >
                    取消定时
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Loop Settings Panel (Integrated) */}
        <div className={`transition-all duration-500 ease-in-out overflow-hidden ${showSettings ? 'max-h-48 opacity-100 mb-4' : 'max-h-0 opacity-0'}`}>
          <div className="bg-[#1c1209]/60 backdrop-blur-md rounded-2xl border border-gold-dark/20 p-4 space-y-4">
            <div className="flex items-center justify-between">
              <span className="text-stone-400 text-xs font-serif tracking-widest uppercase">循环次数</span>
              <div className="flex items-center gap-4">
                <button onClick={() => adjustReps(-1)} className="text-gold-main/60 hover:text-gold-main active:scale-90 transition-all">
                  <span className="material-symbols-outlined">remove_circle_outline</span>
                </button>
                <span className="text-gold-light font-bold font-display min-w-[3ch] text-center">{reps}</span>
                <button onClick={() => adjustReps(1)} className="text-gold-main/60 hover:text-gold-main active:scale-90 transition-all">
                  <span className="material-symbols-outlined">add_circle_outline</span>
                </button>
              </div>
            </div>
            <div className="flex items-center justify-between">
              <div className="flex flex-col">
                <span className="text-stone-400 text-xs font-serif tracking-widest uppercase">断点续播</span>
                <span className="text-[10px] text-stone-600">下次打开自动从上次位置开始</span>
              </div>
              <button 
                onClick={() => setResumeFromBreak(!resumeFromBreak)}
                className={`w-10 h-5 rounded-full transition-colors relative flex items-center ${resumeFromBreak ? 'bg-gold-main/40' : 'bg-stone-800'}`}
              >
                <div className={`w-4 h-4 rounded-full shadow-md transition-transform duration-300 transform ${resumeFromBreak ? 'translate-x-5 bg-gold-main' : 'translate-x-1 bg-stone-500'}`} />
              </button>
            </div>
          </div>
        </div>

        {/* Volume Controls */}
        <div className="space-y-3 px-2">
          <div className="flex items-center bg-[#150f0a]/80 backdrop-blur-sm p-1 rounded-full border border-white/5 shadow-inner relative overflow-hidden">
            <button className="p-2.5 text-gold-dark/60 active:text-gold-main transition-colors z-10" onClick={() => setVolume(Math.max(0, volume - 10))}>
              <span className="material-symbols-outlined text-[20px]">volume_down</span>
            </button>
            <div className="flex-1 h-1 bg-[#2a1f16] rounded-full mx-2 overflow-hidden relative cursor-pointer" onClick={(e) => {
              const rect = e.currentTarget.getBoundingClientRect();
              const x = e.clientX - rect.left;
              setVolume(Math.round((x / rect.width) * 100));
            }}>
              <div className="h-full bg-gold-metal shadow-[0_0_10px_rgba(212,175,55,0.5)] transition-all" style={{ width: `${volume}%` }}></div>
            </div>
            <button className="p-2.5 text-gold-dark/60 active:text-gold-main transition-colors z-10" onClick={() => setVolume(Math.min(100, volume + 10))}>
              <span className="material-symbols-outlined text-[20px]">volume_up</span>
            </button>
          </div>
        </div>
      </div>
    </main>
  );
};

