import React, { useState, useEffect, useRef } from 'react';
import { Track } from '../types';
import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
  onBack: () => void;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId, onBack }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load custom tracks from localStorage
  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }
  }, []);

  // Save custom tracks to localStorage
  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
    localStorage.setItem(CUSTOM_TRACKS_KEY, JSON.stringify(tracks));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewTrackUrl(url);
      if (!newTrackTitle) {
        setNewTrackTitle(file.name.replace(/\.[^/.]+$/, ""));
      }
    }
  };

  const handleAddTrack = () => {
    if (!newTrackTitle || !newTrackUrl) return;

    const newTrack: Track = {
      id: `custom_${Date.now()}`,
      code: `Z${(customTracks.length + 1).toString().padStart(2, '0')}`,
      title: newTrackTitle,
      subtitle: addMethod === 'file' ? '本地上传' : '网络链接',
      section: 'CUSTOM',
      imageUrl: 'https://lh3.googleusercontent.com/aida-public/AB6AXuBJupDlq9JO1_3H0HeLoFF4eVm6ydKebYrZkOL-4iYlDL4hLYi7yEQpNPXp20s98OhpF7MxXwgZtwzpACof1MXEj-GmgejY4TCx3vUE54sfQLJhTtifwaAGnB8vihtksdesusrjADyEWrRqjzUAhBGddYhFiwoH2O32UkEA7mOBdxQjNn-7fdZHIN36BrCjD7eghLr-lC-aXUPZ5Lu3ODxnxnxaTJNFhkx7Mh7MaXKqabQm1VUe2ujaI0k-wb0azO8EYW7tFBdrAQ83' // Default Dabeizou image
    };

    saveCustomTracks([...customTracks, newTrack]);
    setShowAddModal(false);
    setNewTrackTitle('');
    setNewTrackUrl('');
  };

  const removeTrack = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = customTracks.filter(t => t.id !== id);
    saveCustomTracks(updated);
  };

  return (
    <div className="flex flex-col h-full bg-dark-gradient pb-40">
      <div className="sticky top-0 z-30 flex items-center bg-[#221b10]/95 backdrop-blur-md px-4 py-3 justify-between border-b border-primary/20 shadow-lg">
