        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 backdrop-blur-md bg-black/60">
          <div className="w-full max-w-sm bg-surface-dark border border-gold-dark/30 rounded-[2rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <h3 className="text-gold-light text-xl font-bold font-serif mb-6 text-center tracking-widest">添加修行曲目</h3>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-stone-500 text-[10px] uppercase tracking-widest font-serif ml-1">曲目名称</label>
                <input 
                  type="text" 
                  value={newTrackTitle}
                  onChange={(e) => setNewTrackTitle(e.target.value)}
                  placeholder="请输入曲目名称"
                  className="w-full bg-black/30 border border-gold-dark/20 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none transition-colors"
                />
              </div>

              <div className="space-y-3">
                <div className="flex gap-2">
                  <button 
                    onClick={() => setAddMethod('url')}
                    className={`flex-1 py-2 rounded-lg text-xs font-serif transition-all ${addMethod === 'url' ? 'bg-gold-main/20 text-gold-main border border-gold-main/30' : 'bg-black/20 text-stone-500 border border-transparent'}`}
                  >
                    网络链接
                  </button>
                  <button 
                    onClick={() => setAddMethod('file')}
                    className={`flex-1 py-2 rounded-lg text-xs font-serif transition-all ${addMethod === 'file' ? 'bg-gold-main/20 text-gold-main border border-gold-main/30' : 'bg-black/20 text-stone-500 border border-transparent'}`}
                  >
                    本地文件
                  </button>
                </div>

                {addMethod === 'url' ? (
                  <div className="space-y-2">
                    <label className="text-stone-500 text-[10px] uppercase tracking-widest font-serif ml-1">音频URL</label>
                    <input 
                      type="text" 
                      value={newTrackUrl}
                      onChange={(e) => setNewTrackUrl(e.target.value)}
                      placeholder="https://example.com/audio.mp3"
                      className="w-full bg-black/30 border border-gold-dark/20 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none transition-colors"
                    />
                  </div>
                ) : (
                  <div className="space-y-2">
                    <label className="text-stone-500 text-[10px] uppercase tracking-widest font-serif ml-1">选择文件</label>
                    <div 
                      onClick={() => fileInputRef.current?.click()}
                      className="w-full bg-black/30 border border-dashed border-gold-dark/20 rounded-xl px-4 py-4 text-center cursor-pointer hover:border-gold-main transition-colors"
                    >
                      <span className="text-gold-main/60 text-xs font-serif">
                        {newTrackUrl ? '已选择音频' : '点击上传本地音频'}
                      </span>
                      <input 
                        type="file" 
                        ref={fileInputRef}
                        onChange={handleFileUpload}
                        accept="audio/*"
                        className="hidden"
                      />
                    </div>
                  </div>
                )}
              </div>

              <div className="flex gap-3 pt-4">
                <button 
                  onClick={() => setShowAddModal(false)}
                  className="flex-1 py-3 rounded-xl border border-gold-dark/30 text-stone-400 font-bold tracking-widest font-serif active:scale-95 transition-all"
                >
                  取消
                </button>
                <button 
                  onClick={handleAddTrack}
                  disabled={!newTrackTitle || !newTrackUrl}
                  className="flex-1 py-3 rounded-xl bg-gold-metal text-[#3d2b1f] font-bold tracking-widest font-serif active:scale-95 transition-all disabled:opacity-30"
                >
                  确认添加
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

