import React, { useState, useEffect } from 'react';
import { Track } from '../types';

interface PlayerProps {
  track: Track;
  isPlaying: boolean;
  onTogglePlay: () => void;
  onNext: () => void;
  onPrev: () => void;
  currentTime: number;
  duration: number;
  volume: number;
  setVolume: (vol: number) => void;
}

const Player: React.FC<PlayerProps> = ({ 
  track, isPlaying, onTogglePlay, onNext, onPrev, 
  currentTime, duration, volume, setVolume 
}) => {
  const [reps, setReps] = useState(108);
  const [showSettings, setShowSettings] = useState(false);
  const [showTimerMenu, setShowTimerMenu] = useState(false);
  const [remainingSeconds, setRemainingSeconds] = useState<number | null>(null);

  const timerPresets = [
    { label: '15分', value: 15 * 60 },
    { label: '30分', value: 30 * 60 },
    { label: '60分', value: 60 * 60 },
    { label: '90分', value: 90 * 60 },
  ];

  useEffect(() => {
    let timerId: any;
    if (isPlaying && remainingSeconds !== null && remainingSeconds > 0) {
      timerId = setInterval(() => {
        setRemainingSeconds(prev => {
          if (prev !== null && prev <= 1) {
            onTogglePlay(); 
            return null;
          }
          return prev !== null ? prev - 1 : null;
        });
      }, 1000);
    }
    return () => clearInterval(timerId);
  }, [isPlaying, remainingSeconds, onTogglePlay]);

  const formatSeconds = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60);
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const progressPercent = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <main className="flex-1 flex flex-col justify-center px-6 relative z-10 pb-28">
      {/* 佛像显示区域 */}
      <div className="relative flex flex-col items-center mb-8 z-10">
        <div className="w-full max-w-[360px] relative flex items-center justify-center">
          <button 
            onClick={onPrev}
            className="absolute left-0 z-20 metal-btn rounded-full p-4 text-gold-dark hover:text-gold-main active:scale-95 transition-all"
            aria-label="上一曲"
          >
            <span className="material-symbols-outlined text-[32px]">chevron_left</span>
          </button>

          <div className="relative w-[280px] h-[280px] rounded-full gold-ring shadow-[0_0_50px_rgba(212,175,55,0.25)]">
            <div className="w-full h-full rounded-full overflow-hidden bg-[#0c0805] relative flex items-center justify-center halo-effect border-4 border-[#1A0F08]">
              <div className={`absolute inset-0 bg-gold-main/10 transition-opacity duration-1000 ${isPlaying ? 'opacity-40 animate-pulse-gentle' : 'opacity-10'}`}></div>
              <img 
                alt={track.title}
                className={`w-[82%] h-[82%] object-contain relative z-10 drop-shadow-2xl transition-transform duration-700 ${isPlaying ? 'scale-105' : 'scale-100'}`} 
                src={track.imageUrl} 
              />
              <div className="absolute inset-0 rounded-full shadow-inner-gold pointer-events-none z-20"></div>
            </div>
          </div>

          <button 
            onClick={onNext}
            className="absolute right-0 z-20 metal-btn rounded-full p-4 text-gold-dark hover:text-gold-main active:scale-95 transition-all"
            aria-label="下一曲"
          >
            <span className="material-symbols-outlined text-[32px]">chevron_right</span>
          </button>
        </div>

        {/* 标题信息：增强对比度与层级 */}
        <div className="mt-10 text-center space-y-2">
          <div className="inline-flex items-center px-4 py-1 border border-gold-dark/40 rounded-full bg-[#1c1209]/80 backdrop-blur-sm shadow-inner">
            <span className="text-gold-main text-[12px] tracking-[0.2em] font-bold font-serif">{track.code}</span>
          </div>
          <div>
            <h2 className="text-stone-100 text-2xl font-bold tracking-wider font-serif drop-shadow-lg">{track.title}</h2>
            <p className="text-stone-400 text-[14px] mt-1 font-light tracking-[0.2em] font-serif opacity-90">{track.subtitle}</p>
          </div>
        </div>
      </div>

      <div className="mt-4 max-w-[340px] mx-auto w-full space-y-8 z-10">
        {/* 进度控制：增加触控感知 */}
        <div className="px-2 space-y-3">
          <div className="h-2 w-full bg-black/50 rounded-full overflow-hidden shadow-inner border border-white/5">
            <div 
              className="h-full bg-gold-main transition-all duration-300 shadow-[0_0_12px_rgba(212,175,55,0.8)]" 
              style={{ width: `${progressPercent}%` }}
            />
          </div>
          <div className="flex justify-between text-[11px] text-stone-400 font-display tracking-widest">
            <span>{formatSeconds(currentTime)}</span>
            <span>{formatSeconds(duration)}</span>
          </div>
        </div>

        {/* 交互按钮组 */}
        <div className="flex items-center justify-between px-2">
          <button 
            onClick={() => setShowSettings(!showSettings)}
            className={`w-14 h-14 rounded-full metal-btn flex items-center justify-center active:scale-90 transition-all ${showSettings ? 'border-gold-main shadow-[0_0_20px_rgba(212,175,55,0.3)]' : ''}`}
          >
            <span className={`material-symbols-outlined text-[26px] ${showSettings ? 'text-gold-main' : 'text-stone-400'}`}>repeat_one</span>
          </button>

          <div className="relative group">
            <div className={`absolute -inset-4 bg-gold-main blur-2xl opacity-0 transition-opacity duration-1000 ${isPlaying ? 'opacity-10' : ''}`}></div>
            <button 
              onClick={onTogglePlay}
              className="relative w-22 h-22 rounded-full bg-gold-metal flex items-center justify-center shadow-[0_10px_30px_rgba(0,0,0,0.6)] active:scale-95 active:brightness-95 transition-all border-4 border-[#2C1E12] z-10"
            >
              <span className="material-symbols-outlined text-[#3d2b1f] text-[52px] fill-1">
                {isPlaying ? 'pause' : 'play_arrow'}
              </span>
            </button>
          </div>

          <div className="relative">
            <button 
              onClick={() => setShowTimerMenu(!showTimerMenu)}
              className={`w-14 h-14 rounded-full metal-btn flex items-center justify-center active:scale-90 transition-all ${remainingSeconds !== null ? 'border-gold-main text-gold-main' : 'text-stone-400'}`}
            >
              {remainingSeconds !== null ? (
                <span className="text-[12px] font-bold font-display">{formatSeconds(remainingSeconds)}</span>
              ) : (
                <span className="material-symbols-outlined text-[26px]">schedule</span>
              )}
            </button>

            {showTimerMenu && (
              <div className="absolute bottom-full right-0 mb-6 bg-[#1a1208] border border-gold-dark/30 rounded-2xl shadow-2xl p-2 min-w-[140px] z-50 animate-in fade-in slide-in-from-bottom-2">
                <p className="text-[10px] text-gold-dark/70 text-center py-2 uppercase tracking-widest font-serif border-b border-white/5">定时关机</p>
                {timerPresets.map(preset => (
                  <button
                    key={preset.value}
                    onClick={() => { setRemainingSeconds(preset.value); setShowTimerMenu(false); }}
                    className="w-full px-4 py-3 hover:bg-gold-main/10 rounded-xl text-xs text-gold-light text-left transition-colors font-serif"
                  >
                    {preset.label}
                  </button>
                ))}
                {remainingSeconds !== null && (
                  <button onClick={() => setRemainingSeconds(null)} className="w-full px-4 py-3 mt-1 border-t border-white/5 text-red-400 text-xs text-left font-serif">取消</button>
                )}
              </div>
            )}
          </div>
        </div>

        {/* 音量控制：加粗并增强视觉 */}
        <div className="pt-2 px-2">
          <div className="flex items-center bg-black/40 backdrop-blur-md p-2 rounded-full border border-white/5">
            <span className="material-symbols-outlined text-[20px] text-stone-500 ml-2">volume_mute</span>
            <div className="flex-1 h-2 bg-[#2a1f16] rounded-full mx-3 overflow-hidden relative cursor-pointer" onClick={(e) => {
              const rect = e.currentTarget.getBoundingClientRect();
              setVolume((e.clientX - rect.left) / rect.width);
            }}>
              <div className="h-full bg-gold-metal shadow-[0_0_10px_rgba(212,175,55,0.4)]" style={{ width: `${volume * 100}%` }}></div>
            </div>
            <span className="material-symbols-outlined text-[20px] text-stone-500 mr-2">volume_up</span>
          </div>
        </div>
      </div>
    </main>
  );
};

export default Player;

