import React, { useState, useEffect } from 'react';
import { Track } from '../types';

interface PlayerProps {
  track: Track;
  isPlaying: boolean;
  onTogglePlay: () => void;
  onNext: () => void;
  onPrev: () => void;
  currentTime: number;
  duration: number;
  volume: number;
  setVolume: (vol: number) => void;
}

const Player: React.FC<PlayerProps> = ({ 
  track, isPlaying, onTogglePlay, onNext, onPrev, 
  currentTime, duration, volume, setVolume 
}) => {
  const [showTimerMenu, setShowTimerMenu] = useState(false);
  const [remainingSeconds, setRemainingSeconds] = useState<number | null>(null);

  const timerPresets = [
    { label: '15分', value: 15 * 60 },
    { label: '30分', value: 30 * 60 },
    { label: '60分', value: 60 * 60 },
    { label: '90分', value: 90 * 60 },
  ];

  useEffect(() => {
    let timerId: any;
    if (isPlaying && remainingSeconds !== null && remainingSeconds > 0) {
      timerId = setInterval(() => {
        setRemainingSeconds(prev => {
          if (prev !== null && prev <= 1) {
            onTogglePlay(); 
            return null;
          }
          return prev !== null ? prev - 1 : null;
        });
      }, 1000);
    }
    return () => clearInterval(timerId);
  }, [isPlaying, remainingSeconds, onTogglePlay]);

  const formatSeconds = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60);
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const progressPercent = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <main className="flex-1 flex flex-col justify-center px-6 relative z-10 pb-28">
      {/* 佛像显示区域 - 优化了视觉层级和动效 */}
      <div className="relative flex flex-col items-center mb-10 z-10">
        <div className="w-full max-w-[360px] relative flex items-center justify-center">

          {/* 背景呼吸光晕 */}
          <div className={`absolute w-[340px] h-[340px] rounded-full bg-gold-main blur-[60px] pointer-events-none transition-opacity duration-1000 ${isPlaying ? 'animate-aura-breath' : 'opacity-0'}`}></div>

          <button 
            onClick={onPrev}
            className="absolute left-0 z-20 metal-btn rounded-full p-4 text-gold-dark hover:text-gold-main active:scale-90 transition-all focus:outline-none"
            aria-label="上一曲"
          >
            <span className="material-symbols-outlined text-[34px]">chevron_left</span>
          </button>

          <div className="relative w-[280px] h-[280px] rounded-full gold-ring shadow-[0_0_80px_rgba(212,175,55,0.2)]">
            <div className="w-full h-full rounded-full overflow-hidden bg-[#0c0805] relative flex items-center justify-center halo-effect border-4 border-[#1A0F08]">
              {/* 播放状态下的微光补强 */}
              <div className={`absolute inset-0 bg-gold-main/20 transition-opacity duration-2000 ${isPlaying ? 'opacity-30' : 'opacity-0'}`}></div>

              <img 
                alt={track.title}
                className={`w-[85%] h-[85%] object-contain relative z-10 drop-shadow-[0_0_20px_rgba(212,175,55,0.4)] transition-transform duration-[4000ms] ${isPlaying ? 'scale-110' : 'scale-100'}`} 
                src={track.imageUrl} 
              />
              <div className="absolute inset-0 rounded-full shadow-inner-gold pointer-events-none z-20"></div>
            </div>
          </div>

          <button 
            onClick={onNext}
            className="absolute right-0 z-20 metal-btn rounded-full p-4 text-gold-dark hover:text-gold-main active:scale-90 transition-all focus:outline-none"
            aria-label="下一曲"
          >
            <span className="material-symbols-outlined text-[34px]">chevron_right</span>
          </button>
        </div>

        {/* 曲目信息：显著提升可读性 */}
        <div className="mt-12 text-center space-y-3">
          <div className="inline-flex items-center px-4 py-1.5 border border-gold-dark/50 rounded-full bg-[#1c1209]/90 backdrop-blur-sm shadow-xl">
            <span className="text-gold-light text-[13px] tracking-[0.25em] font-bold font-serif">{track.code}</span>
          </div>
          <div>
            <h2 className="text-stone-100 text-3xl font-bold tracking-[0.1em] font-serif drop-shadow-[0_2px_10px_rgba(0,0,0,0.8)]">{track.title}</h2>
            <p className="text-gold-dark text-[15px] mt-2 font-light tracking-[0.2em] font-serif opacity-80">{track.subtitle}</p>
          </div>
        </div>
      </div>

      <div className="mt-4 max-w-[340px] mx-auto w-full space-y-10 z-10">
        {/* 进度条：增加对比度和视觉厚度 */}
        <div className="px-1 space-y-4">
          <div 
            className="h-3 w-full bg-black/60 rounded-full overflow-hidden shadow-inner border border-white/5 cursor-pointer"
            onClick={(e) => {
              // 简易进度条跳转逻辑（需配合父组件实现）
            }}
          >
            <div 
              className="h-full bg-gold-metal transition-all duration-500 shadow-[0_0_15px_rgba(212,175,55,0.7)]" 
              style={{ width: `${progressPercent}%` }}
            />
          </div>
          <div className="flex justify-between text-[12px] text-stone-400 font-display tracking-widest font-medium">
            <span className="bg-black/20 px-2 py-0.5 rounded">{formatSeconds(currentTime)}</span>
            <span className="bg-black/20 px-2 py-0.5 rounded">{formatSeconds(duration)}</span>
          </div>
        </div>

        {/* 控制核心 */}
        <div className="flex items-center justify-between px-2">
          {/* 循环模式 */}
          <button 
            className="w-14 h-14 rounded-full metal-btn flex items-center justify-center text-stone-500 hover:text-gold-main transition-colors active:scale-90"
          >
            <span className="material-symbols-outlined text-[28px]">repeat</span>
          </button>

          {/* 播放/暂停：核心交互 */}
          <div className="relative">
            <div className={`absolute -inset-6 bg-gold-main/20 blur-3xl rounded-full transition-opacity duration-1000 ${isPlaying ? 'opacity-100' : 'opacity-0'}`}></div>
            <button 
              onClick={onTogglePlay}
              className="relative w-24 h-24 rounded-full bg-gold-metal flex items-center justify-center shadow-[0_15px_40px_rgba(0,0,0,0.7)] active:scale-95 active:brightness-90 transition-all border-4 border-[#2C1E12] z-10"
            >
              <span className="material-symbols-outlined text-[#3d2b1f] text-[58px] fill-1">
                {isPlaying ? 'pause' : 'play_arrow'}
              </span>
            </button>
          </div>

          {/* 定时器 */}
          <div className="relative">
            <button 
              onClick={() => setShowTimerMenu(!showTimerMenu)}
              className={`w-14 h-14 rounded-full metal-btn flex items-center justify-center active:scale-90 transition-all ${remainingSeconds !== null ? 'border-gold-main text-gold-main shadow-[0_0_15px_rgba(212,175,55,0.2)]' : 'text-stone-500'}`}
            >
              {remainingSeconds !== null ? (
                <span className="text-[13px] font-bold font-display">{formatSeconds(remainingSeconds)}</span>
              ) : (
                <span className="material-symbols-outlined text-[28px]">schedule</span>
              )}
            </button>

            {showTimerMenu && (
              <div className="absolute bottom-full right-0 mb-6 bg-[#1a1208]/98 border border-gold-dark/40 rounded-[24px] shadow-2xl p-2 min-w-[150px] z-50 animate-in fade-in slide-in-from-bottom-4 backdrop-blur-xl">
                <p className="text-[11px] text-gold-dark/80 text-center py-3 uppercase tracking-[0.2em] font-serif border-b border-white/10 mb-1">定时禅修</p>
                {timerPresets.map(preset => (
                  <button
                    key={preset.value}
                    onClick={() => { setRemainingSeconds(preset.value); setShowTimerMenu(false); }}
                    className="w-full px-5 py-3.5 hover:bg-gold-main/20 rounded-xl text-sm text-gold-light text-left transition-colors font-serif active:bg-gold-main/30"
                  >
                    {preset.label}
                  </button>
                ))}
                {remainingSeconds !== null && (
                  <button onClick={() => setRemainingSeconds(null)} className="w-full px-5 py-3.5 mt-2 border-t border-white/10 text-red-400 text-xs text-center font-serif">取消定时</button>
                )}
              </div>
            )}
          </div>
        </div>

        {/* 音量条：增强触控灵敏度和视觉 */}
        <div className="pt-2 px-1">
          <div className="flex items-center bg-black/50 backdrop-blur-xl p-3 rounded-2xl border border-white/5 shadow-lg">
            <span className="material-symbols-outlined text-[22px] text-stone-500 ml-1">volume_mute</span>
            <div className="flex-1 h-2 bg-[#2a1f16] rounded-full mx-4 overflow-hidden relative cursor-pointer" onClick={(e) => {
              const rect = e.currentTarget.getBoundingClientRect();
              setVolume(Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width)));
            }}>
              <div className="h-full bg-gold-metal shadow-[0_0_15px_rgba(212,175,55,0.5)]" style={{ width: `${volume * 100}%` }}></div>
            </div>
            <span className="material-symbols-outlined text-[22px] text-stone-500 mr-1">volume_up</span>
          </div>
        </div>
      </div>
    </main>
  );
};

