import React, { useState, useEffect } from 'react';
import { Track } from '../types';

interface SettingsProps {
  currentTrack: Track;
  onBack: () => void;
  onNext: () => void;
  onPrev: () => void;
  onStartTask: (target: number) => void;
  taskProgress: number;
  taskTarget: number;
}

const Settings: React.FC<SettingsProps> = ({ 
  currentTrack, onBack, onNext, onPrev, onStartTask, taskProgress, taskTarget 
}) => {
  // selectedTarget 用于记录用户在页面上点击的预设值
  const [selectedTarget, setSelectedTarget] = useState(108);
  const presets = [7, 21, 49, 108];

  // 进度计算
  const displayTarget = taskTarget > 0 ? taskTarget : selectedTarget;
  const displayProgress = taskTarget > 0 ? taskProgress : 0;

  const dashArray = 2 * Math.PI * 115;
  const dashOffset = dashArray * (1 - displayProgress / displayTarget);

