            >
              <span className="material-symbols-outlined text-[#3d2b1f] text-[58px] fill-1">
                {isPlaying ? 'pause' : 'play_arrow'}
              </span>
            </button>
          </div>

          {/* 定时器 */}
          <div className="relative">
            <button 
              onClick={() => setShowTimerMenu(!showTimerMenu)}
              className={`w-14 h-14 rounded-full metal-btn flex items-center justify-center active:scale-90 transition-all ${remainingSeconds !== null ? 'border-gold-main text-gold-main shadow-[0_0_15px_rgba(212,175,55,0.2)]' : 'text-stone-500'}`}
