import React, { useState, useEffect, useRef } from 'react';
import { Track } from '../types';
import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
  onBack: () => void;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId, onBack }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load custom tracks from localStorage
  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }
  }, []);

  // Save custom tracks to localStorage
  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
    localStorage.setItem(CUSTOM_TRACKS_KEY, JSON.stringify(tracks));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewTrackUrl(url);
      if (!newTrackTitle) {
        setNewTrackTitle(file.name.replace(/\.[^/.]+$/, ""));
      }
    }
  };

  const handleAddTrack = () => {
    if (!newTrackTitle || !newTrackUrl) return;

    const newTrack: Track = {
      id: `custom_${Date.now()}`,
      code: `Z${(customTracks.length + 1).toString().padStart(2, '0')}`,
      title: newTrackTitle,
      subtitle: addMethod === 'file' ? '本地上传' : '网络链接',
      section: 'CUSTOM',
      imageUrl: 'https://www.shouyueliang.org/wp-content/uploads/2021/04/1623587633-v500-4-1.gif',
      audioUrl: newTrackUrl
    };

    saveCustomTracks([...customTracks, newTrack]);
    setShowAddModal(false);
    setNewTrackTitle('');
    setNewTrackUrl('');
  };

  const removeTrack = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = customTracks.filter(t => t.id !== id);
    saveCustomTracks(updated);
  };

  return (
    <div className="flex flex-col h-full bg-dark-gradient overflow-hidden">
      {/* 顶部固定栏 */}
      <div className="flex-none bg-[#221b10]/95 backdrop-blur-md z-40 border-b border-white/5">
        <div className="flex items-center px-4 py-3 justify-between">
          <button onClick={onBack} className="text-gold-main hover:text-gold-light transition-colors flex size-10 items-center justify-center active:scale-90">
            <span className="material-symbols-outlined text-2xl">arrow_back_ios_new</span>
          </button>
          <h2 className="text-xl font-bold tracking-widest text-center flex-1 pr-10 font-serif text-gold-light uppercase">曲目列表</h2>
        </div>

        {/* Tab 导航 */}
        <div className="flex px-6">
          <button 
            onClick={() => setActiveTab('official')}
            className={`flex-1 flex flex-col items-center border-b-[2px] pb-3 pt-4 transition-all ${activeTab === 'official' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-500'}`}
          >
            <p className="text-[15px] font-bold tracking-[0.05em]">官方曲目</p>
          </button>
          <button 
            onClick={() => setActiveTab('custom')}
            className={`flex-1 flex flex-col items-center border-b-[2px] pb-3 pt-4 transition-all ${activeTab === 'custom' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-500'}`}
          >
            <p className="text-[15px] font-bold tracking-[0.05em]">自定义</p>
          </button>
        </div>
      </div>

      {/* 滚动列表区域 */}
      <div className="flex-1 overflow-y-auto pb-40 scroll-smooth">
        {activeTab === 'official' ? (
          SECTIONS.map((section) => (
            <div key={section.id} className="mb-2">
              {/* 吸顶分区标题：改为 top-0，因为它现在是滚动容器的直接子代 */}
              <div className="sticky top-0 z-30 bg-[#1a1208]/95 backdrop-blur-md px-5 py-3 border-b border-gold-dark/10 shadow-sm">
                <div className="flex items-center gap-3">
                  <span className="bg-gold-main/20 border border-gold-main/40 text-gold-main text-[10px] font-bold px-2 py-0.5 rounded tracking-widest font-display">
                    {section.code}
                  </span>
                  <h3 className="text-gold-light text-base font-bold font-serif tracking-wider">{section.name}</h3>
                </div>
              </div>

              <div className="flex flex-col divide-y divide-white/5 px-2">
                {TRACKS.filter(t => t.section === section.code).map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.03] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.08]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className={`badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#4a3b18] text-sm font-display shadow-lg border border-[#7c6428]/50 transition-transform ${currentTrackId === track.id ? 'scale-110' : ''}`}>
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        <p className={`text-[17px] font-medium font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-gray-200 group-hover:text-gold-main'}`}>
                          {track.title}
                        </p>
                        <p className="text-stone-500 text-xs tracking-wider font-serif">{track.subtitle}</p>
                      </div>
                    </div>
                    <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-[#5d4a1f] group-hover:text-gold-main'}`}>
                      {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          ))
        ) : (
          <div className="px-2 py-4 space-y-4">
            <button 
              onClick={() => setShowAddModal(true)}
              className="w-full flex items-center justify-center gap-3 py-4 rounded-xl border-2 border-dashed border-gold-dark/30 text-gold-main hover:bg-gold-main/5 transition-colors group"
            >
              <span className="material-symbols-outlined text-2xl group-hover:scale-110 transition-transform">add_circle</span>
              <span className="font-bold tracking-widest font-serif">添加自定义曲目</span>
            </button>

            <div className="flex flex-col divide-y divide-white/5">
              {customTracks.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 opacity-30 text-gold-light">
                  <span className="material-symbols-outlined text-6xl mb-4">music_off</span>
                  <p className="text-sm tracking-widest font-serif">暂无自定义曲目</p>
                </div>
              ) : (
                customTracks.map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.03] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.08]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className="badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#4a3b18] text-sm font-display shadow-lg border border-[#7c6428]/50">
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        <p className={`text-[17px] font-medium font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-gray-200 group-hover:text-gold-main'}`}>
                          {track.title}
                        </p>
                        <p className="text-stone-500 text-xs tracking-wider font-serif">{track.subtitle}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={(e) => removeTrack(e, track.id)}
                        className="text-red-900/40 hover:text-red-500 p-2 transition-colors"
                      >
                        <span className="material-symbols-outlined text-xl">delete</span>
                      </button>
                      <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-[#5d4a1f] group-hover:text-gold-main'}`}>
                        {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                      </span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </div>

      {/* Add Track Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 backdrop-blur-md bg-black/60">
          <div className="w-full max-w-sm bg-surface-dark border border-gold-dark/30 rounded-[2rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <h3 className="text-gold-light text-xl font-bold font-serif mb-6 text-center tracking-widest">添加修行曲目</h3>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-stone-500 text-[10px] uppercase tracking-widest font-serif ml-1">曲目名称</label>
                <input 
                  type="text" 
                  value={newTrackTitle}
                  onChange={(e) => setNewTrackTitle(e.target.value)}
                  placeholder="请输入曲目名称"
                  className="w-full bg-black/30 border border-gold-dark/20 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none transition-colors"
                />
              </div>

              <div className="space-y-3">
                <div className="flex gap-2">
                  <button 
                    onClick={() => setAddMethod('url')}
                    className={`flex-1 py-2 rounded-lg text-xs font-serif transition-all ${addMethod === 'url' ? 'bg-gold-main/20 text-gold-main border border-gold-main/30' : 'bg-black/20 text-stone-500 border border-transparent'}`}
                  >
                    网络链接
                  </button>
                  <button 
                    onClick={() => setAddMethod('file')}
                    className={`flex-1 py-2 rounded-lg text-xs font-serif transition-all ${addMethod === 'file' ? 'bg-gold-main/20 text-gold-main border border-gold-main/30' : 'bg-black/20 text-stone-500 border border-transparent'}`}
                  >
                    本地文件
                  </button>
                </div>

                {addMethod === 'url' ? (
                  <div className="space-y-2">
                    <label className="text-stone-500 text-[10px] uppercase tracking-widest font-serif ml-1">音频URL</label>
                    <input 
                      type="text" 
                      value={newTrackUrl}
                      onChange={(e) => setNewTrackUrl(e.target.value)}
