  onUpdateTarget: (target: number) => void;
  onStopTask: () => void;
  taskProgress: number;
  taskTarget: number;
}

const Settings: React.FC<SettingsProps> = ({ 
  currentTrack, onBack, onNext, onPrev, onUpdateTarget, onStopTask, taskProgress, taskTarget 
}) => {
  const presets = [7, 21, 49, 108];
  const isTaskActive = taskTarget > 0;

  // 进度条与刻度逻辑
  const radius = 115;
  const cx = 140;
  const cy = 140;
  const dashArray = 2 * Math.PI * radius;
  const progressRatio = isTaskActive ? Math.min(taskProgress / taskTarget, 1) : 0;
  const dashOffset = dashArray * (1 - progressRatio);

  // 生成刻度线
  const renderTicks = () => {
    if (!isTaskActive) return null;

    // 如果遍数太多，采用等分策略，避免刻度过密
    const tickCount = taskTarget <= 49 ? taskTarget : 36; // 108遍时每3遍一刻度
    const ticks = [];
    for (let i = 0; i < tickCount; i++) {
      const angle = (i * 360) / tickCount - 90;
      const x1 = cx + (radius - 8) * Math.cos((angle * Math.PI) / 180);
      const y1 = cy + (radius - 8) * Math.sin((angle * Math.PI) / 180);
      const x2 = cx + (radius + 8) * Math.cos((angle * Math.PI) / 180);
      const y2 = cy + (radius + 8) * Math.sin((angle * Math.PI) / 180);

      const isCompleted = (i / tickCount) < progressRatio;

      ticks.push(
        <line
          key={i}
          x1={x1}
          y1={y1}
          x2={x2}
          y2={y2}
          stroke={isCompleted ? "url(#metalGradient)" : "rgba(212, 175, 55, 0.15)"}
          strokeWidth={isCompleted ? "2" : "1"}
          className="transition-all duration-700"
        />
      );
    }
    return ticks;
  };

  return (
    <div className="flex flex-col min-h-screen bg-zen-dark pb-24 overflow-x-hidden">
      {/* 顶部导航 */}
      <header className="flex items-center p-4 justify-between sticky top-0 bg-black/40 backdrop-blur-md border-b border-white/5 z-20">
        <button onClick={onBack} className="text-gold-main flex size-12 items-center justify-start active:scale-90 transition-transform">
          <span className="material-symbols-outlined text-[28px]">arrow_back_ios</span>
        </button>
        <h2 className="text-gray-100 text-lg font-bold tracking-tight flex-1 text-center pr-12 font-serif">精进修行</h2>
      </header>

      <div className="flex-1 flex flex-col items-center justify-center px-6 py-4">

        {/* 曲目切换 - 保持静止、居中 */}
        <div className="mb-8 flex flex-col items-center gap-6 w-full">
          <div className="flex items-center justify-between w-full max-w-[320px]">
            <button 
              onClick={onPrev}
              className="w-12 h-12 rounded-full flex items-center justify-center text-gold-main/30 hover:text-gold-main active:scale-90 transition-all"
            >
              <span className="material-symbols-outlined text-4xl">chevron_left</span>
            </button>

            <div className="relative">
              <div className={`absolute inset-[-20px] bg-gold-main/10 blur-3xl rounded-full transition-opacity duration-1000 ${isTaskActive ? 'opacity-40' : 'opacity-0'}`}></div>
              <div className={`w-28 h-28 rounded-full border p-1 bg-[#1a1208] overflow-hidden relative z-10 transition-all duration-500 ${isTaskActive ? 'border-gold-main/60 shadow-[0_0_30px_rgba(212,175,55,0.2)]' : 'border-white/10'}`}>
                <img className="w-full h-full rounded-full object-cover" src={currentTrack.imageUrl} alt={currentTrack.title} />
              </div>
            </div>

            <button 
              onClick={onNext}
              className="w-12 h-12 rounded-full flex items-center justify-center text-gold-main/30 hover:text-gold-main active:scale-90 transition-all"
            >
              <span className="material-symbols-outlined text-4xl">chevron_right</span>
            </button>
          </div>

          <div className="text-center">
            <h3 className="text-gold-light font-bold text-xl tracking-widest font-serif">{currentTrack.title}</h3>
            <p className="text-stone-600 text-[10px] mt-1 tracking-[0.3em] font-serif uppercase">Selected Track</p>
          </div>
        </div>

        {/* 核心计数圆环 - 精确居中且显示刻度 */}
        <div 
          className="relative w-[280px] h-[280px] flex items-center justify-center mb-10 cursor-pointer group"
          onClick={() => isTaskActive && onStopTask()}
        >
          <svg className="absolute inset-0 w-full h-full -rotate-90" viewBox="0 0 280 280">
            <defs>
              <linearGradient id="metalGradient" x1="0%" x2="100%" y1="0%" y2="100%">
                <stop offset="0%" stopColor="#ffd700" />
                <stop offset="100%" stopColor="#996515" />
              </linearGradient>
            </defs>

            {/* 刻度背景 */}
            {renderTicks()}

            {/* 主圆环背景 */}
            <circle 
              className="text-white/[0.03]" 
              cx={cx} cy={cy} r={radius} 
              fill="transparent" 
              stroke="currentColor" 
              strokeWidth="1" 
            />

            {/* 动态进度环 */}
            <circle 
              cx={cx} cy={cy} r={radius} 
              fill="transparent" 
              stroke="url(#metalGradient)" 
              strokeWidth="6" 
              strokeDasharray={dashArray} 
              strokeDashoffset={dashOffset}
              strokeLinecap="round"
              className="transition-all duration-1000 ease-in-out"
            />
          </svg>

          <div className="flex flex-col items-center z-10 transition-transform group-active:scale-95">
            <div className="flex items-baseline gap-1">
              <span className="text-6xl font-bold text-transparent bg-clip-text bg-gold-metal tracking-tighter drop-shadow-2xl">
                {taskProgress || 0}
              </span>
              {isTaskActive && <span className="text-xl font-semibold text-gold-main/20">/{taskTarget}</span>}
            </div>
            <p className="text-[10px] font-bold text-gold-main/50 mt-3 uppercase tracking-[0.5em] font-serif">
              {isTaskActive ? '当前遍数' : '请礼请遍数'}
            </p>
            {isTaskActive && (
               <div className="mt-3 flex items-center justify-center">
                  <div className="w-1.5 h-1.5 rounded-full bg-gold-main animate-pulse"></div>
                  <span className="text-[9px] text-gold-main/40 ml-2 tracking-widest">修持中</span>
               </div>
            )}
          </div>
        </div>

        {/* 预设选择：矩阵布局 */}
        <div className="grid grid-cols-2 gap-4 w-full max-w-[320px]">
          {presets.map((p) => (
            <button
              key={p}
              onClick={() => onUpdateTarget(p)}
              className={`h-16 rounded-2xl flex flex-col items-center justify-center transition-all duration-300 border font-serif active:scale-95 relative overflow-hidden group ${taskTarget === p ? 'bg-gold-metal text-[#3d2b1f] border-gold-light font-bold shadow-[0_10px_25px_rgba(212,175,55,0.2)]' : 'bg-white/[0.03] text-stone-500 border-white/5 hover:bg-white/10'}`}
            >
              <span className="text-lg tracking-widest relative z-10">{p}遍</span>
              <span className={`text-[8px] uppercase tracking-tighter mt-0.5 relative z-10 ${taskTarget === p ? 'text-[#3d2b1f]/60' : 'text-stone-700'}`}>Mala Rounds</span>
              {taskTarget === p && (
                <div className="absolute inset-0 bg-white/10 mix-blend-overlay"></div>
              )}
            </button>
          ))}
        </div>

        {/* 底部提示 */}
        <div className="mt-auto pt-8 text-stone-700 text-[10px] tracking-[0.3em] font-serif text-center leading-loose opacity-60">
           念念至诚 · 功不唐捐
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect, useRef } from 'react';
import { View, Track } from './types';
import { TRACKS } from './constants';
import BottomNav from './components/BottomNav';
import Player from './components/Player';
import Playlist from './components/Playlist';
import Settings from './components/Settings';
import { getZenQuote } from './services/geminiService';

const App: React.FC = () => {
  const [view, setView] = useState<View>(View.PLAYER);
  const [currentTrack, setCurrentTrack] = useState<Track>(TRACKS[0]);
  const [isPlaying, setIsPlaying] = useState(true);
  const [zenQuote, setZenQuote] = useState("静能生慧，定能生福。");
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.65);
  const [isSingleLoop, setIsSingleLoop] = useState(true); 

  const [taskTarget, setTaskTarget] = useState(0);
  const [taskProgress, setTaskProgress] = useState(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    getZenQuote().then(setZenQuote);
  }, []);

  const isTaskActive = taskTarget > 0;

  // 监听播放状态
  useEffect(() => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.play().catch(() => setIsPlaying(false));
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying]);

  // 同步音量
  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume, currentTrack, view]);

  // 切换曲目逻辑
  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.load();
      if (isPlaying) {
        audioRef.current.play().catch(() => {});
      }
    }
    // 切换曲目时：若正在修行，进度重置到第1遍；若非修行模式，进度清零
    setTaskProgress(isTaskActive ? 1 : 0);
  }, [currentTrack.id]);

  const handleTrackSelect = (track: Track) => {
    setCurrentTrack(track);
    setIsPlaying(true);
    setView(View.PLAYER);
    setTaskTarget(0);
    setTaskProgress(0);
  };

  const handleNext = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const nextTrack = TRACKS[(idx + 1) % TRACKS.length];
      setCurrentTrack(nextTrack);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const prevTrack = TRACKS[(idx - 1 + TRACKS.length) % TRACKS.length];
      setCurrentTrack(prevTrack);
      setIsPlaying(true);
    }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration || 0);
    }
  };

  const handleEnded = () => {
    if (taskTarget > 0) {
      if (taskProgress < taskTarget) {
        setTaskProgress(prev => prev + 1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
          audioRef.current.play();
        }
      } else {
        setIsPlaying(false);
        setTaskTarget(0);
        setTaskProgress(0);
        alert("功德圆满，修行完成。");
      }
    } else if (!isSingleLoop) {
      handleNext();
    }
  };

  const updateTaskTarget = (target: number) => {
    // 开启或更新目标。如果是新开始，进度设为1；如果是已在进行，保持进度仅更新目标
    if (taskProgress === 0) {
        setTaskProgress(1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
        }
    }

    setTaskTarget(target);
    setIsSingleLoop(false);
    setIsPlaying(true);

    if (audioRef.current && audioRef.current.paused) {
      audioRef.current.play();
    }
  };

  const stopTask = () => {
    setTaskTarget(0);
    setTaskProgress(0);
    setIsPlaying(false);
  };

  const renderContent = () => {
    switch (view) {
      case View.PLAYER:
        return (
          <Player 
            track={currentTrack} 
            isPlaying={isPlaying} 
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            currentTime={currentTime}
            duration={duration}
            volume={volume}
            setVolume={setVolume}
          />
        );
      case View.PLAYLIST:
        return (
          <Playlist 
            currentTrackId={currentTrack.id} 
            onTrackSelect={handleTrackSelect}
            onBack={() => setView(View.PLAYER)}
          />
        );
      case View.TIMER:
        return (
          <Settings 
            currentTrack={currentTrack} 
            onBack={() => setView(View.PLAYER)}
            onNext={handleNext}
            onPrev={handlePrev}
            onUpdateTarget={updateTaskTarget}
            onStopTask={stopTask}
            taskProgress={taskProgress}
            taskTarget={taskTarget}
          />
        );
      case View.PROFILE:
        return (
          <div className="flex-1 flex flex-col items-center justify-center p-8 space-y-6 text-center">
            <div className="w-24 h-24 rounded-full badge-texture flex items-center justify-center text-[#4a3b18]">
               <span className="material-symbols-outlined text-5xl">person</span>
            </div>
            <div className="space-y-2">
              <h3 className="text-2xl font-bold text-gold-light">念佛弟子</h3>
              <p className="text-stone-400 text-sm tracking-widest italic">“{zenQuote}”</p>
            </div>
            <div className="w-full grid grid-cols-2 gap-4">
              <div className="p-4 bg-surface-dark/50 rounded-xl border border-white/5">
                <p className="text-gold-main text-lg font-bold">128</p>
                <p className="text-xs text-stone-500">累计天数</p>
              </div>
              <div className="p-4 bg-surface-dark/50 rounded-xl border border-white/5">
                <p className="text-gold-main text-lg font-bold">45.2k</p>
                <p className="text-xs text-stone-500">累计遍数</p>
              </div>
            </div>
            <button 
              onClick={() => getZenQuote().then(setZenQuote)}
              className="px-6 py-2 rounded-full border border-gold-main/30 text-gold-main text-sm hover:bg-gold-main/10 transition-colors"
            >
              换一段开示
            </button>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col w-full max-w-md mx-auto min-h-screen relative shadow-2xl bg-zen-dark overflow-hidden">
      <div className="fixed inset-0 pointer-events-none opacity-20 bg-wood-grain mix-blend-overlay z-0"></div>

      <audio 
        ref={audioRef}
        src={currentTrack.audioUrl}
        onTimeUpdate={handleTimeUpdate}
        onEnded={handleEnded}
        loop={isSingleLoop && taskTarget === 0} 
      />

      {view === View.PLAYER && (
        <header className="flex items-center justify-between px-6 py-5 sticky top-0 z-20 bg-gradient-to-b from-[#0f0a06] to-transparent">
          <button className="flex items-center justify-center w-10 h-10 rounded-full text-gold-main/80 active:text-gold-light transition-colors">
            <span className="material-symbols-outlined text-[26px]">settings</span>
          </button>
          <div className="flex flex-col items-center">
            <h2 className="text-gold-light text-xl font-medium tracking-[0.3em] font-serif">念佛机</h2>
            <div className="h-[1px] w-8 bg-gradient-to-r from-transparent via-gold-dark to-transparent mt-1"></div>
          </div>
          <button className="flex items-center justify-center w-10 h-10 rounded-full text-gold-main/80 active:text-gold-light transition-colors">
            <span className="material-symbols-outlined text-[26px]">palette</span>
          </button>
        </header>
      )}

      {renderContent()}

      <BottomNav activeView={view} onViewChange={setView} />
    </div>
  );
};

export default App;

import React from 'react';
import { Track } from '../types';

interface SettingsProps {
  currentTrack: Track;
  onBack: () => void;
  onNext: () => void;
  onPrev: () => void;
  onUpdateTarget: (target: number) => void;
  onStopTask: () => void;
  taskProgress: number;
  taskTarget: number;
}

const Settings: React.FC<SettingsProps> = ({ 
  currentTrack, onBack, onNext, onPrev, onUpdateTarget, onStopTask, taskProgress, taskTarget 
}) => {
  const presets = [7, 21, 49, 108];
  const isTaskActive = taskTarget > 0;

  // 视觉参数：容器 300x300，圆环半径 110，居中坐标 150
  const size = 300;
  const radius = 110;
  const center = size / 2;
  const dashArray = 2 * Math.PI * radius;

  // 进度：从第一遍开始，播放中进度应为 (taskProgress - 1) / taskTarget 到 taskProgress / taskTarget 的变化
  // 简单处理：当前已完成遍数的进度比例
  const progressRatio = isTaskActive ? Math.min((taskProgress - 1) / taskTarget, 1) : 0;
  const dashOffset = dashArray * (1 - progressRatio);

  /**
   * 刻度生成逻辑：
   * 按照用户要求，N遍对应 N-1 个等分刻度（内部界限）。
   * 刻度从0度（顶部）开始顺时针分布。
   */
  const renderTicks = () => {
    if (!isTaskActive) return null;

    const ticks = [];
    const count = taskTarget; // 包含起点的所有分段点

    for (let i = 0; i < count; i++) {
      // 0度在顶部 (-90 deg)
      const angle = (i * 360 / count) - 90;
      const angleRad = (angle * Math.PI) / 180;

      // 刻度长度控制
      const isMajor = i === 0;
      const tickLen = isMajor ? 12 : 8;

      const x1 = center + (radius - tickLen) * Math.cos(angleRad);
      const y1 = center + (radius - tickLen) * Math.sin(angleRad);
      const x2 = center + (radius + 2) * Math.cos(angleRad);
      const y2 = center + (radius + 2) * Math.sin(angleRad);

      // 颜色逻辑：已播放过的遍数对应的刻度高亮
      // 如果当前在第 N 遍，那么前面的 N-1 个分段点都已过
      const isPassed = i < taskProgress;

      ticks.push(
        <line
          key={i}
          x1={x1}
          y1={y1}
          x2={x2}
          y2={y2}
          stroke={isPassed ? (isMajor ? "#F9Eea5" : "#D4AF37") : "rgba(212, 175, 55, 0.1)"}
          strokeWidth={isPassed ? (isMajor ? "2.5" : "2") : "1"}
          strokeLinecap="round"
          className="transition-all duration-700"
        />
      );
    }
    return ticks;
  };

  return (
    <div className="flex flex-col min-h-screen bg-zen-dark pb-28 overflow-x-hidden">
      {/* 顶部固定栏 */}
      <header className="flex items-center p-4 justify-between sticky top-0 bg-[#0f0a06]/80 backdrop-blur-xl border-b border-white/5 z-30">
        <button onClick={onBack} className="text-gold-main flex size-12 items-center justify-start active:scale-90 transition-transform">
          <span className="material-symbols-outlined text-[28px]">arrow_back_ios</span>
        </button>
        <h2 className="text-gold-light text-lg font-bold tracking-widest flex-1 text-center pr-12 font-serif uppercase">精进修行</h2>
      </header>

      <div className="flex-1 flex flex-col items-center justify-around px-6 py-2">

        {/* 曲目切换与封面 - 极简静止 */}
        <div className="flex flex-col items-center gap-6 w-full mt-4">
          <div className="flex items-center justify-between w-full max-w-[320px]">
            <button 
              onClick={onPrev}
              className="w-10 h-10 rounded-full flex items-center justify-center text-gold-dark/40 hover:text-gold-main active:scale-90 transition-all"
            >
              <span className="material-symbols-outlined text-4xl">chevron_left</span>
            </button>

            <div className="relative">
              <div className={`absolute inset-[-15px] bg-gold-main/5 blur-3xl rounded-full transition-opacity duration-1000 ${isTaskActive ? 'opacity-100' : 'opacity-0'}`}></div>
              <div className={`w-24 h-24 rounded-full border-2 p-1 bg-[#0c0805] overflow-hidden relative z-10 transition-all duration-500 ${isTaskActive ? 'border-gold-main shadow-[0_0_30px_rgba(212,175,55,0.2)]' : 'border-white/10'}`}>
                <img className="w-full h-full rounded-full object-cover grayscale-[0.2]" src={currentTrack.imageUrl} alt={currentTrack.title} />
              </div>
            </div>

            <button 
              onClick={onNext}
              className="w-10 h-10 rounded-full flex items-center justify-center text-gold-dark/40 hover:text-gold-main active:scale-90 transition-all"
            >
              <span className="material-symbols-outlined text-4xl">chevron_right</span>
            </button>
          </div>

          <div className="text-center">
            <h3 className="text-gold-light font-bold text-xl tracking-[0.2em] font-serif">{currentTrack.title}</h3>
            <p className="text-stone-600 text-[10px] mt-1 tracking-[0.4em] font-serif uppercase opacity-60 italic">Continuously Meditating</p>
          </div>
        </div>

        {/* 核心法轮刻度圆环 - 完全居中 */}
        <div 
          className="relative flex items-center justify-center cursor-pointer group my-4"
          style={{ width: size, height: size }}
          onClick={() => isTaskActive && onStopTask()}
        >
          <svg 
            width={size} 
            height={size} 
            viewBox={`0 0 ${size} ${size}`}
            className="absolute inset-0 transition-transform duration-500 group-hover:scale-[1.02]"
          >
            <defs>
              <linearGradient id="goldGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#fcf6ba" />
                <stop offset="50%" stopColor="#bf953f" />
                <stop offset="100%" stopColor="#aa771c" />
              </linearGradient>
            </defs>

            {/* 轨道背景 */}
            <circle 
              cx={center} cy={center} r={radius} 
              fill="transparent" 
              stroke="rgba(255,255,255,0.03)" 
              strokeWidth="1" 
            />

            {/* 刻度线 */}
            {renderTicks()}

            {/* 动态进度环：-90度开始 */}
            <circle 
              cx={center} cy={center} r={radius} 
              fill="transparent" 
              stroke="url(#goldGrad)" 
              strokeWidth="5" 
              strokeDasharray={dashArray} 
              strokeDashoffset={dashOffset}
              strokeLinecap="round"
              transform={`rotate(-90 ${center} ${center})`}
              className="transition-all duration-1000 ease-in-out"
            />
          </svg>

          {/* 中心文字内容 */}
          <div className="flex flex-col items-center z-10 select-none">
            <div className="flex items-baseline gap-1">
              <span className="text-7xl font-bold text-transparent bg-clip-text bg-gold-metal tracking-tighter drop-shadow-[0_10px_20px_rgba(0,0,0,0.5)]">
                {taskProgress || 0}
              </span>
              {isTaskActive && <span className="text-2xl font-semibold text-gold-main/20">/{taskTarget}</span>}
            </div>
            <p className="text-[10px] font-bold text-gold-main/50 mt-4 uppercase tracking-[0.6em] font-serif">
              {isTaskActive ? '当前修持' : '请礼请遍数'}
            </p>
            {isTaskActive && (
               <div className="mt-4 flex flex-col items-center">
                  <span className="material-symbols-outlined text-gold-main/40 text-sm animate-pulse">keyboard_double_arrow_up</span>
                  <span className="text-[8px] text-stone-600 tracking-widest mt-1">点击文字可停止</span>
               </div>
            )}
          </div>
        </div>

        {/* 预设选择：禅意卡片布局 */}
        <div className="grid grid-cols-2 gap-4 w-full max-w-[340px] px-2">
          {presets.map((p) => (
            <button
              key={p}
              onClick={() => onUpdateTarget(p)}
