            >
              <span className="text-xl tracking-widest relative z-10">{p}遍</span>
              <span className={`text-[9px] uppercase tracking-widest mt-0.5 relative z-10 transition-opacity ${taskTarget === p ? 'text-[#3d2b1f]/60' : 'text-stone-700 opacity-60 group-hover:opacity-100'}`}>Consecutive</span>
