  onBack: () => void;
  onNext: () => void;
  onPrev: () => void;
  onUpdateTarget: (target: number) => void;
  onStopTask: () => void;
  taskProgress: number;
  taskTarget: number;
}

const Settings: React.FC<SettingsProps> = ({ 
  currentTrack, onBack, onNext, onPrev, onUpdateTarget, onStopTask, taskProgress, taskTarget 
}) => {
  const presets = [7, 21, 49, 108];
  const isTaskActive = taskTarget > 0;

  // 视觉参数
  const size = 300;
  const radius = 110;
  const center = size / 2;
  const dashArray = 2 * Math.PI * radius;

  // 进度条逻辑：当前正在进行的遍数进度。
  // (taskProgress - 1) 表示已经【完全结束】的遍数
  const progressRatio = isTaskActive ? Math.min((taskProgress - 1) / taskTarget, 1) : 0;
  const dashOffset = dashArray * (1 - progressRatio);

  /**
   * 刻度生成逻辑：
   * 1. 刻度从 0 度（正上方）开始。
   * 2. 将 360 度进行 taskTarget 等分。
   * 3. 每一个等分点放置一个刻度。
   */
  const renderTicks = () => {
    if (!isTaskActive) return null;

    const ticks = [];
    const n = taskTarget;

    for (let i = 0; i < n; i++) {
      // 角度计算：从 -90 度（顶部）开始顺时针
      const angle = (i * 360 / n) - 90;
      const angleRad = (angle * Math.PI) / 180;

      // 起点与终点
      const innerR = radius - 8;
      const outerR = radius + 2;

      const x1 = center + innerR * Math.cos(angleRad);
      const y1 = center + innerR * Math.sin(angleRad);
      const x2 = center + outerR * Math.cos(angleRad);
      const y2 = center + outerR * Math.sin(angleRad);

      // 高亮逻辑：已经完成的遍数对应的刻度
      const isCompleted = i < (taskProgress - 1);
      // 当前正在念的那一遍的起始刻度
      const isCurrent = i === (taskProgress - 1);

      ticks.push(
        <line
          key={i}
          x1={x1}
          y1={y1}
          x2={x2}
          y2={y2}
          stroke={isCompleted ? "#D4AF37" : (isCurrent ? "#F9Eea5" : "rgba(212, 175, 55, 0.1)")}
          strokeWidth={isCurrent || isCompleted ? "2" : "1"}
          strokeLinecap="round"
          className="transition-all duration-500"
        />
      );
    }
    return ticks;
  };

  return (
    <div className="flex flex-col min-h-screen bg-zen-dark pb-28 overflow-x-hidden">
      {/* 顶部固定栏 */}
      <header className="flex items-center p-4 justify-between sticky top-0 bg-[#0f0a06]/80 backdrop-blur-xl border-b border-white/5 z-30">
