              {isTaskActive && <span className="text-2xl font-semibold text-gold-main/20">/{taskTarget}</span>}
            </div>
            <p className="text-[10px] font-bold text-gold-main/50 mt-4 uppercase tracking-[0.6em] font-serif">
              {isTaskActive ? '当前遍数' : '选择修行遍数'}
            </p>
            {isTaskActive && (
               <div className="mt-4 flex flex-col items-center opacity-40">
                  <span className="material-symbols-outlined text-gold-main text-xs animate-bounce">expand_more</span>
                  <span className="text-[8px] text-stone-600 tracking-widest mt-1">点击文字区域停止</span>
               </div>
