import React, { useState, useEffect, useRef } from 'react';
import { View, Track } from './types';
import { TRACKS } from './constants';
import BottomNav from './components/BottomNav';
import Player from './components/Player';
import Playlist from './components/Playlist';
import Settings from './components/Settings';
import Profile from './components/Profile';
import SplashScreen from './components/SplashScreen';
import LogoDesign from './components/LogoDesign';
import { getZenQuote } from './services/geminiService';

const STATS_KEY = 'zen_chant_user_stats';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [view, setView] = useState<View>(View.PLAYER);
  const [currentTrack, setCurrentTrack] = useState<Track>(TRACKS[0]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [zenQuote, setZenQuote] = useState("静能生慧，定能生福。");
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.65);
  const [isSingleLoop, setIsSingleLoop] = useState(true); 

  const [taskTarget, setTaskTarget] = useState(0);
  const [taskProgress, setTaskProgress] = useState(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // 初始化统计数据
  const [stats, setStats] = useState(() => {
    const saved = localStorage.getItem(STATS_KEY);
    if (saved) return JSON.parse(saved);
    return {
      installDate: new Date().toISOString(),
      totalCompletions: 0,
      dailyLogs: {} 
    };
  });

  useEffect(() => {
    getZenQuote().then(setZenQuote);
  }, []);

  useEffect(() => {
    localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  }, [stats]);

  const recordCompletion = (trackId: string) => {
    const today = new Date().toISOString().split('T')[0];
    setStats(prev => {
      const newDailyLogs = { ...prev.dailyLogs };
      if (!newDailyLogs[today]) newDailyLogs[today] = {};
      newDailyLogs[today][trackId] = (newDailyLogs[today][trackId] || 0) + 1;

      return {
        ...prev,
        totalCompletions: prev.totalCompletions + 1,
        dailyLogs: newDailyLogs
      };
    });
  };

  const isTaskActive = taskTarget > 0;

  useEffect(() => {
    if (!audioRef.current || showSplash) return;
    if (isPlaying) {
      audioRef.current.play().catch(() => setIsPlaying(false));
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying, showSplash]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume, currentTrack, view]);

  useEffect(() => {
    if (audioRef.current && !showSplash) {
      audioRef.current.load();
      if (isPlaying) {
        audioRef.current.play().catch(() => {});
      }
    }
    setTaskProgress(isTaskActive ? 1 : 0);
  }, [currentTrack.id, showSplash]);

  const handleTrackSelect = (track: Track) => {
    setCurrentTrack(track);
    setIsPlaying(true);
    setView(View.PLAYER);
    setTaskTarget(0);
    setTaskProgress(0);
  };

  const handleNext = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const nextTrack = TRACKS[(idx + 1) % TRACKS.length];
      setCurrentTrack(nextTrack);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const prevTrack = TRACKS[(idx - 1 + TRACKS.length) % TRACKS.length];
      setCurrentTrack(prevTrack);
      setIsPlaying(true);
    }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration || 0);
    }
  };

  const handleEnded = () => {
    recordCompletion(currentTrack.id);
    if (taskTarget > 0) {
      if (taskProgress < taskTarget) {
        setTaskProgress(prev => prev + 1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
          audioRef.current.play();
        }
      } else {
        setIsPlaying(false);
        setTaskTarget(0);
        setTaskProgress(0);
        alert("功德圆满，修行完成。");
      }
    } else if (!isSingleLoop) {
      handleNext();
    }
  };

  const updateTaskTarget = (target: number) => {
    if (taskProgress === 0) {
        setTaskProgress(1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
        }
    }
    setTaskTarget(target);
    setIsSingleLoop(false);
    setIsPlaying(true);
    if (audioRef.current && audioRef.current.paused) {
      audioRef.current.play();
    }
  };

  const stopTask = () => {
    setTaskTarget(0);
    setTaskProgress(0);
    setIsPlaying(false);
  };

  const renderContent = () => {
    switch (view) {
      case View.PLAYER:
        return (
          <Player 
            track={currentTrack} 
            isPlaying={isPlaying} 
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            currentTime={currentTime}
            duration={duration}
            volume={volume}
            setVolume={setVolume}
          />
        );
      case View.PLAYLIST:
        return (
          <Playlist 
            currentTrackId={currentTrack.id} 
            onTrackSelect={handleTrackSelect}
            onBack={() => setView(View.PLAYER)}
          />
        );
      case View.TIMER:
        return (
          <Settings 
            currentTrack={currentTrack} 
            onBack={() => setView(View.PLAYER)}
            onNext={handleNext}
            onPrev={handlePrev}
            onUpdateTarget={updateTaskTarget}
            onStopTask={stopTask}
            taskProgress={taskProgress}
            taskTarget={taskTarget}
            currentTime={currentTime}
            duration={duration}
          />
        );
      case View.PROFILE:
        return (
          <Profile 
            stats={stats} 
            zenQuote={zenQuote} 
            onRefreshQuote={() => getZenQuote().then(setZenQuote)}
            onOpenLogoDesign={() => setView(View.LOGO_DESIGN)}
          />
        );
      case View.LOGO_DESIGN:
        return (
          <LogoDesign onBack={() => setView(View.PROFILE)} />
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col w-full max-w-md mx-auto min-h-screen relative shadow-2xl bg-zen-dark overflow-hidden">
      {showSplash && <SplashScreen onComplete={() => setShowSplash(false)} />}

      <div className="fixed inset-0 pointer-events-none opacity-20 bg-wood-grain mix-blend-overlay z-0"></div>

      <audio 
        ref={audioRef}
        src={currentTrack.audioUrl}
        onTimeUpdate={handleTimeUpdate}
        onEnded={handleEnded}
        loop={isSingleLoop && taskTarget === 0} 
      />

      {!showSplash && view !== View.PROFILE && view !== View.LOGO_DESIGN && (
        <header className="flex items-center justify-between px-6 py-5 sticky top-0 z-20 bg-gradient-to-b from-[#0f0a06] to-transparent">
          <button className="flex items-center justify-center w-10 h-10 rounded-full text-gold-main/80 active:text-gold-light transition-colors">
            <span className="material-symbols-outlined text-[26px]">settings</span>
          </button>
          <div className="flex flex-col items-center">
            <h2 className="text-gold-light text-xl font-medium tracking-[0.3em] font-serif">守月亮念佛机</h2>
            <div className="h-[1px] w-8 bg-gradient-to-r from-transparent via-gold-dark to-transparent mt-1"></div>
          </div>
          <button className="flex items-center justify-center w-10 h-10 rounded-full text-gold-main/80 active:text-gold-light transition-colors">
            <span className="material-symbols-outlined text-[26px]">palette</span>
          </button>
        </header>
      )}

      {!showSplash && renderContent()}

      {!showSplash && view !== View.LOGO_DESIGN && <BottomNav activeView={view} onViewChange={setView} />}
    </div>
  );
};

