import React from 'react';
import { TRACKS } from '../constants';

interface ProfileProps {
  stats: {
    installDate: string;
    totalCompletions: number;
    dailyLogs: { [date: string]: { [trackId: string]: number } };
  };
  zenQuote: string;
  onRefreshQuote: () => void;
}

const Profile: React.FC<ProfileProps> = ({ stats, zenQuote, onRefreshQuote }) => {
  const today = new Date().toISOString().split('T')[0];
  const todayStats: Record<string, number> = stats.dailyLogs[today] || {};

  const calculateDays = () => {
    const start = new Date(stats.installDate).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    return diff + 1;
  };

  const todayItems = (Object.entries(todayStats) as [string, number][])
    .map(([trackId, count]) => {
      const track = TRACKS.find(t => t.id === trackId);
      return {
        title: track?.title || '自定义曲目',
        subtitle: track?.subtitle || '',
        count
      };
    })
    .sort((a, b) => b.count - a.count);

  const totalToday = todayItems.reduce((acc, curr) => acc + curr.count, 0);

  return (
    <div className="flex-1 flex flex-col overflow-y-auto pb-32">
      <div className="px-8 pt-10 pb-6 flex flex-col items-center text-center">
        <div className="relative mb-6">
          <div className="absolute inset-[-10px] bg-gold-main/10 blur-2xl rounded-full"></div>
          <div className="w-24 h-24 rounded-full badge-texture flex items-center justify-center text-[#4a3b18] border-2 border-gold-dark/30 shadow-2xl relative z-10">
             <span className="material-symbols-outlined text-5xl">person</span>
          </div>
        </div>

        <div className="space-y-4">
          <h3 className="text-2xl font-bold text-gold-light tracking-[0.2em] font-serif uppercase">念佛弟子</h3>
          <div className="relative px-4 py-3">
             <span className="absolute top-0 left-0 text-gold-main/20 text-4xl font-serif">“</span>
             <p className="text-stone-400 text-sm tracking-widest leading-relaxed italic px-4 font-serif">
               {zenQuote}
             </p>
             <span className="absolute bottom-0 right-0 text-gold-main/20 text-4xl font-serif">”</span>
          </div>
          <button 
            onClick={onRefreshQuote}
            className="text-[10px] text-gold-main/40 uppercase tracking-[0.5em] hover:text-gold-main transition-colors"
          >
            Refresh Wisdom
          </button>
        </div>
      </div>

      <div className="px-6 grid grid-cols-2 gap-4 mb-8">
        <div className="p-5 bg-gradient-to-br from-surface-dark to-black border border-white/5 rounded-3xl shadow-xl flex flex-col items-center justify-center">
          <p className="text-gold-main text-3xl font-bold font-display tracking-tighter">{calculateDays()}</p>
