import React, { useState, useEffect, useRef } from 'react';
import { View, Track } from './types';
import { TRACKS } from './constants';
import BottomNav from './components/BottomNav';
import Player from './components/Player';
import Playlist from './components/Playlist';
import Settings from './components/Settings';
import Profile from './components/Profile';
import SplashScreen from './components/SplashScreen';
import LogoDesign from './components/LogoDesign';
import { getZenQuote } from './services/geminiService';

const STATS_KEY = 'zen_chant_user_stats';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [view, setView] = useState<View>(View.PLAYER);
  const [currentTrack, setCurrentTrack] = useState<Track>(TRACKS[0]);
  const [isPlaying, setIsPlaying] = useState(true); // 默认进入即播放
  const [zenQuote, setZenQuote] = useState("静能生慧，定能生福。");
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.65);
  const [isSingleLoop, setIsSingleLoop] = useState(true); 

  const [taskTarget, setTaskTarget] = useState(0);
  const [taskProgress, setTaskProgress] = useState(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // 初始化统计数据
  const [stats, setStats] = useState(() => {
    const saved = localStorage.getItem(STATS_KEY);
    if (saved) return JSON.parse(saved);
    return {
      installDate: new Date().toISOString(),
      totalCompletions: 0,
      dailyLogs: {} 
    };
  });

  useEffect(() => {
    getZenQuote().then(setZenQuote);
  }, []);

  useEffect(() => {
    localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  }, [stats]);

  const recordCompletion = (trackId: string) => {
    const today = new Date().toISOString().split('T')[0];
    setStats(prev => {
      const newDailyLogs = { ...prev.dailyLogs };
      if (!newDailyLogs[today]) newDailyLogs[today] = {};
      newDailyLogs[today][trackId] = (newDailyLogs[today][trackId] || 0) + 1;

      return {
        ...prev,
        totalCompletions: prev.totalCompletions + 1,
        dailyLogs: newDailyLogs
      };
    });
  };

  const isTaskActive = taskTarget > 0;

  useEffect(() => {
    if (!audioRef.current || showSplash) return;
    if (isPlaying) {
      audioRef.current.play().catch(() => setIsPlaying(false));
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying, showSplash]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume, currentTrack, view]);

  useEffect(() => {
    if (audioRef.current && !showSplash) {
      audioRef.current.load();
      if (isPlaying) {
        audioRef.current.play().catch(() => {});
      }
    }
    setTaskProgress(isTaskActive ? 1 : 0);
  }, [currentTrack.id, showSplash]);

  const handleTrackSelect = (track: Track) => {
    setCurrentTrack(track);
    setIsPlaying(true);
    setView(View.PLAYER);
    setTaskTarget(0);
    setTaskProgress(0);
  };

  const handleNext = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const nextTrack = TRACKS[(idx + 1) % TRACKS.length];
      setCurrentTrack(nextTrack);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const prevTrack = TRACKS[(idx - 1 + TRACKS.length) % TRACKS.length];
      setCurrentTrack(prevTrack);
      setIsPlaying(true);
    }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration || 0);
    }
  };

  const handleEnded = () => {
    recordCompletion(currentTrack.id);
    if (taskTarget > 0) {
      if (taskProgress < taskTarget) {
        setTaskProgress(prev => prev + 1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
          audioRef.current.play();
        }
      } else {
        setIsPlaying(false);
        setTaskTarget(0);
        setTaskProgress(0);
        alert("功德圆满，修行完成。");
      }
    } else if (!isSingleLoop) {
      handleNext();
    }
  };

  const updateTaskTarget = (target: number) => {
    if (taskProgress === 0) {
        setTaskProgress(1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
        }
    }
    setTaskTarget(target);
    setIsSingleLoop(false);
    setIsPlaying(true);
    if (audioRef.current && audioRef.current.paused) {
      audioRef.current.play();
    }
  };

  const stopTask = () => {
    setTaskTarget(0);
    setTaskProgress(0);
    setIsPlaying(false);
  };

  const renderContent = () => {
    switch (view) {
      case View.PLAYER:
        return (
          <Player 
            track={currentTrack} 
            isPlaying={isPlaying} 
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            currentTime={currentTime}
            duration={duration}
            volume={volume}
            setVolume={setVolume}
          />
        );
      case View.PLAYLIST:
        return (
          <Playlist 
            currentTrackId={currentTrack.id} 
            onTrackSelect={handleTrackSelect}
            onBack={() => setView(View.PLAYER)}
          />
        );
      case View.TIMER:
        return (
          <Settings 
            currentTrack={currentTrack} 
            onBack={() => setView(View.PLAYER)}
            onNext={handleNext}
            onPrev={handlePrev}
            onUpdateTarget={updateTaskTarget}
            onStopTask={stopTask}
            taskProgress={taskProgress}
            taskTarget={taskTarget}
            currentTime={currentTime}
            duration={duration}
          />
        );
      case View.PROFILE:
        return (
          <Profile 
            stats={stats} 
            zenQuote={zenQuote} 
            onRefreshQuote={() => getZenQuote().then(setZenQuote)}
            onOpenLogoDesign={() => setView(View.LOGO_DESIGN as any)}
          />
        );
      case 'LOGO_DESIGN' as any:
        return (
          <LogoDesign onBack={() => setView(View.PROFILE)} />
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col w-full max-w-md mx-auto min-h-screen relative shadow-2xl bg-zen-dark overflow-hidden">
      {showSplash && <SplashScreen onComplete={() => setShowSplash(false)} />}

      <div className="fixed inset-0 pointer-events-none opacity-20 bg-wood-grain mix-blend-overlay z-0"></div>

      <audio 
        ref={audioRef}
        src={currentTrack.audioUrl}
        onTimeUpdate={handleTimeUpdate}
        onEnded={handleEnded}
        loop={isSingleLoop && taskTarget === 0} 
      />

      {/* 顶栏已移除，使界面更加纯粹 */}

      {!showSplash && renderContent()}

      {!showSplash && view !== ('LOGO_DESIGN' as any) && <BottomNav activeView={view} onViewChange={setView} />}
    </div>
  );
};

export default App;

import React, { useRef, useEffect } from 'react';
import { Track } from '../types';

interface PlayerProps {
  track: Track;
  isPlaying: boolean;
  onTogglePlay: () => void;
  onNext: () => void;
  onPrev: () => void;
  currentTime: number;
  duration: number;
  volume: number;
  setVolume: (vol: number) => void;
}

const Player: React.FC<PlayerProps> = ({ 
  track, isPlaying, onTogglePlay, onNext, onPrev, 
  currentTime, duration, volume, setVolume
}) => {
  // 用于记录静音前的音量，默认为当前音量或 0.65
  const lastVolumeRef = useRef(volume > 0 ? volume : 0.65);

  // 当音量大于 0 时，实时更新记录值
  useEffect(() => {
    if (volume > 0) {
      lastVolumeRef.current = volume;
    }
  }, [volume]);

  const handleMuteToggle = () => {
    if (volume > 0) {
      setVolume(0);
    } else {
      setVolume(lastVolumeRef.current);
    }
  };

  const formatSeconds = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60);
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const progressPercent = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <main className="flex-1 flex flex-col justify-between px-8 pt-12 pb-28 relative z-10">
      {/* 核心展示区 */}
      <div className="flex-1 flex flex-col justify-center items-center py-4">
        <div className="relative w-full max-w-[340px] flex items-center justify-center">

          <button 
            onClick={onPrev}
            className="absolute -left-10 z-30 w-14 h-14 rounded-full flex items-center justify-center text-gold-main/50 hover:text-gold-light hover:bg-white/5 active:scale-90 transition-all focus:outline-none backdrop-blur-sm border border-white/5 shadow-lg group"
            aria-label="上一曲"
          >
            <span className="material-symbols-outlined text-[40px] transition-transform group-hover:-translate-x-1">chevron_left</span>
          </button>

          <div className="relative w-64 h-64 sm:w-80 sm:h-80">
            <div className={`absolute inset-0 rounded-full bg-gold-main/20 blur-[50px] transition-all duration-1000 ${isPlaying ? 'scale-110 opacity-40' : 'scale-95 opacity-0'}`}></div>

            <div className="relative w-full h-full rounded-full gold-ring shadow-[0_0_60px_rgba(0,0,0,0.6)]">
              <div className="w-full h-full rounded-full overflow-hidden bg-[#0c0805] relative flex items-center justify-center border-[4px] border-[#1A0F08]">
                <img 
                  alt={track.title}
                  className={`w-full h-full object-cover relative z-10 transition-transform duration-[10000ms] ease-in-out ${isPlaying ? 'scale-110' : 'scale-100'}`} 
                  src={track.imageUrl} 
                />
                <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-transparent via-white/5 to-transparent pointer-events-none z-20"></div>
              </div>
            </div>
          </div>

          <button 
            onClick={onNext}
            className="absolute -right-10 z-30 w-14 h-14 rounded-full flex items-center justify-center text-gold-main/50 hover:text-gold-light hover:bg-white/5 active:scale-90 transition-all focus:outline-none backdrop-blur-sm border border-white/5 shadow-lg group"
            aria-label="下一曲"
          >
            <span className="material-symbols-outlined text-[40px] transition-transform group-hover:translate-x-1">chevron_right</span>
          </button>
        </div>

        <div className="mt-10 text-center space-y-2">
          <h2 className="text-gold-light text-2xl font-bold tracking-[0.25em] font-serif drop-shadow-md">{track.title}</h2>
          <p className="text-stone-500 text-sm font-light tracking-[0.2em] font-serif italic opacity-80">{track.subtitle}</p>
        </div>
      </div>

      {/* 底部控制台 */}
      <div className="w-full max-w-[320px] mx-auto space-y-12">

        {/* 1. 播放进度 */}
        <div className="space-y-3">
          <div className="relative h-1 w-full bg-stone-900/80 rounded-full overflow-visible">
            <div 
              className="absolute top-0 left-0 h-full bg-gold-metal shadow-[0_0_12px_rgba(212,175,55,0.6)] transition-all duration-300 rounded-full" 
              style={{ width: `${progressPercent}%` }}
            />
            <div 
              className="absolute top-1/2 -translate-y-1/2 w-2 h-2 bg-white rounded-full shadow-[0_0_8px_white] transition-all duration-300"
              style={{ left: `${progressPercent}%`, transform: `translate(-50%, -50%)` }}
            ></div>
          </div>
          <div className="flex justify-between text-[10px] text-stone-600 font-display tracking-widest font-medium">
            <span>{formatSeconds(currentTime)}</span>
            <span>{formatSeconds(duration)}</span>
          </div>
        </div>

        {/* 2. 核心控制组合：播放与音量 */}
        <div className="flex flex-col items-center gap-10">
          <div className="relative">
            {isPlaying && (
              <div className="absolute inset-0 rounded-full border-2 border-gold-main/10 animate-ping-slow scale-150 pointer-events-none"></div>
            )}
            <button 
              onClick={onTogglePlay}
              className="relative w-24 h-24 rounded-full bg-gold-metal flex items-center justify-center shadow-[0_15px_45px_rgba(0,0,0,0.7),inset_0_-4px_8px_rgba(0,0,0,0.4)] active:scale-95 transition-all border-4 border-[#2C1E12] z-10 group overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-tr from-black/20 via-transparent to-white/10 opacity-50 group-hover:opacity-100 transition-opacity pointer-events-none"></div>
              <span className="material-symbols-outlined text-[#3d2b1f] text-[68px] select-none transition-transform group-hover:scale-110">
                {isPlaying ? 'pause' : 'play_arrow'}
              </span>
            </button>
          </div>

          {/* 音量控制 - 采用原生 input 以确保 100% 可用性 */}
          <div className="w-full flex items-center gap-4 px-5 py-4 bg-black/40 backdrop-blur-md rounded-2xl border border-white/5 shadow-inner group">
            {/* 静音/取消静音按钮 */}
            <button 
              onClick={handleMuteToggle}
              className="flex items-center justify-center focus:outline-none transition-transform active:scale-90"
              title={volume === 0 ? "取消静音" : "静音"}
            >
              <span className={`material-symbols-outlined text-[20px] font-light transition-colors ${volume === 0 ? 'text-red-500/80' : 'text-stone-600 hover:text-gold-main'}`}>
                {volume === 0 ? 'volume_off' : volume < 0.5 ? 'volume_down' : 'volume_up'}
              </span>
            </button>

            <div className="flex-1 relative flex items-center h-4">
              {/* 背景装饰条 */}
              <div className="absolute w-full h-1 bg-stone-800 rounded-full pointer-events-none"></div>
              {/* 激活装饰条 */}
              <div 
                className="absolute h-1 bg-gold-dark/60 rounded-full pointer-events-none transition-all duration-75"
                style={{ width: `${volume * 100}%` }}
              ></div>
              {/* 实际的透明 Input，覆盖在上方处理交互 */}
              <input 
                type="range"
                min="0"
                max="1"
                step="0.01"
                value={volume}
                onChange={(e) => setVolume(parseFloat(e.target.value))}
                className="absolute w-full h-6 opacity-0 cursor-pointer z-10"
              />
              {/* 视觉滑块点 */}
              <div 
                className="absolute w-4 h-4 bg-gold-light rounded-full border-2 border-gold-dark shadow-xl transition-all duration-75 pointer-events-none"
                style={{ left: `calc(${volume * 100}% - 8px)` }}
              ></div>
            </div>
            <span className="text-[10px] text-stone-600 font-display w-6 text-right">{Math.round(volume * 100)}</span>
          </div>
        </div>
      </div>
    </main>
  );
};

