import React from 'react';
import { Track } from '../types';

interface SettingsProps {
  currentTrack: Track;
  onNext: () => void;
  onPrev: () => void;
  onUpdateTarget: (target: number) => void;
  onStopTask: () => void;
  taskProgress: number;
  taskTarget: number;
  currentTime: number;
  duration: number;
}

const Settings: React.FC<SettingsProps> = ({ 
  currentTrack, onNext, onPrev, onUpdateTarget, onStopTask, 
  taskProgress, taskTarget, currentTime, duration 
}) => {
  const presets = [7, 21, 49, 108];
  const isTaskActive = taskTarget > 0;

  const size = 300;
  const radius = 110;
  const center = size / 2;
  const dashArray = 2 * Math.PI * radius;

  const currentRepProgress = duration > 0 ? currentTime / duration : 0;
  const totalProgressRatio = isTaskActive 
    ? Math.min(((taskProgress - 1) + currentRepProgress) / taskTarget, 1) 
    : 0;

  const dashOffset = dashArray * (1 - totalProgressRatio);

  const renderTicks = () => {
    if (!isTaskActive) return null;
    const ticks = [];
    const n = taskTarget;
    for (let i = 0; i < n; i++) {
      const angle = (i * 360 / n) - 90;
      const angleRad = (angle * Math.PI) / 180;
      const innerR = radius - 8;
      const outerR = radius + 2;
      const x1 = center + innerR * Math.cos(angleRad);
      const y1 = center + innerR * Math.sin(angleRad);
      const x2 = center + outerR * Math.cos(angleRad);
      const y2 = center + outerR * Math.sin(angleRad);
      const tickProgressRatio = i / n;
      const isPassed = totalProgressRatio >= tickProgressRatio;
      const isCurrent = i === (taskProgress - 1);
      ticks.push(
        <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke={isPassed ? "#D4AF37" : (isCurrent ? "#F9Eea5" : "rgba(212, 175, 55, 0.1)")} strokeWidth={isPassed ? "2" : "1"} strokeLinecap="round" className="transition-all duration-300" />
      );
    }
    return ticks;
  };

  return (
    <div className="flex flex-col min-h-screen bg-zen-dark pb-32 overflow-x-hidden pt-12">
      {/* 移除了 header，让圆环占据视觉中心 */}
      <div className="flex-1 flex flex-col items-center justify-around px-6">
        <div className="flex flex-col items-center gap-6 w-full">
          <div className="flex items-center justify-between w-full max-w-[320px]">
            <button onClick={onPrev} className="w-10 h-10 rounded-full flex items-center justify-center text-gold-dark/40 hover:text-gold-main active:scale-90 transition-all">
              <span className="material-symbols-outlined text-4xl">chevron_left</span>
            </button>
            <div className="relative">
              <div className={`absolute inset-[-10px] bg-gold-main/5 blur-3xl rounded-full transition-opacity duration-1000 ${isTaskActive ? 'opacity-100' : 'opacity-0'}`}></div>
              <div className={`w-24 h-24 rounded-full border-2 p-1 bg-[#0c0805] overflow-hidden relative z-10 transition-all duration-500 ${isTaskActive ? 'border-gold-main shadow-[0_0_30px_rgba(212,175,55,0.2)]' : 'border-white/10'}`}>
                <img className="w-full h-full rounded-full object-cover grayscale-[0.1]" src={currentTrack.imageUrl} alt={currentTrack.title} />
              </div>
            </div>
            <button onClick={onNext} className="w-10 h-10 rounded-full flex items-center justify-center text-gold-dark/40 hover:text-gold-main active:scale-90 transition-all">
              <span className="material-symbols-outlined text-4xl">chevron_right</span>
            </button>
          </div>
          <div className="text-center">
            <h3 className="text-gold-light font-bold text-xl tracking-[0.2em] font-serif">{currentTrack.title}</h3>
            <p className="text-stone-600 text-[10px] mt-1 tracking-[0.4em] font-serif uppercase opacity-60">Synchronized Flow</p>
          </div>
        </div>

        <div 
          className="relative flex items-center justify-center cursor-pointer group"
          style={{ width: size, height: size }}
          onClick={() => isTaskActive && onStopTask()}
        >
          <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="absolute inset-0">
            <defs>
              <linearGradient id="goldProgressGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#fcf6ba" /><stop offset="50%" stopColor="#bf953f" /><stop offset="100%" stopColor="#aa771c" />
              </linearGradient>
            </defs>
            <circle cx={center} cy={center} r={radius} fill="transparent" stroke="rgba(255,255,255,0.02)" strokeWidth="1" />
            {renderTicks()}
            <circle cx={center} cy={center} r={radius} fill="transparent" stroke="url(#goldProgressGrad)" strokeWidth="5" strokeDasharray={dashArray} strokeDashoffset={dashOffset} strokeLinecap="round" transform={`rotate(-90 ${center} ${center})`} className="transition-all duration-150 ease-linear" />
          </svg>
          <div className="flex flex-col items-center z-10 select-none">
            <div className="flex items-baseline gap-1">
              <span className="text-7xl font-bold text-transparent bg-clip-text bg-gold-metal tracking-tighter drop-shadow-2xl">{taskProgress || 0}</span>
              {isTaskActive && <span className="text-2xl font-semibold text-gold-main/20">/{taskTarget}</span>}
            </div>
            <p className="text-[10px] font-bold text-gold-main/50 mt-4 uppercase tracking-[0.6em] font-serif">{isTaskActive ? '当前修持' : '请礼请遍数'}</p>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 w-full max-w-[340px] px-2 mb-4">
          {presets.map((p) => (
            <button key={p} onClick={() => onUpdateTarget(p)} className={`h-16 rounded-2xl flex flex-col items-center justify-center transition-all duration-300 border font-serif active:scale-95 relative overflow-hidden group ${taskTarget === p ? 'bg-gold-metal text-[#3d2b1f] border-gold-light font-bold shadow-xl scale-[1.02]' : 'bg-white/[0.02] text-stone-500 border-white/5 hover:bg-white/[0.05]'}`}>
              <span className="text-xl tracking-widest relative z-10">{p}遍</span>
              {taskTarget === p && <div className="absolute inset-0 bg-white/10 mix-blend-overlay"></div>}
            </button>
          ))}
        </div>
        <div className="mt-2 text-stone-700 text-[10px] tracking-[0.4em] font-serif text-center opacity-40 italic">修持功德 · 普皆回向</div>
      </div>
    </div>
  );
};

