import React, { useState, useEffect, useRef } from 'react';
import { View, Track } from './types';
import { TRACKS } from './constants';
import BottomNav from './components/BottomNav';
import Player from './components/Player';
import Playlist from './components/Playlist';
import Settings from './components/Settings';
import Profile from './components/Profile';
import { getZenQuote, ZenQuote } from './services/zenQuoteService';

const STATS_KEY = 'zen_chant_user_stats';

const App: React.FC = () => {
  const [view, setView] = useState<View>(View.PLAYER);
  const [currentTrack, setCurrentTrack] = useState<Track>(TRACKS[0]);
  const [isPlaying, setIsPlaying] = useState(true); 
  const [zenQuote, setZenQuote] = useState<ZenQuote>(getZenQuote());
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.65);
  const [isSingleLoop, setIsSingleLoop] = useState(true); 

  const [taskTarget, setTaskTarget] = useState(0);
  const [taskProgress, setTaskProgress] = useState(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // 初始化统计数据
  const [stats, setStats] = useState(() => {
    const saved = localStorage.getItem(STATS_KEY);
    if (saved) return JSON.parse(saved);
    return {
      installDate: new Date().toISOString(),
      totalCompletions: 0,
      dailyLogs: {} 
    };
  });

  useEffect(() => {
    localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  }, [stats]);

  const recordCompletion = (trackId: string) => {
    const today = new Date().toISOString().split('T')[0];
    setStats(prev => {
      const newDailyLogs = { ...prev.dailyLogs };
      if (!newDailyLogs[today]) newDailyLogs[today] = {};
      newDailyLogs[today][trackId] = (newDailyLogs[today][trackId] || 0) + 1;

      return {
        ...prev,
        totalCompletions: prev.totalCompletions + 1,
        dailyLogs: newDailyLogs
      };
    });
  };

  const isTaskActive = taskTarget > 0;

  useEffect(() => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.play().catch(() => setIsPlaying(false));
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume, currentTrack, view]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.load();
      if (isPlaying) {
        audioRef.current.play().catch(() => {});
      }
    }
    setTaskProgress(isTaskActive ? 1 : 0);
  }, [currentTrack.id]);

  const handleTrackSelect = (track: Track) => {
    setCurrentTrack(track);
    setIsPlaying(true);
    setView(View.PLAYER);
    setTaskTarget(0);
    setTaskProgress(0);
  };

  const handleNext = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const nextTrack = TRACKS[(idx + 1) % TRACKS.length];
      setCurrentTrack(nextTrack);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const prevTrack = TRACKS[(idx - 1 + TRACKS.length) % TRACKS.length];
      setCurrentTrack(prevTrack);
      setIsPlaying(true);
    }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration || 0);
    }
  };

  const handleEnded = () => {
    recordCompletion(currentTrack.id);
    if (taskTarget > 0) {
      if (taskProgress < taskTarget) {
        setTaskProgress(prev => prev + 1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
          audioRef.current.play();
        }
      } else {
        setIsPlaying(false);
        setTaskTarget(0);
        setTaskProgress(0);
        alert("功德圆满，修行完成。");
      }
    } else if (!isSingleLoop) {
      handleNext();
    }
  };

  const updateTaskTarget = (target: number) => {
    if (taskProgress === 0) {
        setTaskProgress(1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
        }
    }
    setTaskTarget(target);
    setIsSingleLoop(false);
    setIsPlaying(true);
    if (audioRef.current && audioRef.current.paused) {
      audioRef.current.play();
    }
  };

  const stopTask = () => {
    setTaskTarget(0);
    setTaskProgress(0);
    setIsPlaying(false);
  };

  const handleRefreshQuote = () => {
    setZenQuote(getZenQuote());
  };

  const renderContent = () => {
    switch (view) {
      case View.PLAYER:
        return (
          <Player 
            track={currentTrack} 
            isPlaying={isPlaying} 
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            currentTime={currentTime}
            duration={duration}
            volume={volume}
            setVolume={setVolume}
          />
        );
      case View.PLAYLIST:
        return (
          <Playlist 
            currentTrackId={currentTrack.id} 
            onTrackSelect={handleTrackSelect}
          />
        );
      case View.TIMER:
        return (
          <Settings 
            currentTrack={currentTrack} 
            onNext={handleNext}
            onPrev={handlePrev}
            onUpdateTarget={updateTaskTarget}
            onStopTask={stopTask}
            taskProgress={taskProgress}
            taskTarget={taskTarget}
            currentTime={currentTime}
            duration={duration}
          />
        );
      case View.PROFILE:
        return (
          <Profile 
            stats={stats} 
            zenQuote={zenQuote} 
            onRefreshQuote={handleRefreshQuote}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col w-full max-w-md mx-auto min-h-screen relative shadow-2xl bg-zen-dark overflow-hidden">
      <div className="fixed inset-0 pointer-events-none opacity-20 bg-wood-grain mix-blend-overlay z-0"></div>

      <audio 
        ref={audioRef}
        src={currentTrack.audioUrl}
        onTimeUpdate={handleTimeUpdate}
        onEnded={handleEnded}
        loop={isSingleLoop && taskTarget === 0} 
      />

      {renderContent()}

      <BottomNav activeView={view} onViewChange={setView} />
    </div>
  );
};

export default App;

import React from 'react';
import { TRACKS } from '../constants';
import { ZenQuote } from '../services/zenQuoteService';

interface ProfileProps {
  stats: {
    installDate: string;
    totalCompletions: number;
    dailyLogs: { [date: string]: { [trackId: string]: number } };
  };
  zenQuote: ZenQuote;
  onRefreshQuote: () => void;
}

const Profile: React.FC<ProfileProps> = ({ stats, zenQuote, onRefreshQuote }) => {
  const today = new Date().toISOString().split('T')[0];
  const todayStats: Record<string, number> = stats.dailyLogs[today] || {};

  const calculateDays = () => {
    const start = new Date(stats.installDate).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    return diff + 1;
  };

  const todayItems = (Object.entries(todayStats) as [string, number][])
    .map(([trackId, count]) => {
      const track = TRACKS.find(t => t.id === trackId);
      return {
        title: track?.title || '自定义曲目',
        subtitle: track?.subtitle || '',
        count
      };
    })
    .sort((a, b) => b.count - a.count);

  const totalToday = todayItems.reduce((acc, curr) => acc + curr.count, 0);

  return (
    <div className="flex-1 flex flex-col overflow-y-auto pb-32 pt-16">
      <div className="px-8 pb-6 flex flex-col items-center text-center">
        <div className="relative mb-6">
          <div className="absolute inset-[-10px] bg-gold-main/10 blur-2xl rounded-full"></div>
          <div className="w-24 h-24 rounded-full badge-texture flex items-center justify-center text-[#4a3b18] border-2 border-gold-dark/30 shadow-2xl relative z-10">
             <span className="material-symbols-outlined text-5xl">person</span>
          </div>
        </div>

        <div className="space-y-4 w-full">
          <h3 className="text-2xl font-bold text-gold-light tracking-[0.2em] font-serif uppercase">念佛弟子</h3>

          <div className="relative px-2 py-3 flex flex-col items-center">
             <span className="absolute top-0 left-0 text-gold-main/20 text-4xl font-serif">“</span>
             <div className="px-6 py-2">
                <p className="text-stone-300 text-[15px] tracking-widest leading-relaxed font-serif text-center">
                  {zenQuote.text}
                </p>
                <p className="text-gold-main/60 text-[11px] tracking-widest font-serif mt-3 text-right">
                  —— {zenQuote.source}
                </p>
             </div>
             <span className="absolute bottom-0 right-0 text-gold-main/20 text-4xl font-serif">”</span>
          </div>

          <button 
            onClick={onRefreshQuote} 
            className="text-[10px] text-gold-main/40 uppercase tracking-[0.5em] hover:text-gold-main transition-colors mt-2"
          >
            刷新智慧
          </button>
        </div>
      </div>

      <div className="px-6 grid grid-cols-2 gap-4 mb-8">
        <div className="p-5 bg-gradient-to-br from-surface-dark to-black border border-white/5 rounded-3xl shadow-xl flex flex-col items-center justify-center">
          <p className="text-gold-main text-3xl font-bold font-display tracking-tighter">{calculateDays()}</p>
          <p className="text-[10px] text-stone-500 uppercase tracking-widest mt-2">累计天数</p>
        </div>
        <div className="p-5 bg-gradient-to-br from-surface-dark to-black border border-white/5 rounded-3xl shadow-xl flex flex-col items-center justify-center">
          <p className="text-gold-main text-3xl font-bold font-display tracking-tighter">{stats.totalCompletions >= 10000 ? (stats.totalCompletions / 10000).toFixed(1) + 'w' : stats.totalCompletions}</p>
          <p className="text-[10px] text-stone-500 uppercase tracking-widest mt-2">累计遍数</p>
        </div>
      </div>

      <div className="px-6 space-y-4">
        <div className="flex items-center justify-between px-2">
           <h4 className="text-gold-light text-sm font-bold tracking-[0.2em] font-serif uppercase border-l-2 border-gold-main pl-3">今日功课</h4>
           <div className="flex items-baseline gap-1">
              <span className="text-gold-main text-lg font-bold">{totalToday}</span>
              <span className="text-stone-600 text-[10px] uppercase">Rounds Today</span>
           </div>
        </div>

        <div className="bg-black/20 rounded-3xl border border-white/5 overflow-hidden">
          {todayItems.length > 0 ? (
            <div className="divide-y divide-white/5">
              {todayItems.map((item, idx) => (
                <div key={idx} className="flex items-center justify-between p-4 hover:bg-white/[0.02] transition-colors">
                  <div className="flex flex-col">
                    <span className="text-stone-200 text-sm font-medium tracking-wide">{item.title}</span>
                    <span className="text-stone-600 text-[10px] tracking-widest mt-0.5">{item.subtitle}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-gold-main font-bold text-lg">{item.count}</span>
                    <span className="text-stone-700 text-[10px] font-serif">遍</span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="py-12 flex flex-col items-center justify-center opacity-20">
               <span className="material-symbols-outlined text-4xl mb-2">hourglass_empty</span>
               <p className="text-xs tracking-[0.3em] uppercase">今日暂无记录</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Profile;

