      const cacheName = 'zen-chant-audio';
      const cache = await caches.open(cacheName);
      let downloadedCount = 0;

      for (const trackUrl of TRACKS) {
        try {
          // If the audio URL contains spaces, replace them with "%20"
          const url = trackUrl.replace(/ /g, '%20');
          const response = await fetch(url);
          if (!response.ok) {
            throw new Error(`Failed to fetch ${url}: ${response.status}`);
          }

          await cache.put(url, response.clone());
          downloadedCount++;
          setSyncProgress((downloadedCount / TRACKS.length) * 100);

        } catch (error) {
          console.error(`Error downloading ${trackUrl}:`, error);
          setSyncStatus(`Sync Failed: ${error}`);
          break; // Stop on error
        }
      }

      if (downloadedCount === TRACKS.length) {
        setSyncStatus('Synced');
      }
    } catch (error) {
      console.error('Overall download error:', error);
      setSyncStatus(`Sync Failed: ${error}`);
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <div>
      {/*... Other playlist content ...*/}

      <button onClick={handleOfflineDownload} disabled={isSyncing}>
        {isSyncing ? `Syncing (${syncProgress.toFixed(0)}%)` : syncStatus === 'Synced' ? 'Synced' : 'Offline Download'}
      </button>

      {/*... Display Sync Status and Progress ...*/}
      {isSyncing && (
        <div>
          <progress value={syncProgress} max="100"></progress>
        </div>
      )}
    </div>
  );
};

