import React, { useState, useEffect, useRef } from 'react';
import { View, Track } from './types';
import { TRACKS } from './constants';
import BottomNav from './components/BottomNav';
import Player from './components/Player';
import Playlist from './components/Playlist';
import Settings from './components/Settings';
import Profile from './components/Profile';
import MeritAnimation from './components/MeritAnimation';
import ShareCard from './components/ShareCard';
import { getZenQuote, ZenQuote } from './services/zenQuoteService';

const STATS_KEY = 'zen_chant_user_stats';
const CONFIG_KEY = 'zen_chant_config';

const App: React.FC = () => {
  const [view, setView] = useState<View>(View.PLAYER);
  const [currentTrack, setCurrentTrack] = useState<Track>(TRACKS[0]);
  const [isPlaying, setIsPlaying] = useState(true); 
  const [zenQuote, setZenQuote] = useState<ZenQuote>(getZenQuote());
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.65);
  const [isSingleLoop, setIsSingleLoop] = useState(true); 

  // 功德目标与进度
  const [taskTarget, setTaskTarget] = useState(0);
  const [taskProgress, setTaskProgress] = useState(0);
  const [showMerit, setShowMerit] = useState(false);
  const [showShare, setShowShare] = useState(false);

  // 配置项
  const [isLargeText, setIsLargeText] = useState(() => {
    const saved = localStorage.getItem(CONFIG_KEY);
    return saved ? JSON.parse(saved).isLargeText : false;
  });

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    localStorage.setItem(CONFIG_KEY, JSON.stringify({ isLargeText }));
  }, [isLargeText]);

  // 初始化统计数据
  const [stats, setStats] = useState(() => {
    const saved = localStorage.getItem(STATS_KEY);
    if (saved) return JSON.parse(saved);
    return {
      installDate: new Date().toISOString(),
      totalCompletions: 0,
      dailyLogs: {} 
    };
  });

  useEffect(() => {
    localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  }, [stats]);

  const recordCompletion = (trackId: string) => {
    const today = new Date().toISOString().split('T')[0];
    setStats(prev => {
      const newDailyLogs = { ...prev.dailyLogs };
      if (!newDailyLogs[today]) newDailyLogs[today] = {};
      newDailyLogs[today][trackId] = (newDailyLogs[today][trackId] || 0) + 1;

      return {
        ...prev,
        totalCompletions: prev.totalCompletions + 1,
        dailyLogs: newDailyLogs
      };
    });
  };

  const isTaskActive = taskTarget > 0;

  useEffect(() => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.play().catch(() => setIsPlaying(false));
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume, currentTrack, view]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.load();
      if (isPlaying) {
        audioRef.current.play().catch(() => {});
      }
    }
    setTaskProgress(isTaskActive ? 1 : 0);
  }, [currentTrack.id]);

  const handleTrackSelect = (track: Track) => {
    setCurrentTrack(track);
    setIsPlaying(true);
    setView(View.PLAYER);
    setTaskTarget(0);
    setTaskProgress(0);
  };

  const handleNext = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const nextTrack = TRACKS[(idx + 1) % TRACKS.length];
      setCurrentTrack(nextTrack);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const prevTrack = TRACKS[(idx - 1 + TRACKS.length) % TRACKS.length];
      setCurrentTrack(prevTrack);
      setIsPlaying(true);
    }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration || 0);
    }
  };

  const handleEnded = () => {
    recordCompletion(currentTrack.id);
    if (taskTarget > 0) {
      if (taskProgress < taskTarget) {
        setTaskProgress(prev => prev + 1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
          audioRef.current.play();
        }
      } else {
        setIsPlaying(false);
        setTaskTarget(0);
        setTaskProgress(0);
        setShowMerit(true); // 触发功德圆满动画
      }
    } else if (!isSingleLoop) {
      handleNext();
    }
  };

  const updateTaskTarget = (target: number) => {
    if (taskProgress === 0) {
        setTaskProgress(1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
        }
    }
    setTaskTarget(target);
    setIsSingleLoop(false);
    setIsPlaying(true);
    if (audioRef.current && audioRef.current.paused) {
      audioRef.current.play();
    }
  };

  const stopTask = () => {
    setTaskTarget(0);
    setTaskProgress(0);
    setIsPlaying(false);
  };

  const handleRefreshQuote = () => {
    setZenQuote(getZenQuote());
  };

  const renderContent = () => {
    switch (view) {
      case View.PLAYER:
        return (
          <Player 
            track={currentTrack} 
            isPlaying={isPlaying} 
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            currentTime={currentTime}
            duration={duration}
            volume={volume}
            setVolume={setVolume}
            isLargeText={isLargeText}
          />
        );
      case View.PLAYLIST:
        return (
          <Playlist 
            currentTrackId={currentTrack.id} 
            onTrackSelect={handleTrackSelect}
            isLargeText={isLargeText}
          />
        );
      case View.TIMER:
        return (
          <Settings 
            currentTrack={currentTrack} 
            onNext={handleNext}
            onPrev={handlePrev}
            onUpdateTarget={updateTaskTarget}
            onStopTask={stopTask}
            taskProgress={taskProgress}
            taskTarget={taskTarget}
            currentTime={currentTime}
            duration={duration}
          />
        );
      case View.PROFILE:
        return (
          <Profile 
            stats={stats} 
            zenQuote={zenQuote} 
            onRefreshQuote={handleRefreshQuote}
            isLargeText={isLargeText}
            onToggleLargeText={() => setIsLargeText(!isLargeText)}
            onOpenShare={() => setShowShare(true)}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col w-full max-w-md mx-auto min-h-screen relative shadow-2xl bg-zen-dark overflow-hidden">
      {/* 沉浸式背景动态层 */}
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute inset-0 bg-wood-grain mix-blend-overlay opacity-20"></div>
        {/* 动态烟雾效果 */}
        <div className="absolute top-1/4 -left-1/4 w-[150%] h-1/2 bg-gradient-to-r from-transparent via-white/5 to-transparent blur-[100px] animate-smoke-flow rotate-12"></div>
        <div className="absolute bottom-1/4 -right-1/4 w-[150%] h-1/2 bg-gradient-to-l from-transparent via-gold-main/5 to-transparent blur-[80px] animate-smoke-flow -rotate-6 animation-delay-5000"></div>
      </div>

      <audio 
        ref={audioRef}
        src={currentTrack.audioUrl}
        onTimeUpdate={handleTimeUpdate}
        onEnded={handleEnded}
        loop={isSingleLoop && taskTarget === 0} 
      />

      {renderContent()}

      <BottomNav activeView={view} onViewChange={setView} />

      {/* 全屏功德圆满动画 */}
      {showMerit && <MeritAnimation onComplete={() => setShowMerit(false)} />}

      {/* 智慧分享卡 */}
      {showShare && <ShareCard quote={zenQuote} onClose={() => setShowShare(false)} />}
    </div>
  );
};

export default App;

import React, { useRef, useEffect } from 'react';
import { Track } from '../types';

interface PlayerProps {
  track: Track;
  isPlaying: boolean;
  onTogglePlay: () => void;
  onNext: () => void;
  onPrev: () => void;
  currentTime: number;
  duration: number;
  volume: number;
  setVolume: (vol: number) => void;
  isLargeText: boolean;
}

const Player: React.FC<PlayerProps> = ({ 
  track, isPlaying, onTogglePlay, onNext, onPrev, 
  currentTime, duration, volume, setVolume, isLargeText
}) => {
  const lastVolumeRef = useRef(volume > 0 ? volume : 0.65);

  useEffect(() => {
    if (volume > 0) {
      lastVolumeRef.current = volume;
    }
  }, [volume]);

  const handleMuteToggle = () => {
    if (volume > 0) {
      setVolume(0);
    } else {
      setVolume(lastVolumeRef.current);
    }
  };

  const formatSeconds = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60);
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const progressPercent = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <main className="flex-1 flex flex-col justify-between px-8 pt-12 pb-28 relative z-10">
      <div className="flex-1 flex flex-col justify-center items-center py-4">
        <div className="relative w-full max-w-[340px] flex items-center justify-center">

          <button 
            onClick={onPrev}
            className="absolute -left-10 z-30 w-14 h-14 rounded-full flex items-center justify-center text-gold-main/50 hover:text-gold-light hover:bg-white/5 active:scale-90 transition-all focus:outline-none backdrop-blur-sm border border-white/5 shadow-lg group"
            aria-label="上一曲"
          >
            <span className="material-symbols-outlined text-[40px] transition-transform group-hover:-translate-x-1">chevron_left</span>
          </button>

          <div className="relative w-64 h-64 sm:w-80 sm:h-80">
            {/* 佛光背景动效 */}
            <div className={`absolute inset-0 rounded-full bg-gold-main/20 blur-[60px] transition-all duration-1000 ${isPlaying ? 'scale-125 opacity-40 animate-aura-breath' : 'scale-95 opacity-0'}`}></div>

            <div className="relative w-full h-full rounded-full gold-ring shadow-[0_0_60px_rgba(0,0,0,0.6)]">
              <div className="w-full h-full rounded-full overflow-hidden bg-[#0c0805] relative flex items-center justify-center border-[4px] border-[#1A0F08]">
                <img 
                  alt={track.title}
                  className={`w-full h-full object-cover relative z-10 transition-transform duration-[10000ms] ease-in-out ${isPlaying ? 'scale-110 rotate-2' : 'scale-100 rotate-0'}`} 
                  src={track.imageUrl} 
                />
                <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-transparent via-white/5 to-transparent pointer-events-none z-20"></div>
              </div>
            </div>
          </div>

          <button 
            onClick={onNext}
            className="absolute -right-10 z-30 w-14 h-14 rounded-full flex items-center justify-center text-gold-main/50 hover:text-gold-light hover:bg-white/5 active:scale-90 transition-all focus:outline-none backdrop-blur-sm border border-white/5 shadow-lg group"
            aria-label="下一曲"
          >
            <span className="material-symbols-outlined text-[40px] transition-transform group-hover:translate-x-1">chevron_right</span>
          </button>
        </div>

        <div className="mt-12 text-center space-y-3">
          <h2 className={`text-gold-glow font-bold tracking-[0.25em] font-serif transition-all duration-500 ${isLargeText ? 'text-4xl' : 'text-2xl'}`}>
            {track.title}
          </h2>
          <p className={`text-stone-500 font-light tracking-[0.2em] font-serif italic opacity-80 ${isLargeText ? 'text-lg' : 'text-sm'}`}>
            {track.subtitle}
          </p>
        </div>
      </div>

      <div className="w-full max-w-[320px] mx-auto space-y-12">
        <div className="space-y-4">
          <div className="relative h-1.5 w-full bg-stone-900/80 rounded-full overflow-visible">
            <div 
              className="absolute top-0 left-0 h-full bg-gold-metal shadow-[0_0_15px_rgba(212,175,55,0.7)] transition-all duration-300 rounded-full" 
              style={{ width: `${progressPercent}%` }}
            />
            <div 
              className="absolute top-1/2 -translate-y-1/2 w-3 h-3 bg-white rounded-full shadow-[0_0_10px_white] transition-all duration-300"
              style={{ left: `${progressPercent}%`, transform: `translate(-50%, -50%)` }}
            ></div>
          </div>
          <div className="flex justify-between text-[11px] text-stone-600 font-display tracking-widest font-bold">
            <span>{formatSeconds(currentTime)}</span>
            <span>{formatSeconds(duration)}</span>
          </div>
        </div>

        <div className="flex flex-col items-center gap-10">
          <div className="relative">
            {isPlaying && (
              <div className="absolute inset-0 rounded-full border-2 border-gold-main/10 animate-[ping_3s_linear_infinite] scale-150 pointer-events-none"></div>
            )}
            <button 
              onClick={onTogglePlay}
              className="relative w-24 h-24 rounded-full bg-gold-metal flex items-center justify-center shadow-[0_15px_45px_rgba(0,0,0,0.7),inset_0_-4px_8px_rgba(0,0,0,0.4)] active:scale-95 transition-all border-4 border-[#2C1E12] z-10 group overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-tr from-black/20 via-transparent to-white/10 opacity-50 group-hover:opacity-100 transition-opacity pointer-events-none"></div>
              <span className="material-symbols-outlined text-[#3d2b1f] text-[68px] select-none transition-transform group-hover:scale-110">
                {isPlaying ? 'pause' : 'play_arrow'}
              </span>
            </button>
          </div>

          <div className="w-full flex items-center gap-4 px-5 py-4 bg-black/40 backdrop-blur-xl rounded-2xl border border-white/5 shadow-inner group">
            <button 
              onClick={handleMuteToggle}
              className="flex items-center justify-center focus:outline-none transition-transform active:scale-90"
              title={volume === 0 ? "取消静音" : "静音"}
            >
              <span className={`material-symbols-outlined text-[20px] font-light transition-colors ${volume === 0 ? 'text-red-500/80' : 'text-stone-600 hover:text-gold-main'}`}>
                {volume === 0 ? 'volume_off' : volume < 0.5 ? 'volume_down' : 'volume_up'}
              </span>
            </button>

            <div className="flex-1 relative flex items-center h-4">
              <div className="absolute w-full h-1 bg-stone-800 rounded-full pointer-events-none"></div>
              <div 
                className="absolute h-1 bg-gold-dark/60 rounded-full pointer-events-none transition-all duration-75"
                style={{ width: `${volume * 100}%` }}
              ></div>
              <input 
                type="range"
                min="0"
                max="1"
                step="0.01"
                value={volume}
                onChange={(e) => setVolume(parseFloat(e.target.value))}
                className="absolute w-full h-6 opacity-0 cursor-pointer z-10"
              />
              <div 
                className="absolute w-4 h-4 bg-gold-light rounded-full border-2 border-gold-dark shadow-xl transition-all duration-75 pointer-events-none"
                style={{ left: `calc(${volume * 100}% - 8px)` }}
              ></div>
            </div>
            <span className="text-[10px] text-stone-600 font-display w-6 text-right font-bold">{Math.round(volume * 100)}</span>
          </div>
        </div>
      </div>
    </main>
  );
};

export default Player;

import React, { useState } from 'react';
import { TRACKS } from '../constants';
import { ZenQuote } from '../services/zenQuoteService';

interface ProfileProps {
  stats: {
    installDate: string;
    totalCompletions: number;
    dailyLogs: { [date: string]: { [trackId: string]: number } };
  };
  zenQuote: ZenQuote;
  onRefreshQuote: () => void;
  isLargeText: boolean;
  onToggleLargeText: () => void;
  onOpenShare: () => void;
}

const Profile: React.FC<ProfileProps> = ({ stats, zenQuote, onRefreshQuote, isLargeText, onToggleLargeText, onOpenShare }) => {
  const [showCalendar, setShowCalendar] = useState(false);
  const today = new Date().toISOString().split('T')[0];
  const todayStats: Record<string, number> = stats.dailyLogs[today] || {};

  const calculateDays = () => {
    const start = new Date(stats.installDate).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    return diff + 1;
  };

  const todayItems = (Object.entries(todayStats) as [string, number][])
    .map(([trackId, count]) => {
      const track = TRACKS.find(t => t.id === trackId);
      return {
        title: track?.title || '自定义曲目',
        subtitle: track?.subtitle || '',
        count
      };
    })
    .sort((a, b) => b.count - a.count);

  const totalToday = todayItems.reduce((acc, curr) => acc + curr.count, 0);

  // 渲染简单的精进日历（展示最近30天）
  const renderCalendar = () => {
    const days = [];
    const now = new Date();
    for (let i = 29; i >= 0; i--) {
      const d = new Date(now);
      d.setDate(now.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];
      const log = stats.dailyLogs[dateStr] || {};
      const count = Object.values(log).reduce((a, b) => a + (b as number), 0);

      let intensity = 'bg-white/5';
      if (count > 0) intensity = 'bg-gold-main/20';
      if (count >= 108) intensity = 'bg-gold-main/50';
      if (count >= 1000) intensity = 'bg-gold-main';

      days.push(
        <div key={dateStr} className={`w-3 h-3 rounded-full ${intensity} transition-colors cursor-help`} title={`${dateStr}: ${count}遍`}></div>
      );
    }
    return days;
  };

  return (
    <div className="flex-1 flex flex-col overflow-y-auto pb-32 pt-16">
      <div className="px-8 pb-6 flex flex-col items-center text-center">
        <div className="relative mb-6">
          <div className="absolute inset-[-10px] bg-gold-main/10 blur-2xl rounded-full"></div>
          <div className="w-24 h-24 rounded-full badge-texture flex items-center justify-center text-[#4a3b18] border-2 border-gold-dark/30 shadow-2xl relative z-10">
             <span className="material-symbols-outlined text-5xl">person</span>
          </div>
        </div>

        <div className="space-y-4 w-full">
          <h3 className={`font-bold text-gold-light tracking-[0.2em] font-serif uppercase ${isLargeText ? 'text-3xl' : 'text-2xl'}`}>念佛弟子</h3>

          <div className="relative px-2 py-3 flex flex-col items-center group">
             <span className="absolute top-0 left-0 text-gold-main/20 text-4xl font-serif">“</span>
             <div className="px-6 py-2">
                <p className={`text-stone-300 tracking-widest leading-relaxed font-serif text-center transition-all ${isLargeText ? 'text-xl' : 'text-[15px]'}`}>
                  {zenQuote.text}
                </p>
                <p className={`text-gold-main/60 tracking-widest font-serif mt-3 text-right ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>
                  —— {zenQuote.source}
                </p>
             </div>
             <span className="absolute bottom-0 right-0 text-gold-main/20 text-4xl font-serif">”</span>
          </div>

          <div className="flex items-center justify-center gap-6 mt-2">
            <button 
              onClick={handleRefreshQuote} 
              className="text-[10px] text-gold-main/40 uppercase tracking-[0.4em] hover:text-gold-main transition-colors flex items-center gap-1"
            >
              <span className="material-symbols-outlined text-sm">refresh</span>
              刷新智慧
            </button>
            <button 
              onClick={onOpenShare} 
              className="text-[10px] text-gold-main/40 uppercase tracking-[0.4em] hover:text-gold-main transition-colors flex items-center gap-1"
            >
              <span className="material-symbols-outlined text-sm">share</span>
              法布施
            </button>
          </div>
        </div>
      </div>

      {/* 精进日历卡片 */}
      <div className="px-6 mb-8">
        <div className="glass-panel p-5 rounded-[2rem] overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] text-stone-500 uppercase tracking-widest font-serif font-bold">精进日历</h4>
            <div className="flex gap-1">
              <div className="w-2 h-2 rounded-full bg-white/5"></div>
              <div className="w-2 h-2 rounded-full bg-gold-main/20"></div>
              <div className="w-2 h-2 rounded-full bg-gold-main"></div>
            </div>
          </div>
          <div className="grid grid-cols-10 gap-2 justify-items-center">
            {renderCalendar()}
          </div>
        </div>
      </div>

      <div className="px-6 grid grid-cols-2 gap-4 mb-8">
        <div className="glass-panel p-5 rounded-3xl flex flex-col items-center justify-center">
          <p className="text-gold-main text-3xl font-bold font-display tracking-tighter">{calculateDays()}</p>
          <p className="text-[10px] text-stone-500 uppercase tracking-widest mt-2 font-bold">累计天数</p>
        </div>
        <div className="glass-panel p-5 rounded-3xl flex flex-col items-center justify-center">
          <p className="text-gold-main text-3xl font-bold font-display tracking-tighter">{stats.totalCompletions >= 10000 ? (stats.totalCompletions / 10000).toFixed(1) + 'w' : stats.totalCompletions}</p>
          <p className="text-[10px] text-stone-500 uppercase tracking-widest mt-2 font-bold">累计遍数</p>
        </div>
      </div>

      {/* 设置区域 */}
      <div className="px-6 mb-8">
        <div className="glass-panel p-5 rounded-[2rem] space-y-4">
          <h4 className="text-[11px] text-stone-500 uppercase tracking-widest font-serif font-bold mb-4">系统设置</h4>
          <div className="flex items-center justify-between">
            <div className="flex flex-col">
              <span className="text-stone-300 text-sm font-medium">大字模式</span>
              <span className="text-stone-600 text-[10px]">更清晰的文字展示</span>
            </div>
            <button 
              onClick={onToggleLargeText}
              className={`w-12 h-6 rounded-full transition-all relative ${isLargeText ? 'bg-gold-main' : 'bg-stone-800'}`}
            >
              <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isLargeText ? 'left-7' : 'left-1'}`}></div>
            </button>
          </div>
        </div>
      </div>

      <div className="px-6 space-y-4">
        <div className="flex items-center justify-between px-2">
           <h4 className="text-gold-light text-sm font-bold tracking-[0.2em] font-serif uppercase border-l-2 border-gold-main pl-3">今日功课</h4>
           <div className="flex items-baseline gap-1">
              <span className="text-gold-main text-lg font-bold">{totalToday}</span>
              <span className="text-stone-600 text-[10px] uppercase font-bold">Rounds</span>
           </div>
        </div>

        <div className="bg-black/20 rounded-3xl border border-white/5 overflow-hidden">
          {todayItems.length > 0 ? (
            <div className="divide-y divide-white/5">
              {todayItems.map((item, idx) => (
                <div key={idx} className="flex items-center justify-between p-4 hover:bg-white/[0.02] transition-colors">
                  <div className="flex flex-col">
                    <span className="text-stone-200 text-sm font-medium tracking-wide">{item.title}</span>
                    <span className="text-stone-600 text-[10px] tracking-widest mt-0.5">{item.subtitle}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-gold-main font-bold text-lg">{item.count}</span>
                    <span className="text-stone-700 text-[10px] font-serif">遍</span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="py-12 flex flex-col items-center justify-center opacity-20">
               <span className="material-symbols-outlined text-4xl mb-2">hourglass_empty</span>
               <p className="text-xs tracking-[0.3em] uppercase">今日暂无记录</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Profile;

