import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
  // Added isLargeText prop to handle font scaling
  isLargeText?: boolean;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';
const AUDIO_CACHE_NAME = 'zen-chant-audio';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId, isLargeText }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');

  // 离线同步状态
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'completed'>('idle');
  const [syncProgress, setSyncProgress] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }

    // 检查缓存状态
    checkCacheStatus();
  }, []);

  const checkCacheStatus = async () => {
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      const keys = await cache.keys();
      // 如果已缓存数量等于官方曲目数量，标记为已完成
      if (keys.length >= TRACKS.length) {
        setSyncStatus('completed');
      }
    } catch (e) {
      console.error("Cache check failed", e);
    }
  };

  const handleOfflineSync = async () => {
    if (syncStatus === 'syncing') return;

    setSyncStatus('syncing');
    setSyncProgress(0);

    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      let count = 0;

      for (const track of TRACKS) {
        try {
          // 检查是否已缓存
          const match = await cache.match(track.audioUrl);
          if (!match) {
            await cache.add(track.audioUrl);
          }
        } catch (err) {
          console.warn(`Failed to sync track: ${track.title}`, err);
        }
        count++;
        setSyncProgress(Math.round((count / TRACKS.length) * 100));
      }

      setSyncStatus('completed');
    } catch (e) {
      console.error("Sync failed", e);
      setSyncStatus('idle');
      alert("同步失败，请检查网络连接后重试。");
    }
  };

  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
    localStorage.setItem(CUSTOM_TRACKS_KEY, JSON.stringify(tracks));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewTrackUrl(url);
      if (!newTrackTitle) {
        setNewTrackTitle(file.name.replace(/\.[^/.]+$/, ""));
      }
    }
  };

  const handleAddTrack = () => {
    if (!newTrackTitle || !newTrackUrl) return;

    const newTrack: Track = {
      id: `custom_${Date.now()}`,
      code: `Z${(customTracks.length + 1).toString().padStart(2, '0')}`,
      title: newTrackTitle,
      subtitle: addMethod === 'file' ? '本地上传' : '网络链接',
      section: 'CUSTOM',
      imageUrl: 'https://www.shouyueliang.org/wp-content/uploads/2021/04/1623587633-v500-4-1.gif',
      audioUrl: newTrackUrl
    };

    saveCustomTracks([...customTracks, newTrack]);
    setShowAddModal(false);
    setNewTrackTitle('');
    setNewTrackUrl('');
  };

  const removeTrack = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = customTracks.filter(t => t.id !== id);
    saveCustomTracks(updated);
  };

  return (
    <div className="flex flex-col h-full bg-dark-gradient overflow-hidden pt-10">
      {/* 顶部标签切换 */}
      <div className="flex-none bg-transparent px-6 mb-2">
        <div className="flex gap-4">
          <button 
            onClick={() => setActiveTab('official')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'official' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-600'}`}
          >
            {/* Added dynamic font size for tab labels */}
            <p className={`font-bold tracking-[0.1em] font-serif ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>官方曲目</p>
          </button>
          <button 
            onClick={() => setActiveTab('custom')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'custom' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-600'}`}
          >
            {/* Added dynamic font size for tab labels */}
            <p className={`font-bold tracking-[0.1em] font-serif ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>自定义</p>
          </button>
        </div>
      </div>

      {/* 离线同步状态条 (仅在官方曲目页显示) */}
      {activeTab === 'official' && (
        <div className="px-6 py-3">
          <div className="bg-black/40 border border-white/5 rounded-2xl p-3 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className={`material-symbols-outlined text-xl ${syncStatus === 'completed' ? 'text-green-500' : 'text-gold-main'}`}>
                {syncStatus === 'syncing' ? 'sync' : syncStatus === 'completed' ? 'cloud_done' : 'cloud_download'}
              </span>
              <div>
                <p className="text-[11px] text-stone-300 font-serif">
                  {syncStatus === 'syncing' ? `正在离线同步 (${syncProgress}%)` : syncStatus === 'completed' ? '已离线 (无网亦可播放)' : '未离线 (建议同步以支持离线)'}
                </p>
                {syncStatus === 'syncing' && (
                  <div className="w-32 h-1 bg-stone-800 rounded-full mt-1 overflow-hidden">
                    <div className="h-full bg-gold-main transition-all duration-300" style={{ width: `${syncProgress}%` }}></div>
                  </div>
                )}
              </div>
            </div>
            {syncStatus !== 'completed' && (
              <button 
                onClick={handleOfflineSync}
                disabled={syncStatus === 'syncing'}
                className="px-3 py-1 bg-gold-main/10 border border-gold-main/30 rounded-lg text-[10px] text-gold-main font-bold tracking-widest uppercase hover:bg-gold-main/20 disabled:opacity-50"
              >
                {syncStatus === 'syncing' ? '同步中' : '开始同步'}
              </button>
            )}
          </div>
        </div>
      )}

      {/* 滚动列表 */}
      <div className="flex-1 overflow-y-auto pb-32 scroll-smooth">
        {activeTab === 'official' ? (
          SECTIONS.map((section) => (
            <div key={section.id} className="mb-2">
              <div className="sticky top-0 z-30 bg-[#1a1208]/95 backdrop-blur-md px-5 py-3 border-b border-gold-dark/10 shadow-sm">
                <div className="flex items-center gap-3">
                  <span className="bg-gold-main/20 border border-gold-main/40 text-gold-main text-[10px] font-bold px-2 py-0.5 rounded tracking-widest font-display">
                    {section.code}
                  </span>
                  <h3 className="text-gold-light text-base font-bold font-serif tracking-wider">{section.name}</h3>
                </div>
              </div>

              <div className="flex flex-col divide-y divide-white/5 px-2">
                {TRACKS.filter(t => t.section === section.code).map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.03] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.08]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className={`badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#4a3b18] text-sm font-display shadow-lg border border-[#7c6428]/50 transition-transform ${currentTrackId === track.id ? 'scale-110' : ''}`}>
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        {/* Added dynamic font size for track titles */}
                        <p className={`font-medium font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-gray-200 group-hover:text-gold-main'} ${isLargeText ? 'text-xl' : 'text-[17px]'}`}>
                          {track.title}
                        </p>
                        {/* Added dynamic font size for track subtitles */}
                        <p className={`text-stone-500 tracking-wider font-serif ${isLargeText ? 'text-sm' : 'text-xs'}`}>{track.subtitle}</p>
                      </div>
                    </div>
                    <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-[#5d4a1f] group-hover:text-gold-main'}`}>
                      {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          ))
        ) : (
          <div className="px-2 py-4 space-y-4">
            <button 
              onClick={() => setShowAddModal(true)}
              className="w-full flex items-center justify-center gap-3 py-4 rounded-xl border-2 border-dashed border-gold-dark/30 text-gold-main hover:bg-gold-main/5 transition-colors group"
            >
              <span className="material-symbols-outlined text-2xl group-hover:scale-110 transition-transform">add_circle</span>
              <span className="font-bold tracking-widest font-serif">添加自定义曲目</span>
            </button>

            <div className="flex flex-col divide-y divide-white/5">
              {customTracks.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 opacity-30 text-gold-light">
                  <span className="material-symbols-outlined text-6xl mb-4">music_off</span>
                  <p className="text-sm tracking-widest font-serif">暂无自定义曲目</p>
                </div>
              ) : (
                customTracks.map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.03] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.08]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className="badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#4a3b18] text-sm font-display shadow-lg border border-[#7c6428]/50">
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        {/* Added dynamic font size for custom track titles */}
                        <p className={`font-medium font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-gray-200 group-hover:text-gold-main'} ${isLargeText ? 'text-xl' : 'text-[17px]'}`}>
                          {track.title}
                        </p>
                        {/* Added dynamic font size for custom track subtitles */}
                        <p className={`text-stone-500 tracking-wider font-serif ${isLargeText ? 'text-sm' : 'text-xs'}`}>{track.subtitle}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={(e) => removeTrack(e, track.id)}
                        className="text-red-900/40 hover:text-red-500 p-2 transition-colors"
                      >
                        <span className="material-symbols-outlined text-xl">delete</span>
                      </button>
                      <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-[#5d4a1f] group-hover:text-gold-main'}`}>
                        {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                      </span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 backdrop-blur-md bg-black/60">
          <div className="w-full max-w-sm bg-surface-dark border border-gold-dark/30 rounded-[2rem] p-8 shadow-2xl">
            <h3 className="text-gold-light text-xl font-bold font-serif mb-6 text-center tracking-widest">添加修行曲目</h3>
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-stone-500 text-[10px] uppercase tracking-widest font-serif ml-1">曲目名称</label>
                <input 
                  type="text" 
                  value={newTrackTitle}
                  onChange={(e) => setNewTrackTitle(e.target.value)}
                  placeholder="请输入曲目名称"
                  className="w-full bg-black/30 border border-gold-dark/20 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none"
                />
              </div>
              <div className="space-y-3">
                <div className="flex gap-2">
                  <button onClick={() => setAddMethod('url')} className={`flex-1 py-2 rounded-lg text-xs font-serif transition-all ${addMethod === 'url' ? 'bg-gold-main/20 text-gold-main border border-gold-main/30' : 'bg-black/20 text-stone-500 border border-transparent'}`}>网络链接</button>
                  <button onClick={() => setAddMethod('file')} className={`flex-1 py-2 rounded-lg text-xs font-serif transition-all ${addMethod === 'file' ? 'bg-gold-main/20 text-gold-main border border-gold-main/30' : 'bg-black/20 text-stone-500 border border-transparent'}`}>本地文件</button>
                </div>
                {addMethod === 'url' ? (
                  <input 
                    type="text" 
                    value={newTrackUrl}
                    onChange={(e) => setNewTrackUrl(e.target.value)}
                    placeholder="https://example.com/audio.mp3"
                    className="w-full bg-black/30 border border-gold-dark/20 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none"
                  />
                ) : (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full bg-black/30 border border-dashed border-gold-dark/20 rounded-xl px-4 py-4 text-center cursor-pointer">
                    <span className="text-gold-main/60 text-xs font-serif">{newTrackUrl ? '已选择音频' : '点击上传本地音频'}</span>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="audio/*" className="hidden" />
                  </div>
                )}
              </div>
              <div className="flex gap-3 pt-4">
                <button onClick={() => setShowAddModal(false)} className="flex-1 py-3 rounded-xl border border-gold-dark/30 text-stone-400 font-serif">取消</button>
                <button onClick={handleAddTrack} disabled={!newTrackTitle || !newTrackUrl} className="flex-1 py-3 rounded-xl bg-gold-metal text-[#3d2b1f] font-bold font-serif">确认添加</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Playlist;

import React, { useState } from 'react';
import { TRACKS } from '../constants';
import { ZenQuote } from '../services/zenQuoteService';

interface ProfileProps {
  stats: {
    installDate: string;
    totalCompletions: number;
    dailyLogs: { [date: string]: { [trackId: string]: number } };
  };
  zenQuote: ZenQuote;
  onRefreshQuote: () => void;
  isLargeText: boolean;
  onToggleLargeText: () => void;
  onOpenShare: () => void;
}

const Profile: React.FC<ProfileProps> = ({ stats, zenQuote, onRefreshQuote, isLargeText, onToggleLargeText, onOpenShare }) => {
  const [showCalendar, setShowCalendar] = useState(false);
  const today = new Date().toISOString().split('T')[0];
  const todayStats: Record<string, number> = stats.dailyLogs[today] || {};

  const calculateDays = () => {
    const start = new Date(stats.installDate).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    return diff + 1;
  };

  const todayItems = (Object.entries(todayStats) as [string, number][])
    .map(([trackId, count]) => {
      const track = TRACKS.find(t => t.id === trackId);
      return {
        title: track?.title || '自定义曲目',
        subtitle: track?.subtitle || '',
        count
      };
    })
    .sort((a, b) => b.count - a.count);

  const totalToday = todayItems.reduce((acc, curr) => acc + curr.count, 0);

  // 渲染简单的精进日历（展示最近30天）
  const renderCalendar = () => {
    const days = [];
    const now = new Date();
    for (let i = 29; i >= 0; i--) {
      const d = new Date(now);
      d.setDate(now.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];
      const log = stats.dailyLogs[dateStr] || {};
      const count = Object.values(log).reduce((a, b) => a + (b as number), 0);

      let intensity = 'bg-white/5';
      if (count > 0) intensity = 'bg-gold-main/20';
      if (count >= 108) intensity = 'bg-gold-main/50';
      if (count >= 1000) intensity = 'bg-gold-main';

      days.push(
        <div key={dateStr} className={`w-3 h-3 rounded-full ${intensity} transition-colors cursor-help`} title={`${dateStr}: ${count}遍`}></div>
      );
    }
    return days;
  };

  return (
    <div className="flex-1 flex flex-col overflow-y-auto pb-32 pt-16">
      <div className="px-8 pb-6 flex flex-col items-center text-center">
        <div className="relative mb-6">
          <div className="absolute inset-[-10px] bg-gold-main/10 blur-2xl rounded-full"></div>
          <div className="w-24 h-24 rounded-full badge-texture flex items-center justify-center text-[#4a3b18] border-2 border-gold-dark/30 shadow-2xl relative z-10">
             <span className="material-symbols-outlined text-5xl">person</span>
          </div>
        </div>

        <div className="space-y-4 w-full">
          <h3 className={`font-bold text-gold-light tracking-[0.2em] font-serif uppercase ${isLargeText ? 'text-3xl' : 'text-2xl'}`}>念佛弟子</h3>

          <div className="relative px-2 py-3 flex flex-col items-center group">
             <span className="absolute top-0 left-0 text-gold-main/20 text-4xl font-serif">“</span>
             <div className="px-6 py-2">
                <p className={`text-stone-300 tracking-widest leading-relaxed font-serif text-center transition-all ${isLargeText ? 'text-xl' : 'text-[15px]'}`}>
                  {zenQuote.text}
                </p>
                <p className={`text-gold-main/60 tracking-widest font-serif mt-3 text-right ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>
                  —— {zenQuote.source}
                </p>
             </div>
             <span className="absolute bottom-0 right-0 text-gold-main/20 text-4xl font-serif">”</span>
          </div>

          <div className="flex items-center justify-center gap-6 mt-2">
            {/* Fixed handleRefreshQuote to onRefreshQuote */}
            <button 
              onClick={onRefreshQuote} 
              className="text-[10px] text-gold-main/40 uppercase tracking-[0.4em] hover:text-gold-main transition-colors flex items-center gap-1"
            >
              <span className="material-symbols-outlined text-sm">refresh</span>
              刷新智慧
            </button>
            <button 
              onClick={onOpenShare} 
              className="text-[10px] text-gold-main/40 uppercase tracking-[0.4em] hover:text-gold-main transition-colors flex items-center gap-1"
            >
              <span className="material-symbols-outlined text-sm">share</span>
              法布施
            </button>
          </div>
        </div>
      </div>

      {/* 精进日历卡片 */}
      <div className="px-6 mb-8">
        <div className="glass-panel p-5 rounded-[2rem] overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] text-stone-500 uppercase tracking-widest font-serif font-bold">精进日历</h4>
            <div className="flex gap-1">
              <div className="w-2 h-2 rounded-full bg-white/5"></div>
              <div className="w-2 h-2 rounded-full bg-gold-main/20"></div>
              <div className="w-2 h-2 rounded-full bg-gold-main"></div>
            </div>
          </div>
          <div className="grid grid-cols-10 gap-2 justify-items-center">
            {renderCalendar()}
          </div>
        </div>
      </div>

      <div className="px-6 grid grid-cols-2 gap-4 mb-8">
        <div className="glass-panel p-5 rounded-3xl flex flex-col items-center justify-center">
          <p className="text-gold-main text-3xl font-bold font-display tracking-tighter">{calculateDays()}</p>
          <p className="text-[10px] text-stone-500 uppercase tracking-widest mt-2 font-bold">累计天数</p>
        </div>
        <div className="glass-panel p-5 rounded-3xl flex flex-col items-center justify-center">
          <p className="text-gold-main text-3xl font-bold font-display tracking-tighter">{stats.totalCompletions >= 10000 ? (stats.totalCompletions / 10000).toFixed(1) + 'w' : stats.totalCompletions}</p>
          <p className="text-[10px] text-stone-500 uppercase tracking-widest mt-2 font-bold">累计遍数</p>
        </div>
      </div>

      {/* 设置区域 */}
      <div className="px-6 mb-8">
        <div className="glass-panel p-5 rounded-[2rem] space-y-4">
          <h4 className="text-[11px] text-stone-500 uppercase tracking-widest font-serif font-bold mb-4">系统设置</h4>
          <div className="flex items-center justify-between">
            <div className="flex flex-col">
              <span className="text-stone-300 text-sm font-medium">大字模式</span>
              <span className="text-stone-600 text-[10px]">更清晰的文字展示</span>
            </div>
            <button 
              onClick={onToggleLargeText}
              className={`w-12 h-6 rounded-full transition-all relative ${isLargeText ? 'bg-gold-main' : 'bg-stone-800'}`}
            >
              <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isLargeText ? 'left-7' : 'left-1'}`}></div>
            </button>
          </div>
        </div>
      </div>

      <div className="px-6 space-y-4">
        <div className="flex items-center justify-between px-2">
           <h4 className="text-gold-light text-sm font-bold tracking-[0.2em] font-serif uppercase border-l-2 border-gold-main pl-3">今日功课</h4>
           <div className="flex items-baseline gap-1">
              <span className="text-gold-main text-lg font-bold">{totalToday}</span>
              <span className="text-stone-600 text-[10px] uppercase font-bold">Rounds</span>
           </div>
        </div>

        <div className="bg-black/20 rounded-3xl border border-white/5 overflow-hidden">
          {todayItems.length > 0 ? (
            <div className="divide-y divide-white/5">
              {todayItems.map((item, idx) => (
                <div key={idx} className="flex items-center justify-between p-4 hover:bg-white/[0.02] transition-colors">
                  <div className="flex flex-col">
                    <span className="text-stone-200 text-sm font-medium tracking-wide">{item.title}</span>
                    <span className="text-stone-600 text-[10px] tracking-widest mt-0.5">{item.subtitle}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-gold-main font-bold text-lg">{item.count}</span>
                    <span className="text-stone-700 text-[10px] font-serif">遍</span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="py-12 flex flex-col items-center justify-center opacity-20">
               <span className="material-symbols-outlined text-4xl mb-2">hourglass_empty</span>
               <p className="text-xs tracking-[0.3em] uppercase">今日暂无记录</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Profile;

