import React, { useState, useEffect, useRef } from 'react';
import { Track } from '../types';
import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';
const AUDIO_CACHE_NAME = 'zen-chant-audio';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');

  // 离线同步状态
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'completed'>('idle');
  const [syncProgress, setSyncProgress] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }

    // 检查缓存状态
    checkCacheStatus();
  }, []);

  const checkCacheStatus = async () => {
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      const keys = await cache.keys();
      // 如果已缓存数量等于官方曲目数量，标记为已完成
      if (keys.length >= TRACKS.length) {
        setSyncStatus('completed');
      }
    } catch (e) {
      console.error("Cache check failed", e);
    }
  };

  const handleOfflineSync = async () => {
    if (syncStatus === 'syncing') return;

    setSyncStatus('syncing');
    setSyncProgress(0);

    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      let count = 0;

      for (const track of TRACKS) {
        try {
          // 检查是否已缓存
          const match = await cache.match(track.audioUrl);
          if (!match) {
            await cache.add(track.audioUrl);
          }
        } catch (err) {
          console.warn(`Failed to sync track: ${track.title}`, err);
        }
        count++;
        setSyncProgress(Math.round((count / TRACKS.length) * 100));
      }

      setSyncStatus('completed');
    } catch (e) {
      console.error("Sync failed", e);
      setSyncStatus('idle');
      alert("同步失败，请检查网络连接后重试。");
    }
  };

  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
    localStorage.setItem(CUSTOM_TRACKS_KEY, JSON.stringify(tracks));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewTrackUrl(url);
      if (!newTrackTitle) {
        setNewTrackTitle(file.name.replace(/\.[^/.]+$/, ""));
      }
    }
  };

  const handleAddTrack = () => {
    if (!newTrackTitle || !newTrackUrl) return;

    const newTrack: Track = {
      id: `custom_${Date.now()}`,
      code: `Z${(customTracks.length + 1).toString().padStart(2, '0')}`,
      title: newTrackTitle,
      subtitle: addMethod === 'file' ? '本地上传' : '网络链接',
      section: 'CUSTOM',
      imageUrl: 'https://www.shouyueliang.org/wp-content/uploads/2021/04/1623587633-v500-4-1.gif',
      audioUrl: newTrackUrl
    };

    saveCustomTracks([...customTracks, newTrack]);
    setShowAddModal(false);
    setNewTrackTitle('');
    setNewTrackUrl('');
  };

  const removeTrack = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = customTracks.filter(t => t.id !== id);
    saveCustomTracks(updated);
  };

  return (
    <div className="flex flex-col h-full bg-dark-gradient overflow-hidden pt-10">
      {/* 顶部标签切换 */}
      <div className="flex-none bg-transparent px-6 mb-2">
        <div className="flex gap-4">
          <button 
            onClick={() => setActiveTab('official')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'official' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-600'}`}
          >
            <p className="text-[16px] font-bold tracking-[0.1em] font-serif">官方曲目</p>
          </button>
          <button 
            onClick={() => setActiveTab('custom')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'custom' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-600'}`}
          >
            <p className="text-[16px] font-bold tracking-[0.1em] font-serif">自定义</p>
          </button>
        </div>
      </div>

      {/* 离线同步状态条 (仅在官方曲目页显示) */}
      {activeTab === 'official' && (
        <div className="px-6 py-3">
          <div className="bg-black/40 border border-white/5 rounded-2xl p-3 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className={`material-symbols-outlined text-xl ${syncStatus === 'completed' ? 'text-green-500' : 'text-gold-main'}`}>
                {syncStatus === 'syncing' ? 'sync' : syncStatus === 'completed' ? 'cloud_done' : 'cloud_download'}
              </span>
              <div>
                <p className="text-[11px] text-stone-300 font-serif">
                  {syncStatus === 'syncing' ? `正在离线同步 (${syncProgress}%)` : syncStatus === 'completed' ? '已离线 (无网亦可播放)' : '未离线 (建议同步以支持离线)'}
                </p>
                {syncStatus === 'syncing' && (
                  <div className="w-32 h-1 bg-stone-800 rounded-full mt-1 overflow-hidden">
                    <div className="h-full bg-gold-main transition-all duration-300" style={{ width: `${syncProgress}%` }}></div>
                  </div>
