                  />
                ) : (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full bg-black/30 border border-dashed border-gold-dark/20 rounded-xl px-4 py-4 text-center cursor-pointer">
                    <span className="text-gold-main/60 text-xs font-serif">{newTrackUrl ? '已选择音频' : '点击上传本地音频'}</span>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="audio/*" className="hidden" />
                  </div>
