              <div className="flex gap-3 pt-4">
                <button onClick={() => setShowAddModal(false)} className="flex-1 py-3 rounded-xl border border-gold-dark/30 text-stone-400 font-serif">取消</button>
                <button onClick={handleAddTrack} disabled={!newTrackTitle || !newTrackUrl} className="flex-1 py-3 rounded-xl bg-gold-metal text-[#3d2b1f] font-bold font-serif">确认添加</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

