import React, { useState } from 'react';
import { TRACKS } from '../constants';
import { ZenQuote } from '../services/zenQuoteService';

interface ProfileProps {
  stats: {
    installDate: string;
    totalCompletions: number;
    dailyLogs: { [date: string]: { [trackId: string]: number } };
  };
  zenQuote: ZenQuote;
  onRefreshQuote: () => void;
  isLargeText: boolean;
  onToggleLargeText: () => void;
  onOpenShare: () => void;
}

const Profile: React.FC<ProfileProps> = ({ stats, zenQuote, onRefreshQuote, isLargeText, onToggleLargeText, onOpenShare }) => {
  const [showCalendar, setShowCalendar] = useState(false);
  const today = new Date().toISOString().split('T')[0];
  const todayStats: Record<string, number> = stats.dailyLogs[today] || {};

  const calculateDays = () => {
    const start = new Date(stats.installDate).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    return diff + 1;
  };

  const todayItems = (Object.entries(todayStats) as [string, number][])
    .map(([trackId, count]) => {
      const track = TRACKS.find(t => t.id === trackId);
      return {
        title: track?.title || '自定义曲目',
        subtitle: track?.subtitle || '',
        count
      };
    })
    .sort((a, b) => b.count - a.count);

  const totalToday = todayItems.reduce((acc, curr) => acc + curr.count, 0);

  // 渲染简单的精进日历（展示最近30天）
  const renderCalendar = () => {
    const days = [];
    const now = new Date();
    for (let i = 29; i >= 0; i--) {
      const d = new Date(now);
      d.setDate(now.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];
      const log = stats.dailyLogs[dateStr] || {};
      const count = Object.values(log).reduce((a, b) => a + (b as number), 0);

      let intensity = 'bg-white/5';
      if (count > 0) intensity = 'bg-gold-main/20';
      if (count >= 108) intensity = 'bg-gold-main/50';
      if (count >= 1000) intensity = 'bg-gold-main';

      days.push(
        <div key={dateStr} className={`w-3 h-3 rounded-full ${intensity} transition-colors cursor-help`} title={`${dateStr}: ${count}遍`}></div>
      );
    }
    return days;
  };

  return (
    <div className="flex-1 flex flex-col overflow-y-auto pb-32 pt-16">
      <div className="px-8 pb-6 flex flex-col items-center text-center">
        <div className="relative mb-6">
          <div className="absolute inset-[-10px] bg-gold-main/10 blur-2xl rounded-full"></div>
          <div className="w-24 h-24 rounded-full badge-texture flex items-center justify-center text-[#4a3b18] border-2 border-gold-dark/30 shadow-2xl relative z-10">
             <span className="material-symbols-outlined text-5xl">person</span>
          </div>
        </div>

        <div className="space-y-4 w-full">
          <h3 className={`font-bold text-gold-light tracking-[0.2em] font-serif uppercase ${isLargeText ? 'text-3xl' : 'text-2xl'}`}>念佛弟子</h3>

          <div className="relative px-2 py-3 flex flex-col items-center group">
             <span className="absolute top-0 left-0 text-gold-main/20 text-4xl font-serif">“</span>
             <div className="px-6 py-2">
                <p className={`text-stone-300 tracking-widest leading-relaxed font-serif text-center transition-all ${isLargeText ? 'text-xl' : 'text-[15px]'}`}>
                  {zenQuote.text}
                </p>
                <p className={`text-gold-main/60 tracking-widest font-serif mt-3 text-right ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>
                  —— {zenQuote.source}
                </p>
             </div>
             <span className="absolute bottom-0 right-0 text-gold-main/20 text-4xl font-serif">”</span>
          </div>

          <div className="flex items-center justify-center gap-6 mt-2">
            <button 
              onClick={handleRefreshQuote} 
              className="text-[10px] text-gold-main/40 uppercase tracking-[0.4em] hover:text-gold-main transition-colors flex items-center gap-1"
            >
              <span className="material-symbols-outlined text-sm">refresh</span>
              刷新智慧
            </button>
            <button 
              onClick={onOpenShare} 
              className="text-[10px] text-gold-main/40 uppercase tracking-[0.4em] hover:text-gold-main transition-colors flex items-center gap-1"
            >
              <span className="material-symbols-outlined text-sm">share</span>
              法布施
            </button>
          </div>
        </div>
      </div>

      {/* 精进日历卡片 */}
      <div className="px-6 mb-8">
        <div className="glass-panel p-5 rounded-[2rem] overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-[11px] text-stone-500 uppercase tracking-widest font-serif font-bold">精进日历</h4>
            <div className="flex gap-1">
              <div className="w-2 h-2 rounded-full bg-white/5"></div>
              <div className="w-2 h-2 rounded-full bg-gold-main/20"></div>
              <div className="w-2 h-2 rounded-full bg-gold-main"></div>
            </div>
          </div>
          <div className="grid grid-cols-10 gap-2 justify-items-center">
            {renderCalendar()}
          </div>
        </div>
      </div>

      <div className="px-6 grid grid-cols-2 gap-4 mb-8">
        <div className="glass-panel p-5 rounded-3xl flex flex-col items-center justify-center">
          <p className="text-gold-main text-3xl font-bold font-display tracking-tighter">{calculateDays()}</p>
          <p className="text-[10px] text-stone-500 uppercase tracking-widest mt-2 font-bold">累计天数</p>
        </div>
        <div className="glass-panel p-5 rounded-3xl flex flex-col items-center justify-center">
          <p className="text-gold-main text-3xl font-bold font-display tracking-tighter">{stats.totalCompletions >= 10000 ? (stats.totalCompletions / 10000).toFixed(1) + 'w' : stats.totalCompletions}</p>
          <p className="text-[10px] text-stone-500 uppercase tracking-widest mt-2 font-bold">累计遍数</p>
        </div>
      </div>

      {/* 设置区域 */}
      <div className="px-6 mb-8">
        <div className="glass-panel p-5 rounded-[2rem] space-y-4">
          <h4 className="text-[11px] text-stone-500 uppercase tracking-widest font-serif font-bold mb-4">系统设置</h4>
          <div className="flex items-center justify-between">
            <div className="flex flex-col">
              <span className="text-stone-300 text-sm font-medium">大字模式</span>
              <span className="text-stone-600 text-[10px]">更清晰的文字展示</span>
            </div>
            <button 
              onClick={onToggleLargeText}
              className={`w-12 h-6 rounded-full transition-all relative ${isLargeText ? 'bg-gold-main' : 'bg-stone-800'}`}
            >
              <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isLargeText ? 'left-7' : 'left-1'}`}></div>
            </button>
          </div>
        </div>
      </div>

      <div className="px-6 space-y-4">
        <div className="flex items-center justify-between px-2">
           <h4 className="text-gold-light text-sm font-bold tracking-[0.2em] font-serif uppercase border-l-2 border-gold-main pl-3">今日功课</h4>
           <div className="flex items-baseline gap-1">
              <span className="text-gold-main text-lg font-bold">{totalToday}</span>
              <span className="text-stone-600 text-[10px] uppercase font-bold">Rounds</span>
           </div>
        </div>

        <div className="bg-black/20 rounded-3xl border border-white/5 overflow-hidden">
          {todayItems.length > 0 ? (
            <div className="divide-y divide-white/5">
              {todayItems.map((item, idx) => (
                <div key={idx} className="flex items-center justify-between p-4 hover:bg-white/[0.02] transition-colors">
                  <div className="flex flex-col">
                    <span className="text-stone-200 text-sm font-medium tracking-wide">{item.title}</span>
                    <span className="text-stone-600 text-[10px] tracking-widest mt-0.5">{item.subtitle}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-gold-main font-bold text-lg">{item.count}</span>
                    <span className="text-stone-700 text-[10px] font-serif">遍</span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="py-12 flex flex-col items-center justify-center opacity-20">
               <span className="material-symbols-outlined text-4xl mb-2">hourglass_empty</span>
               <p className="text-xs tracking-[0.3em] uppercase">今日暂无记录</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

