      <file name="sw.js">
const CACHE_NAME = 'zen-chant-v1';
const AUDIO_CACHE = 'zen-chant-audio';

// 安装阶段：可以预缓存一些核心 UI 资源
self.addEventListener('install', (event) => {
  self.skipWaiting();
});

// 激活阶段：清理旧缓存
self.addEventListener('activate', (event) => {
  event.waitUntil(clients.claim());
});

// 拦截请求
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // 处理音频资源的缓存策略：优先从缓存读取
  if (url.hostname.includes('jdcloud-oss.com')) {
    event.respondWith(
      caches.open(AUDIO_CACHE).then(async (cache) => {
        const cachedResponse = await cache.match(event.request);
        if (cachedResponse) {
          return cachedResponse;
        }
        // 如果没有缓存，则发起网络请求
        return fetch(event.request).then(networkResponse => {
            // 这里不自动在播放时静默存入，因为音频文件较大，由用户手动触发同步更合适
            return networkResponse;
        });
      })
    );
    return;
  }

  // 针对其他静态资源（CDN, HTML 等）的缓存策略：Cache First, then Network
  event.respondWith(
    caches.match(event.request).then((response) => {
      if (response) return response;

      return fetch(event.request).then(networkResponse => {
        // 确保只缓存成功的 GET 请求
        if (event.request.method === 'GET' && networkResponse.status === 200) {
          const responseToCache = networkResponse.clone();
          caches.open(CACHE_NAME).then(cache => {
            cache.put(event.request, responseToCache);
          });
        }
        return networkResponse;
      });
    }).catch(() => {
        // 离线时如果没有任何匹配，可以返回一个 fallback
    })
  );
});</file>
