              <span className="text-stone-300 text-sm font-medium">大字模式</span>
              <span className="text-stone-600 text-[10px]">更清晰的文字展示</span>
            </div>
            <button 
              onClick={onToggleLargeText}
              className={`w-12 h-6 rounded-full transition-all relative ${isLargeText ? 'bg-gold-main' : 'bg-stone-800'}`}
            >
              <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isLargeText ? 'left-7' : 'left-1'}`}></div>
            </button>
          </div>
        </div>
      </div>

      <div className="px-6 space-y-4">
        <div className="flex items-center justify-between px-2">
           <h4 className="text-gold-light text-sm font-bold tracking-[0.2em] font-serif uppercase border-l-2 border-gold-main pl-3">今日功课</h4>
           <div className="flex items-baseline gap-1">
              <span className="text-gold-main text-lg font-bold">{totalToday}</span>
              <span className="text-stone-600 text-[10px] uppercase font-bold">Rounds</span>
           </div>
        </div>

        <div className="bg-black/20 rounded-3xl border border-white/5 overflow-hidden">
          {todayItems.length > 0 ? (
            <div className="divide-y divide-white/5">
              {todayItems.map((item, idx) => (
                <div key={idx} className="flex items-center justify-between p-4 hover:bg-white/[0.02] transition-colors">
                  <div className="flex flex-col">
                    <span className="text-stone-200 text-sm font-medium tracking-wide">{item.title}</span>
                    <span className="text-stone-600 text-[10px] tracking-widest mt-0.5">{item.subtitle}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-gold-main font-bold text-lg">{item.count}</span>
                    <span className="text-stone-700 text-[10px] font-serif">遍</span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="py-12 flex flex-col items-center justify-center opacity-20">
               <span className="material-symbols-outlined text-4xl mb-2">hourglass_empty</span>
               <p className="text-xs tracking-[0.3em] uppercase">今日暂无记录</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Profile;

import React from 'react';
import { Track } from '../types';

interface SettingsProps {
  currentTrack: Track;
  isPlaying: boolean;
  onTogglePlay: () => void;
  onNext: () => void;
  onPrev: () => void;
  onUpdateTarget: (target: number) => void;
  onStopTask: () => void;
  taskProgress: number;
  taskTarget: number;
  currentTime: number;
  duration: number;
}

const Settings: React.FC<SettingsProps> = ({ 
  currentTrack, isPlaying, onTogglePlay, onNext, onPrev, onUpdateTarget, onStopTask, 
  taskProgress, taskTarget, currentTime, duration 
}) => {
  const presets = [7, 21, 49, 108];
  const isTaskActive = taskTarget > 0;

  const size = 300;
  const radius = 110;
  const center = size / 2;
  const dashArray = 2 * Math.PI * radius;

  const currentRepProgress = duration > 0 ? currentTime / duration : 0;
  const totalProgressRatio = isTaskActive 
    ? Math.min(((taskProgress - 1) + currentRepProgress) / taskTarget, 1) 
    : 0;

  const dashOffset = dashArray * (1 - totalProgressRatio);

  const renderTicks = () => {
    if (!isTaskActive) return null;
    const ticks = [];
    const n = taskTarget;
    for (let i = 0; i < n; i++) {
      const angle = (i * 360 / n) - 90;
      const angleRad = (angle * Math.PI) / 180;
      const innerR = radius - 8;
      const outerR = radius + 2;
      const x1 = center + innerR * Math.cos(angleRad);
      const y1 = center + innerR * Math.sin(angleRad);
      const x2 = center + outerR * Math.cos(angleRad);
      const y2 = center + outerR * Math.sin(angleRad);
      const tickProgressRatio = i / n;
      const isPassed = totalProgressRatio >= tickProgressRatio;
      const isCurrent = i === (taskProgress - 1);
      ticks.push(
        <line 
          key={i} 
          x1={x1} y1={y1} x2={x2} y2={y2} 
          stroke={isPassed ? "#D4AF37" : (isCurrent ? "#F9Eea5" : "rgba(212, 175, 55, 0.1)")} 
          strokeWidth={isPassed ? "2" : "1"} 
          strokeLinecap="round" 
        />
      );
    }
    return ticks;
  };

  return (
    <div className="flex-1 flex flex-col bg-zen-dark pb-32 overflow-x-hidden pt-16">
      <div className="flex-1 flex flex-col items-center justify-around px-6">
        {/* 顶部选曲状态 */}
        <div className="flex flex-col items-center gap-6 w-full">
          <div className="flex items-center justify-between w-full max-w-[320px]">
            <button onClick={onPrev} className="w-10 h-10 rounded-full flex items-center justify-center text-gold-dark/40 hover:text-gold-main active:scale-90 transition-all">
              <span className="material-symbols-outlined text-4xl">chevron_left</span>
            </button>
            <div className="relative">
              <div className={`w-24 h-24 rounded-full border-2 p-1 bg-[#0c0805] overflow-hidden relative z-10 transition-all duration-500 ${isTaskActive ? 'border-gold-main' : 'border-white/10'}`}>
                <img className="w-full h-full rounded-full object-cover grayscale-[0.1]" src={currentTrack.imageUrl} alt={currentTrack.title} />
              </div>
            </div>
            <button onClick={onNext} className="w-10 h-10 rounded-full flex items-center justify-center text-gold-dark/40 hover:text-gold-main active:scale-90 transition-all">
              <span className="material-symbols-outlined text-4xl">chevron_right</span>
            </button>
          </div>
          <div className="text-center">
            <h3 className="text-gold-light font-bold text-xl tracking-[0.2em] font-serif">{currentTrack.title}</h3>
            <p className="text-stone-600 text-[10px] mt-1 tracking-[0.4em] font-serif uppercase opacity-60">念佛持咒，精进修行</p>
          </div>
        </div>

        {/* 核心进度圆环 */}
        <div className="relative flex flex-col items-center">
          <div 
            className="relative flex items-center justify-center cursor-pointer group"
            style={{ width: size, height: size }}
            onClick={() => isTaskActive ? onTogglePlay() : null}
          >
            <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="absolute inset-0">
              <defs>
                <linearGradient id="goldProgressGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#fcf6ba" /><stop offset="50%" stopColor="#bf953f" /><stop offset="100%" stopColor="#aa771c" />
                </linearGradient>
              </defs>
              <circle cx={center} cy={center} r={radius} fill="transparent" stroke="rgba(255,255,255,0.02)" strokeWidth="1" />
              {renderTicks()}
              <circle 
                cx={center} cy={center} r={radius} fill="transparent" 
                stroke="url(#goldProgressGrad)" strokeWidth="5" 
                strokeDasharray={dashArray} strokeDashoffset={dashOffset} 
                strokeLinecap="round" transform={`rotate(-90 ${center} ${center})`} 
                className={`transition-all duration-150 ease-linear ${!isPlaying && isTaskActive ? 'animate-pulse-gentle opacity-60' : ''}`} 
              />
            </svg>

            <div className="flex flex-col items-center z-10 select-none">
              <div className="flex items-baseline gap-1">
                <span className="text-7xl font-bold text-transparent bg-clip-text bg-gold-metal tracking-tighter drop-shadow-2xl">{taskProgress || 0}</span>
                {isTaskActive && <span className="text-2xl font-semibold text-gold-main/20">/{taskTarget}</span>}
              </div>

              {isTaskActive ? (
                <div className="mt-4 flex flex-col items-center">
                   <span className="material-symbols-outlined text-gold-main/60 text-2xl animate-pulse">
                     {isPlaying ? 'pause' : 'play_arrow'}
                   </span>
                   <p className="text-[10px] font-bold text-gold-main/50 mt-1 uppercase tracking-[0.6em] font-serif">
                     {isPlaying ? '正在修持' : '已暂停'}
                   </p>
                </div>
              ) : (
                <p className="text-[10px] font-bold text-gold-main/50 mt-4 uppercase tracking-[0.6em] font-serif">请设定遍数</p>
              )}
            </div>
          </div>

          {/* 停止/重置按钮 - 仅在任务激活时显示 */}
          {isTaskActive && (
            <button 
              onClick={(e) => { e.stopPropagation(); onStopTask(); }}
              className="mt-4 px-6 py-2 rounded-full border border-gold-dark/20 text-stone-600 text-[10px] font-serif tracking-[0.4em] uppercase hover:text-gold-main hover:border-gold-main/40 transition-all flex items-center gap-2"
            >
              <span className="material-symbols-outlined text-sm">stop</span>
              终结本次功课
            </button>
          )}
        </div>

        {/* 快速设定按钮 */}
        <div className="grid grid-cols-2 gap-4 w-full max-w-[340px] px-2 mb-4">
          {presets.map((p) => (
            <button key={p} onClick={() => onUpdateTarget(p)} className={`h-16 rounded-2xl flex flex-col items-center justify-center transition-all duration-300 border font-serif active:scale-95 relative overflow-hidden group ${taskTarget === p ? 'bg-gold-metal text-[#3d2b1f] border-gold-light font-bold shadow-xl' : 'bg-white/[0.02] text-stone-500 border-white/5 hover:bg-white/[0.05]'}`}>
              <span className="text-xl tracking-widest relative z-10">{p}遍</span>
            </button>
          ))}
        </div>
        <div className="mt-2 text-stone-700 text-[10px] tracking-[0.4em] font-serif text-center opacity-40 italic">都摄六根，净念相继</div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect, useRef } from 'react';
import { View, Track } from './types';
import { TRACKS } from './constants';
import BottomNav from './components/BottomNav';
import Player from './components/Player';
import Playlist from './components/Playlist';
import Settings from './components/Settings';
import Profile from './components/Profile';
import MeritAnimation from './components/MeritAnimation';
import ShareCard from './components/ShareCard';
import { getZenQuote, ZenQuote } from './services/zenQuoteService';

const STATS_KEY = 'zen_chant_user_stats';
const CONFIG_KEY = 'zen_chant_config';

const App: React.FC = () => {
  const [view, setView] = useState<View>(View.PLAYER);
  const [currentTrack, setCurrentTrack] = useState<Track>(TRACKS[0]);
  const [isPlaying, setIsPlaying] = useState(true); 
  const [zenQuote, setZenQuote] = useState<ZenQuote>(getZenQuote());
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.65);
  const [isSingleLoop, setIsSingleLoop] = useState(true); 

  // 功德目标与进度
  const [taskTarget, setTaskTarget] = useState(0);
  const [taskProgress, setTaskProgress] = useState(0);
  const [showMerit, setShowMerit] = useState(false);
  const [showShare, setShowShare] = useState(false);

  // 配置项
  const [isLargeText, setIsLargeText] = useState(() => {
    const saved = localStorage.getItem(CONFIG_KEY);
    return saved ? JSON.parse(saved).isLargeText : false;
  });

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    localStorage.setItem(CONFIG_KEY, JSON.stringify({ isLargeText }));
  }, [isLargeText]);

  // 初始化统计数据
  const [stats, setStats] = useState(() => {
    const saved = localStorage.getItem(STATS_KEY);
    if (saved) return JSON.parse(saved);
    return {
      installDate: new Date().toISOString(),
      totalCompletions: 0,
      dailyLogs: {} 
    };
  });

  useEffect(() => {
    localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  }, [stats]);

  const recordCompletion = (trackId: string) => {
    const today = new Date().toISOString().split('T')[0];
    setStats(prev => {
      const newDailyLogs = { ...prev.dailyLogs };
      if (!newDailyLogs[today]) newDailyLogs[today] = {};
      newDailyLogs[today][trackId] = (newDailyLogs[today][trackId] || 0) + 1;

      return {
        ...prev,
        totalCompletions: prev.totalCompletions + 1,
        dailyLogs: newDailyLogs
      };
    });
  };

  const isTaskActive = taskTarget > 0;

  useEffect(() => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.play().catch(() => setIsPlaying(false));
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume, currentTrack, view]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.load();
      if (isPlaying) {
        audioRef.current.play().catch(() => {});
      }
    }
    setTaskProgress(isTaskActive ? 1 : 0);
  }, [currentTrack.id]);

  const handleTrackSelect = (track: Track) => {
    setCurrentTrack(track);
    setIsPlaying(true);
    setView(View.PLAYER);
    setTaskTarget(0);
    setTaskProgress(0);
  };

  const handleNext = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const nextTrack = TRACKS[(idx + 1) % TRACKS.length];
      setCurrentTrack(nextTrack);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const prevTrack = TRACKS[(idx - 1 + TRACKS.length) % TRACKS.length];
      setCurrentTrack(prevTrack);
      setIsPlaying(true);
    }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration || 0);
    }
  };

  const handleEnded = () => {
    recordCompletion(currentTrack.id);
    if (taskTarget > 0) {
      if (taskProgress < taskTarget) {
        setTaskProgress(prev => prev + 1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
          audioRef.current.play();
        }
      } else {
        setIsPlaying(false);
        setTaskTarget(0);
        setTaskProgress(0);
        setShowMerit(true); // 触发功德圆满动画
      }
    } else if (!isSingleLoop) {
      handleNext();
    }
  };

  const updateTaskTarget = (target: number) => {
    if (taskProgress === 0) {
        setTaskProgress(1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
        }
    }
    setTaskTarget(target);
    setIsSingleLoop(false);
    setIsPlaying(true);
    if (audioRef.current && audioRef.current.paused) {
      audioRef.current.play();
    }
  };

  const stopTask = () => {
    setTaskTarget(0);
    setTaskProgress(0);
    setIsPlaying(false);
  };

  const handleRefreshQuote = () => {
    setZenQuote(getZenQuote());
  };

  const renderContent = () => {
    switch (view) {
      case View.PLAYER:
        return (
          <Player 
            track={currentTrack} 
            isPlaying={isPlaying} 
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            currentTime={currentTime}
            duration={duration}
            volume={volume}
            setVolume={setVolume}
            isLargeText={isLargeText}
          />
        );
      case View.PLAYLIST:
        return (
          <Playlist 
            currentTrackId={currentTrack.id} 
            onTrackSelect={handleTrackSelect}
            isLargeText={isLargeText}
          />
        );
      case View.TIMER:
        return (
          <Settings 
            currentTrack={currentTrack} 
            isPlaying={isPlaying}
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            onUpdateTarget={updateTaskTarget}
            onStopTask={stopTask}
            taskProgress={taskProgress}
            taskTarget={taskTarget}
            currentTime={currentTime}
            duration={duration}
          />
        );
      case View.PROFILE:
        return (
          <Profile 
            stats={stats} 
            zenQuote={zenQuote} 
            onRefreshQuote={handleRefreshQuote}
            isLargeText={isLargeText}
            onToggleLargeText={() => setIsLargeText(!isLargeText)}
            onOpenShare={() => setShowShare(true)}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col w-full max-w-md mx-auto min-h-screen relative shadow-2xl bg-zen-dark overflow-hidden">
      {/* 沉浸式背景动态层 */}
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute inset-0 bg-wood-grain mix-blend-overlay opacity-20"></div>
        {/* 动态烟雾效果 */}
        <div className="absolute top-1/4 -left-1/4 w-[150%] h-1/2 bg-gradient-to-r from-transparent via-white/5 to-transparent blur-[100px] animate-smoke-flow rotate-12"></div>
        <div className="absolute bottom-1/4 -right-1/4 w-[150%] h-1/2 bg-gradient-to-l from-transparent via-gold-main/5 to-transparent blur-[80px] animate-smoke-flow -rotate-6 animation-delay-5000"></div>
      </div>

      <audio 
        ref={audioRef}
        src={currentTrack.audioUrl}
        onTimeUpdate={handleTimeUpdate}
        onEnded={handleEnded}
        loop={isSingleLoop && taskTarget === 0} 
      />

      {renderContent()}

      <BottomNav activeView={view} onViewChange={setView} />

      {/* 全屏功德圆满动画 */}
      {showMerit && <MeritAnimation onComplete={() => setShowMerit(false)} />}

      {/* 智慧分享卡 */}
      {showShare && <ShareCard quote={zenQuote} onClose={() => setShowShare(false)} />}
    </div>
  );
};

export default App;

import React from 'react';
import { TRACKS } from '../constants';
import { ZenQuote } from '../services/zenQuoteService';

interface ProfileProps {
  stats: {
    installDate: string;
    totalCompletions: number;
    dailyLogs: { [date: string]: { [trackId: string]: number } };
  };
  zenQuote: ZenQuote;
  onRefreshQuote: () => void;
  isLargeText: boolean;
  onToggleLargeText: () => void;
  onOpenShare: () => void;
}

const Profile: React.FC<ProfileProps> = ({ 
  stats, 
  zenQuote, 
  onRefreshQuote, 
  isLargeText, 
  onToggleLargeText, 
  onOpenShare 
}) => {
  const today = new Date().toISOString().split('T')[0];
  const todayStats: Record<string, number> = stats.dailyLogs[today] || {};

  const calculateDays = () => {
    const start = new Date(stats.installDate).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    return diff + 1;
  };

  const todayItems = (Object.entries(todayStats) as [string, number][])
    .map(([trackId, count]) => {
      const track = TRACKS.find(t => t.id === trackId);
      return {
        title: track?.title || '自定义曲目',
        subtitle: track?.subtitle || '',
        count
      };
    })
    .sort((a, b) => b.count - a.count);

  return (
    <div className="flex-1 flex flex-col overflow-y-auto pb-32 pt-20">
      {/* 头部：修行者信息与极简结缘天数 */}
