            <button 
              onClick={onOpenShare} 
              className="text-[10px] text-stone-600 uppercase tracking-[0.4em] hover:text-gold-main transition-colors flex items-center gap-1.5"
            >
              <span className="material-symbols-outlined text-sm">share</span>
              分享
            </button>
          </div>
        </div>
      </div>

      {/* 功课列表：只保留今日每项曲目的记录 */}
      <div className="px-8 space-y-6">
        <div className="flex items-center justify-between border-b border-white/5 pb-4">
           <h4 className="text-stone-500 text-[11px] font-bold tracking-[0.3em] font-serif uppercase">今日修持记录</h4>
        </div>

        <div className="space-y-1">
