                  <span className={`text-stone-200 font-serif tracking-wide group-hover:text-gold-main transition-colors ${isLargeText ? 'text-lg' : 'text-base'}`}>
                    {item.title}
                  </span>
                  <span className="text-stone-600 text-[10px] tracking-widest mt-1 opacity-60">
                    {item.subtitle}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-gold-main/80 font-display font-medium text-xl">{item.count}</span>
                  <span className="text-stone-700 text-[10px] font-serif">遍</span>
                </div>
              </div>
            ))
          ) : (
            <div className="py-12 flex flex-col items-center justify-center opacity-10">
               <span className="material-symbols-outlined text-3xl mb-3">quiet_times</span>
               <p className="text-[10px] tracking-[0.4em] uppercase">今日虚度，尚未用功</p>
