            className={`w-10 h-5 rounded-full transition-all relative ${isLargeText ? 'bg-gold-main/60' : 'bg-stone-900'}`}
          >
            <div className={`absolute top-0.5 w-4 h-4 bg-stone-300 rounded-full transition-all shadow-sm ${isLargeText ? 'left-5.5 bg-white' : 'left-0.5'}`}></div>
          </button>
        </div>
      </div>

      {/* 最后的留白感 */}
      <div className="mt-8 text-center">
        <p className="text-[#3d2b1f] text-[9px] tracking-[0.8em] font-serif uppercase opacity-30">
          万缘放下 · 一心念佛
        </p>
      </div>
    </div>
  );
};

export default Profile;

import React from 'react';
import { Track } from '../types';

interface SettingsProps {
  currentTrack: Track;
  isPlaying: boolean;
  onTogglePlay: () => void;
  onNext: () => void;
  onPrev: () => void;
  onUpdateTarget: (target: number) => void;
  onStopTask: () => void;
  taskProgress: number;
  taskTarget: number;
  currentTime: number;
  duration: number;
  isLargeText?: boolean;
}

const Settings: React.FC<SettingsProps> = ({ 
  currentTrack, isPlaying, onTogglePlay, onNext, onPrev, onUpdateTarget, onStopTask, 
  taskProgress, taskTarget, currentTime, duration, isLargeText 
}) => {
  const presets = [7, 21, 49, 108];
  const isTaskActive = taskTarget > 0;

  const size = 300;
  const radius = 110;
  const center = size / 2;
  const dashArray = 2 * Math.PI * radius;

  const currentRepProgress = duration > 0 ? currentTime / duration : 0;
  const totalProgressRatio = isTaskActive 
    ? Math.min(((taskProgress - 1) + currentRepProgress) / taskTarget, 1) 
    : 0;

  const dashOffset = dashArray * (1 - totalProgressRatio);

  const renderTicks = () => {
    if (!isTaskActive) return null;
    const ticks = [];
    const n = taskTarget;
    for (let i = 0; i < n; i++) {
      const angle = (i * 360 / n) - 90;
      const angleRad = (angle * Math.PI) / 180;
      const innerR = radius - 8;
      const outerR = radius + 2;
      const x1 = center + innerR * Math.cos(angleRad);
      const y1 = center + innerR * Math.sin(angleRad);
      const x2 = center + outerR * Math.cos(angleRad);
      const y2 = center + outerR * Math.sin(angleRad);
      const tickProgressRatio = i / n;
      const isPassed = totalProgressRatio >= tickProgressRatio;
      const isCurrent = i === (taskProgress - 1);
      ticks.push(
        <line 
          key={i} 
          x1={x1} y1={y1} x2={x2} y2={y2} 
          stroke={isPassed ? "#D4AF37" : (isCurrent ? "#F9Eea5" : "rgba(212, 175, 55, 0.1)")} 
          strokeWidth={isPassed ? "2" : "1"} 
          strokeLinecap="round" 
        />
      );
    }
    return ticks;
  };

  return (
    <div className="flex-1 flex flex-col bg-zen-dark pb-32 overflow-x-hidden pt-16">
      <div className="flex-1 flex flex-col items-center justify-around px-6">
        {/* 顶部选曲状态 */}
        <div className="flex flex-col items-center gap-6 w-full">
          <div className="flex items-center justify-between w-full max-w-[320px]">
            <button onClick={onPrev} className="w-10 h-10 rounded-full flex items-center justify-center text-gold-dark/40 hover:text-gold-main active:scale-90 transition-all">
              <span className="material-symbols-outlined text-4xl">chevron_left</span>
            </button>
            <div className="relative">
              <div className={`w-24 h-24 rounded-full border-2 p-1 bg-[#0c0805] overflow-hidden relative z-10 transition-all duration-500 ${isTaskActive ? 'border-gold-main' : 'border-white/10'}`}>
                <img className="w-full h-full rounded-full object-cover grayscale-[0.1]" src={currentTrack.imageUrl} alt={currentTrack.title} />
              </div>
            </div>
            <button onClick={onNext} className="w-10 h-10 rounded-full flex items-center justify-center text-gold-dark/40 hover:text-gold-main active:scale-90 transition-all">
              <span className="material-symbols-outlined text-4xl">chevron_right</span>
            </button>
          </div>
          <div className="text-center">
            <h3 className={`text-gold-light font-bold tracking-[0.2em] font-serif transition-all ${isLargeText ? 'text-3xl' : 'text-xl'}`}>{currentTrack.title}</h3>
            <p className={`text-stone-600 mt-1 tracking-[0.4em] font-serif uppercase opacity-60 transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>念佛持咒，精进修行</p>
          </div>
        </div>

        {/* 核心进度圆环 */}
        <div className="relative flex flex-col items-center">
          <div 
            className="relative flex items-center justify-center cursor-pointer group"
            style={{ width: size, height: size }}
            onClick={() => isTaskActive ? onTogglePlay() : null}
          >
            <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="absolute inset-0">
              <defs>
                <linearGradient id="goldProgressGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#fcf6ba" /><stop offset="50%" stopColor="#bf953f" /><stop offset="100%" stopColor="#aa771c" />
                </linearGradient>
              </defs>
              <circle cx={center} cy={center} r={radius} fill="transparent" stroke="rgba(255,255,255,0.02)" strokeWidth="1" />
              {renderTicks()}
              <circle 
                cx={center} cy={center} r={radius} fill="transparent" 
                stroke="url(#goldProgressGrad)" strokeWidth="5" 
                strokeDasharray={dashArray} strokeDashoffset={dashOffset} 
                strokeLinecap="round" transform={`rotate(-90 ${center} ${center})`} 
                className={`transition-all duration-150 ease-linear ${!isPlaying && isTaskActive ? 'animate-pulse-gentle opacity-60' : ''}`} 
              />
            </svg>

            <div className="flex flex-col items-center z-10 select-none">
              <div className="flex items-baseline gap-1">
                <span className={`font-bold text-transparent bg-clip-text bg-gold-metal tracking-tighter drop-shadow-2xl transition-all ${isLargeText ? 'text-8xl' : 'text-7xl'}`}>
                  {taskProgress || 0}
                </span>
                {isTaskActive && <span className={`font-semibold text-gold-main/20 transition-all ${isLargeText ? 'text-3xl' : 'text-2xl'}`}>/{taskTarget}</span>}
              </div>

              {isTaskActive ? (
                <div className="mt-4 flex flex-col items-center">
                   <span className="material-symbols-outlined text-gold-main/60 text-2xl animate-pulse">
                     {isPlaying ? 'pause' : 'play_arrow'}
                   </span>
                   <p className={`font-bold text-gold-main/50 mt-1 uppercase tracking-[0.6em] font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>
                     {isPlaying ? '正在播放' : '已暂停'}
                   </p>
                </div>
              ) : (
                <p className={`font-bold text-gold-main/50 mt-4 uppercase tracking-[0.6em] font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>请设定遍数</p>
              )}
            </div>
          </div>

          {/* 停止/重置按钮 - 仅在任务激活时显示 */}
          {isTaskActive && (
            <button 
              onClick={(e) => { e.stopPropagation(); onStopTask(); }}
              className={`mt-4 px-6 py-2 rounded-full border border-gold-dark/20 text-stone-600 font-serif tracking-[0.4em] uppercase hover:text-gold-main hover:border-gold-main/40 transition-all flex items-center gap-2 ${isLargeText ? 'text-sm' : 'text-[10px]'}`}
            >
              <span className="material-symbols-outlined text-sm">stop</span>
              结束本轮播放
            </button>
          )}
        </div>

        {/* 快速设定按钮 */}
        <div className="grid grid-cols-2 gap-4 w-full max-w-[340px] px-2 mb-4">
          {presets.map((p) => (
            <button key={p} onClick={() => onUpdateTarget(p)} className={`h-16 rounded-2xl flex flex-col items-center justify-center transition-all duration-300 border font-serif active:scale-95 relative overflow-hidden group ${taskTarget === p ? 'bg-gold-metal text-[#3d2b1f] border-gold-light font-bold shadow-xl' : 'bg-white/[0.02] text-stone-500 border-white/5 hover:bg-white/[0.05]'}`}>
              <span className={`tracking-widest relative z-10 transition-all ${isLargeText ? 'text-2xl' : 'text-xl'}`}>{p}遍</span>
            </button>
          ))}
        </div>
        <div className={`mt-2 text-stone-700 tracking-[0.4em] font-serif text-center opacity-40 italic transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>都摄六根，净念相继</div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect, useRef } from 'react';
import { View, Track } from './types';
import { TRACKS } from './constants';
import BottomNav from './components/BottomNav';
import Player from './components/Player';
import Playlist from './components/Playlist';
import Settings from './components/Settings';
import Profile from './components/Profile';
import MeritAnimation from './components/MeritAnimation';
import ShareCard from './components/ShareCard';
import { getZenQuote, ZenQuote } from './services/zenQuoteService';

const STATS_KEY = 'zen_chant_user_stats';
const CONFIG_KEY = 'zen_chant_config';

const App: React.FC = () => {
  const [view, setView] = useState<View>(View.PLAYER);
  const [currentTrack, setCurrentTrack] = useState<Track>(TRACKS[0]);
  const [isPlaying, setIsPlaying] = useState(true); 
  const [zenQuote, setZenQuote] = useState<ZenQuote>(getZenQuote());
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.65);
  const [isSingleLoop, setIsSingleLoop] = useState(true); 

  // 功德目标与进度
  const [taskTarget, setTaskTarget] = useState(0);
  const [taskProgress, setTaskProgress] = useState(0);
  const [showMerit, setShowMerit] = useState(false);
  const [showShare, setShowShare] = useState(false);

  // 配置项
  const [isLargeText, setIsLargeText] = useState(() => {
    const saved = localStorage.getItem(CONFIG_KEY);
    return saved ? JSON.parse(saved).isLargeText : false;
  });

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    localStorage.setItem(CONFIG_KEY, JSON.stringify({ isLargeText }));
  }, [isLargeText]);

  // 初始化统计数据
  const [stats, setStats] = useState(() => {
    const saved = localStorage.getItem(STATS_KEY);
    if (saved) return JSON.parse(saved);
    return {
      installDate: new Date().toISOString(),
      totalCompletions: 0,
      dailyLogs: {} 
    };
  });

  useEffect(() => {
    localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  }, [stats]);

  const recordCompletion = (trackId: string) => {
    const today = new Date().toISOString().split('T')[0];
    setStats(prev => {
      const newDailyLogs = { ...prev.dailyLogs };
      if (!newDailyLogs[today]) newDailyLogs[today] = {};
      newDailyLogs[today][trackId] = (newDailyLogs[today][trackId] || 0) + 1;

      return {
        ...prev,
        totalCompletions: prev.totalCompletions + 1,
        dailyLogs: newDailyLogs
      };
    });
  };

  const isTaskActive = taskTarget > 0;

  useEffect(() => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.play().catch(() => setIsPlaying(false));
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume, currentTrack, view]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.load();
      if (isPlaying) {
        audioRef.current.play().catch(() => {});
      }
    }
    setTaskProgress(isTaskActive ? 1 : 0);
  }, [currentTrack.id]);

  const handleTrackSelect = (track: Track) => {
    setCurrentTrack(track);
    setIsPlaying(true);
    setView(View.PLAYER);
    setTaskTarget(0);
    setTaskProgress(0);
  };

  const handleNext = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const nextTrack = TRACKS[(idx + 1) % TRACKS.length];
      setCurrentTrack(nextTrack);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const prevTrack = TRACKS[(idx - 1 + TRACKS.length) % TRACKS.length];
      setCurrentTrack(prevTrack);
      setIsPlaying(true);
    }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration || 0);
    }
  };

  const handleEnded = () => {
    recordCompletion(currentTrack.id);
    if (taskTarget > 0) {
      if (taskProgress < taskTarget) {
        setTaskProgress(prev => prev + 1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
          audioRef.current.play();
        }
      } else {
        setIsPlaying(false);
        setTaskTarget(0);
        setTaskProgress(0);
        setShowMerit(true); // 触发功德圆满动画
      }
    } else if (!isSingleLoop) {
      handleNext();
    }
  };

  const updateTaskTarget = (target: number) => {
    if (taskProgress === 0) {
        setTaskProgress(1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
        }
    }
    setTaskTarget(target);
    setIsSingleLoop(false);
    setIsPlaying(true);
    if (audioRef.current && audioRef.current.paused) {
      audioRef.current.play();
    }
  };

  const stopTask = () => {
    setTaskTarget(0);
    setTaskProgress(0);
    setIsPlaying(false);
  };

  const handleRefreshQuote = () => {
    setZenQuote(getZenQuote());
  };

  const renderContent = () => {
    switch (view) {
      case View.PLAYER:
        return (
          <Player 
            track={currentTrack} 
            isPlaying={isPlaying} 
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            currentTime={currentTime}
            duration={duration}
            volume={volume}
            setVolume={setVolume}
            isLargeText={isLargeText}
          />
        );
      case View.PLAYLIST:
        return (
          <Playlist 
            currentTrackId={currentTrack.id} 
            onTrackSelect={handleTrackSelect}
            isLargeText={isLargeText}
          />
        );
      case View.TIMER:
        return (
          <Settings 
            currentTrack={currentTrack} 
            isPlaying={isPlaying}
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            onUpdateTarget={updateTaskTarget}
            onStopTask={stopTask}
            taskProgress={taskProgress}
            taskTarget={taskTarget}
            currentTime={currentTime}
            duration={duration}
            isLargeText={isLargeText}
          />
        );
      case View.PROFILE:
        return (
          <Profile 
            stats={stats} 
            zenQuote={zenQuote} 
            onRefreshQuote={handleRefreshQuote}
            isLargeText={isLargeText}
            onToggleLargeText={() => setIsLargeText(!isLargeText)}
            onOpenShare={() => setShowShare(true)}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col w-full max-w-md mx-auto min-h-screen relative shadow-2xl bg-zen-dark overflow-hidden">
      {/* 沉浸式背景动态层 */}
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute inset-0 bg-wood-grain mix-blend-overlay opacity-20"></div>
        {/* 动态烟雾效果 */}
        <div className="absolute top-1/4 -left-1/4 w-[150%] h-1/2 bg-gradient-to-r from-transparent via-white/5 to-transparent blur-[100px] animate-smoke-flow rotate-12"></div>
        <div className="absolute bottom-1/4 -right-1/4 w-[150%] h-1/2 bg-gradient-to-l from-transparent via-gold-main/5 to-transparent blur-[80px] animate-smoke-flow -rotate-6 animation-delay-5000"></div>
      </div>

      <audio 
        ref={audioRef}
        src={currentTrack.audioUrl}
        onTimeUpdate={handleTimeUpdate}
        onEnded={handleEnded}
        loop={isSingleLoop && taskTarget === 0} 
      />

      {renderContent()}

      <BottomNav activeView={view} onViewChange={setView} />

      {/* 全屏功德圆满动画 */}
      {showMerit && <MeritAnimation onComplete={() => setShowMerit(false)} />}

      {/* 智慧分享卡 */}
      {showShare && <ShareCard quote={zenQuote} onClose={() => setShowShare(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Track } from '../types';
import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
  isLargeText?: boolean;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';
const AUDIO_CACHE_NAME = 'zen-chant-audio';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId, isLargeText }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');

  // 离线同步状态
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'completed'>('idle');
  const [syncProgress, setSyncProgress] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }

    // 检查缓存状态
    checkCacheStatus();
  }, []);

  const checkCacheStatus = async () => {
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      const keys = await cache.keys();
      // 如果已缓存数量等于官方曲目数量，标记为已完成
      if (keys.length >= TRACKS.length) {
        setSyncStatus('completed');
      }
    } catch (e) {
      console.error("Cache check failed", e);
    }
  };

  const handleOfflineSync = async () => {
    if (syncStatus === 'syncing') return;

    setSyncStatus('syncing');
    setSyncProgress(0);

    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      let count = 0;

      for (const track of TRACKS) {
        try {
          // 检查是否已缓存
          const match = await cache.match(track.audioUrl);
          if (!match) {
            await cache.add(track.audioUrl);
          }
        } catch (err) {
          console.warn(`Failed to sync track: ${track.title}`, err);
        }
        count++;
        setSyncProgress(Math.round((count / TRACKS.length) * 100));
      }

      setSyncStatus('completed');
    } catch (e) {
      console.error("Sync failed", e);
      setSyncStatus('idle');
      alert("同步失败，请检查网络连接后重试。");
    }
  };

  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
    localStorage.setItem(CUSTOM_TRACKS_KEY, JSON.stringify(tracks));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewTrackUrl(url);
      if (!newTrackTitle) {
        setNewTrackTitle(file.name.replace(/\.[^/.]+$/, ""));
      }
    }
  };

  const handleAddTrack = () => {
    if (!newTrackTitle || !newTrackUrl) return;

    const newTrack: Track = {
      id: `custom_${Date.now()}`,
      code: `Z${(customTracks.length + 1).toString().padStart(2, '0')}`,
      title: newTrackTitle,
      subtitle: addMethod === 'file' ? '本地上传' : '网络链接',
      section: 'CUSTOM',
      imageUrl: 'https://www.shouyueliang.org/wp-content/uploads/2021/04/1623587633-v500-4-1.gif',
      audioUrl: newTrackUrl
    };

    saveCustomTracks([...customTracks, newTrack]);
    setShowAddModal(false);
    setNewTrackTitle('');
    setNewTrackUrl('');
  };

  const removeTrack = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = customTracks.filter(t => t.id !== id);
    saveCustomTracks(updated);
  };

  return (
    <div className="flex flex-col h-full bg-dark-gradient overflow-hidden pt-10">
      {/* 顶部标签切换 */}
      <div className="flex-none bg-transparent px-6 mb-2">
        <div className="flex gap-4">
          <button 
            onClick={() => setActiveTab('official')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'official' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-600'}`}
          >
            <p className={`font-bold tracking-[0.1em] font-serif transition-all ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>官方曲目</p>
          </button>
          <button 
            onClick={() => setActiveTab('custom')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'custom' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-600'}`}
          >
            <p className={`font-bold tracking-[0.1em] font-serif transition-all ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>自定义</p>
          </button>
        </div>
      </div>

      {/* 离线同步状态条 (仅在官方曲目页显示) */}
      {activeTab === 'official' && (
        <div className="px-6 py-3">
          <div className="bg-black/40 border border-white/5 rounded-2xl p-3 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className={`material-symbols-outlined text-xl ${syncStatus === 'completed' ? 'text-green-500' : 'text-gold-main'}`}>
                {syncStatus === 'syncing' ? 'sync' : syncStatus === 'completed' ? 'cloud_done' : 'cloud_download'}
              </span>
              <div>
                <p className={`text-stone-300 font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>
                  {syncStatus === 'syncing' ? `正在离线同步 (${syncProgress}%)` : syncStatus === 'completed' ? '已离线 (无网亦可播放)' : '未离线 (建议同步以支持离线)'}
                </p>
                {syncStatus === 'syncing' && (
                  <div className="w-32 h-1 bg-stone-800 rounded-full mt-1 overflow-hidden">
                    <div className="h-full bg-gold-main transition-all duration-300" style={{ width: `${syncProgress}%` }}></div>
                  </div>
                )}
              </div>
            </div>
            {syncStatus !== 'completed' && (
              <button 
                onClick={handleOfflineSync}
                disabled={syncStatus === 'syncing'}
                className={`px-3 py-1 bg-gold-main/10 border border-gold-main/30 rounded-lg text-gold-main font-bold tracking-widest uppercase hover:bg-gold-main/20 disabled:opacity-50 transition-all ${isLargeText ? 'text-xs' : 'text-[10px]'}`}
              >
                {syncStatus === 'syncing' ? '同步中' : '开始同步'}
              </button>
            )}
          </div>
        </div>
      )}

      {/* 滚动列表 */}
      <div className="flex-1 overflow-y-auto pb-32 scroll-smooth">
        {activeTab === 'official' ? (
          SECTIONS.map((section) => (
            <div key={section.id} className="mb-2">
              <div className="sticky top-0 z-30 bg-[#1a1208]/95 backdrop-blur-md px-5 py-3 border-b border-gold-dark/10 shadow-sm">
                <div className="flex items-center gap-3">
                  <span className="bg-gold-main/20 border border-gold-main/40 text-gold-main text-[10px] font-bold px-2 py-0.5 rounded tracking-widest font-display">
                    {section.code}
                  </span>
                  <h3 className={`text-gold-light font-bold font-serif tracking-wider transition-all ${isLargeText ? 'text-xl' : 'text-base'}`}>{section.name}</h3>
                </div>
              </div>

              <div className="flex flex-col divide-y divide-white/5 px-2">
                {TRACKS.filter(t => t.section === section.code).map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.03] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.08]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className={`badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#4a3b18] text-sm font-display shadow-lg border border-[#7c6428]/50 transition-transform ${currentTrackId === track.id ? 'scale-110' : ''}`}>
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        <p className={`font-medium font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-gray-200 group-hover:text-gold-main'} ${isLargeText ? 'text-xl' : 'text-[17px]'}`}>
                          {track.title}
                        </p>
                        <p className={`text-stone-500 tracking-wider font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'}`}>{track.subtitle}</p>
                      </div>
                    </div>
                    <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-[#5d4a1f] group-hover:text-gold-main'}`}>
                      {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          ))
        ) : (
          <div className="px-2 py-4 space-y-4">
            <button 
              onClick={() => setShowAddModal(true)}
              className="w-full flex items-center justify-center gap-3 py-4 rounded-xl border-2 border-dashed border-gold-dark/30 text-gold-main hover:bg-gold-main/5 transition-colors group"
            >
              <span className="material-symbols-outlined text-2xl group-hover:scale-110 transition-transform">add_circle</span>
              <span className={`font-bold tracking-widest font-serif transition-all ${isLargeText ? 'text-xl' : 'text-base'}`}>添加自定义曲目</span>
            </button>

            <div className="flex flex-col divide-y divide-white/5">
              {customTracks.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 opacity-30 text-gold-light">
                  <span className="material-symbols-outlined text-6xl mb-4">music_off</span>
                  <p className={`tracking-widest font-serif transition-all ${isLargeText ? 'text-lg' : 'text-sm'}`}>暂无自定义曲目</p>
                </div>
              ) : (
                customTracks.map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.03] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.08]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className="badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#4a3b18] text-sm font-display shadow-lg border border-[#7c6428]/50">
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        <p className={`font-medium font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-gray-200 group-hover:text-gold-main'} ${isLargeText ? 'text-xl' : 'text-[17px]'}`}>
                          {track.title}
                        </p>
                        <p className={`text-stone-500 tracking-wider font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'}`}>{track.subtitle}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={(e) => removeTrack(e, track.id)}
                        className="text-red-900/40 hover:text-red-500 p-2 transition-colors"
                      >
                        <span className="material-symbols-outlined text-xl">delete</span>
                      </button>
                      <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-[#5d4a1f] group-hover:text-gold-main'}`}>
                        {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                      </span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 backdrop-blur-md bg-black/60">
          <div className="w-full max-w-sm bg-surface-dark border border-gold-dark/30 rounded-[2rem] p-8 shadow-2xl">
            <h3 className={`text-gold-light font-bold font-serif mb-6 text-center tracking-widest transition-all ${isLargeText ? 'text-2xl' : 'text-xl'}`}>添加修行曲目</h3>
            <div className="space-y-6">
              <div className="space-y-2">
                <label className={`text-stone-500 uppercase tracking-widest font-serif ml-1 transition-all ${isLargeText ? 'text-xs' : 'text-[10px]'}`}>曲目名称</label>
                <input 
                  type="text" 
                  value={newTrackTitle}
                  onChange={(e) => setNewTrackTitle(e.target.value)}
                  placeholder="请输入曲目名称"
                  className="w-full bg-black/30 border border-gold-dark/20 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none"
                />
              </div>
              <div className="space-y-3">
                <div className="flex gap-2">
                  <button onClick={() => setAddMethod('url')} className={`flex-1 py-2 rounded-lg font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'} ${addMethod === 'url' ? 'bg-gold-main/20 text-gold-main border border-gold-main/30' : 'bg-black/20 text-stone-500 border border-transparent'}`}>网络链接</button>
                  <button onClick={() => setAddMethod('file')} className={`flex-1 py-2 rounded-lg font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'} ${addMethod === 'file' ? 'bg-gold-main/20 text-gold-main border border-gold-main/30' : 'bg-black/20 text-stone-500 border border-transparent'}`}>本地文件</button>
                </div>
                {addMethod === 'url' ? (
                  <input 
                    type="text" 
                    value={newTrackUrl}
                    onChange={(e) => setNewTrackUrl(e.target.value)}
                    placeholder="https://example.com/audio.mp3"
                    className="w-full bg-black/30 border border-gold-dark/20 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none"
                  />
                ) : (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full bg-black/30 border border-dashed border-gold-dark/20 rounded-xl px-4 py-4 text-center cursor-pointer">
                    <span className={`text-gold-main/60 font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'}`}>{newTrackUrl ? '已选择音频' : '点击上传本地音频'}</span>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="audio/*" className="hidden" />
                  </div>
                )}
              </div>
              <div className="flex gap-3 pt-4">
                <button onClick={() => setShowAddModal(false)} className={`flex-1 py-3 rounded-xl border border-gold-dark/30 text-stone-400 font-serif transition-all ${isLargeText ? 'text-base' : 'text-sm'}`}>取消</button>
                <button onClick={handleAddTrack} disabled={!newTrackTitle || !newTrackUrl} className={`flex-1 py-3 rounded-xl bg-gold-metal text-[#3d2b1f] font-bold font-serif transition-all ${isLargeText ? 'text-base' : 'text-sm'}`}>确认添加</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Playlist;

import React from 'react';
import { TRACKS } from '../constants';
import { ZenQuote } from '../services/zenQuoteService';

interface ProfileProps {
  stats: {
    installDate: string;
    totalCompletions: number;
    dailyLogs: { [date: string]: { [trackId: string]: number } };
  };
  zenQuote: ZenQuote;
  onRefreshQuote: () => void;
  isLargeText: boolean;
  onToggleLargeText: () => void;
  onOpenShare: () => void;
}

const Profile: React.FC<ProfileProps> = ({ 
  stats, 
  zenQuote, 
  onRefreshQuote, 
  isLargeText, 
  onToggleLargeText, 
  onOpenShare 
}) => {
  const today = new Date().toISOString().split('T')[0];
  const todayStats: Record<string, number> = stats.dailyLogs[today] || {};

  const calculateDays = () => {
    const start = new Date(stats.installDate).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    return diff + 1;
  };

  const todayItems = (Object.entries(todayStats) as [string, number][])
    .map(([trackId, count]) => {
      const track = TRACKS.find(t => t.id === trackId);
      return {
        title: track?.title || '自定义曲目',
        subtitle: track?.subtitle || '',
        count
      };
    })
    .sort((a, b) => b.count - a.count);

  return (
    <div className="flex-1 flex flex-col overflow-y-auto pb-32 pt-20">
      {/* 头部：修行者信息与极简结缘天数 */}
      <div className="px-8 pb-12 flex flex-col items-center text-center">
        <div className="relative mb-8">
          <div className="absolute inset-[-12px] bg-gold-main/5 blur-3xl rounded-full"></div>
          <div className="w-20 h-20 rounded-full badge-texture flex items-center justify-center text-[#4a3b18] border border-gold-dark/20 shadow-xl relative z-10">
             <span className="material-symbols-outlined text-4xl font-light">person</span>
          </div>
        </div>

        <div className="space-y-2">
          <h3 className={`font-bold text-gold-light tracking-[0.4em] font-serif uppercase transition-all ${isLargeText ? 'text-3xl' : 'text-xl'}`}>
            净土行人
          </h3>
          <p className={`text-stone-600 tracking-[0.2em] font-serif opacity-60 transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>
            已使用此APP {calculateDays()} 日
          </p>
        </div>
      </div>

      {/* 核心：智慧语录（作为界面视觉中心） */}
      <div className="px-10 mb-16">
        <div className="relative px-4 py-8 flex flex-col items-center">
          <span className="absolute top-0 left-0 text-gold-main/20 text-5xl font-serif">“</span>
          <div className="px-4">
            <p className={`text-stone-300 tracking-widest leading-[2] font-serif text-center transition-all ${isLargeText ? 'text-2xl' : 'text-[17px]'}`}>
              {zenQuote.text}
            </p>
            <p className={`text-gold-main/60 tracking-[0.2em] font-serif mt-6 text-right transition-all ${isLargeText ? 'text-lg' : 'text-[12px]'}`}>
              —— {zenQuote.source}
            </p>
          </div>
          <span className="absolute bottom-0 right-0 text-gold-main/20 text-5xl font-serif rotate-180">“</span>

          <div className="flex items-center justify-center gap-8 mt-10">
            <button 
              onClick={onRefreshQuote} 
              className={`text-stone-600 uppercase tracking-[0.4em] hover:text-gold-main transition-all flex items-center gap-1.5 ${isLargeText ? 'text-sm' : 'text-[10px]'}`}
            >
              <span className="material-symbols-outlined text-sm">refresh</span>
              刷新
            </button>
            <button 
              onClick={onOpenShare} 
              className={`text-stone-600 uppercase tracking-[0.4em] hover:text-gold-main transition-all flex items-center gap-1.5 ${isLargeText ? 'text-sm' : 'text-[10px]'}`}
            >
              <span className="material-symbols-outlined text-sm">share</span>
              分享
            </button>
          </div>
        </div>
      </div>

      {/* 功课列表：只保留今日每项曲目的记录 */}
      <div className="px-8 space-y-6">
        <div className="flex items-center justify-between border-b border-white/5 pb-4">
           <h4 className={`text-stone-500 font-bold tracking-[0.3em] font-serif uppercase transition-all ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>今日播放记录</h4>
        </div>

        <div className="space-y-1">
          {todayItems.length > 0 ? (
            todayItems.map((item, idx) => (
              <div key={idx} className="flex items-center justify-between py-4 group">
                <div className="flex flex-col">
                  <span className={`text-stone-200 font-serif tracking-wide group-hover:text-gold-main transition-all ${isLargeText ? 'text-lg' : 'text-base'}`}>
                    {item.title}
                  </span>
                  <span className={`text-stone-600 tracking-widest mt-1 opacity-60 transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>
                    {item.subtitle}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <span className={`text-gold-main/80 font-display font-medium transition-all ${isLargeText ? 'text-2xl' : 'text-xl'}`}>{item.count}</span>
                  <span className={`text-stone-700 font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>遍</span>
                </div>
              </div>
            ))
          ) : (
            <div className="py-12 flex flex-col items-center justify-center opacity-10">
               <span className="material-symbols-outlined text-3xl mb-3">quiet_times</span>
               <p className={`tracking-[0.4em] uppercase transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>今日虚度，尚未用功</p>
            </div>
          )}
        </div>
      </div>

      {/* 底部设置：极简布局 */}
      <div className="mt-16 px-8 mb-8">
        <div className="pt-8 border-t border-white/5 flex items-center justify-between">
          <div className="flex flex-col">
            <span className={`text-stone-500 font-bold tracking-[0.3em] uppercase transition-all ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>大字模式</span>
            <span className={`text-stone-700 mt-1 transition-all ${isLargeText ? 'text-[10px]' : 'text-[9px]'}`}>开启后文字显示更加清晰</span>
          </div>
          <button 
            onClick={onToggleLargeText}
            className={`w-10 h-5 rounded-full transition-all relative ${isLargeText ? 'bg-gold-main/60' : 'bg-stone-900'}`}
          >
            <div className={`absolute top-0.5 w-4 h-4 bg-stone-300 rounded-full transition-all shadow-sm ${isLargeText ? 'left-5.5 bg-white' : 'left-0.5'}`}></div>
          </button>
        </div>
      </div>

      {/* 最后的留白感 */}
      <div className="mt-8 text-center">
        <p className={`text-[#3d2b1f] tracking-[0.8em] font-serif uppercase opacity-30 transition-all ${isLargeText ? 'text-[11px]' : 'text-[9px]'}`}>
          万缘放下 · 一心念佛
        </p>
      </div>
    </div>
  );
};

export default Profile;

