import React from 'react';
import { Track } from '../types';

interface SettingsProps {
  currentTrack: Track;
  isPlaying: boolean;
  onTogglePlay: () => void;
  onNext: () => void;
  onPrev: () => void;
  onUpdateTarget: (target: number) => void;
  onStopTask: () => void;
  taskProgress: number;
  taskTarget: number;
  currentTime: number;
  duration: number;
  isLargeText?: boolean;
}

// Convert to default exported function to ensure standard module compatibility
export default function Settings({ 
  currentTrack, isPlaying, onTogglePlay, onNext, onPrev, onUpdateTarget, onStopTask, 
  taskProgress, taskTarget, currentTime, duration, isLargeText 
}: SettingsProps) {
  const presets = [7, 21, 49, 108];
  const isTaskActive = taskTarget > 0;

  const size = 300;
  const radius = 110;
  const center = size / 2;
  const dashArray = 2 * Math.PI * radius;

  const currentRepProgress = duration > 0 ? currentTime / duration : 0;
  const totalProgressRatio = isTaskActive 
    ? Math.min(((taskProgress - 1) + currentRepProgress) / taskTarget, 1) 
    : 0;

  const dashOffset = dashArray * (1 - totalProgressRatio);

  const renderTicks = () => {
    if (!isTaskActive) return null;
    const ticks = [];
    const n = taskTarget;
    for (let i = 0; i < n; i++) {
      const angle = (i * 360 / n) - 90;
      const angleRad = (angle * Math.PI) / 180;
      const innerR = radius - 8;
      const outerR = radius + 2;
      const x1 = center + innerR * Math.cos(angleRad);
      const y1 = center + innerR * Math.sin(angleRad);
      const x2 = center + outerR * Math.cos(angleRad);
      const y2 = center + outerR * Math.sin(angleRad);
      const tickProgressRatio = i / n;
      const isPassed = totalProgressRatio >= tickProgressRatio;
      const isCurrent = i === (taskProgress - 1);
      ticks.push(
        <line 
          key={i} 
          x1={x1} y1={y1} x2={x2} y2={y2} 
          stroke={isPassed ? "#E5B94B" : (isCurrent ? "#FFF7C2" : "rgba(229, 185, 75, 0.15)")} 
          strokeWidth={isPassed ? "2.5" : "1.5"} 
          strokeLinecap="round" 
        />
      );
    }
    return ticks;
  };

  return (
    <div className="flex-1 flex flex-col bg-zen-dark pb-32 overflow-x-hidden pt-16">
      <div className="flex-1 flex flex-col items-center justify-around px-6">
        {/* 顶部选曲状态 */}
        <div className="flex flex-col items-center gap-6 w-full">
          <div className="flex items-center justify-between w-full max-w-[320px]">
            <button onClick={onPrev} className="w-10 h-10 rounded-full flex items-center justify-center text-gold-main/60 hover:text-gold-main active:scale-90 transition-all">
              <span className="material-symbols-outlined text-4xl">chevron_left</span>
            </button>
            <div className="relative">
              <div className={`w-24 h-24 rounded-full border-2 p-1 bg-[#0c0805] overflow-hidden relative z-10 transition-all duration-500 shadow-xl ${isTaskActive ? 'border-gold-main' : 'border-white/20'}`}>
                <img className="w-full h-full rounded-full object-cover grayscale-[0.1]" src={currentTrack.imageUrl} alt={currentTrack.title} />
              </div>
            </div>
            <button onClick={onNext} className="w-10 h-10 rounded-full flex items-center justify-center text-gold-main/60 hover:text-gold-main active:scale-90 transition-all">
              <span className="material-symbols-outlined text-4xl">chevron_right</span>
            </button>
          </div>
          <div className="text-center">
            <h3 className={`text-gold-light font-bold tracking-[0.2em] font-serif transition-all ${isLargeText ? 'text-3xl' : 'text-xl'}`}>{currentTrack.title}</h3>
            <p className={`text-stone-400 mt-1 tracking-[0.4em] font-serif uppercase opacity-90 transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>念佛持咒，精进修行</p>
          </div>
        </div>

        {/* 核心进度圆环 */}
        <div className="relative flex flex-col items-center">
          <div 
            className="relative flex items-center justify-center cursor-pointer group"
            style={{ width: size, height: size }}
            onClick={() => isTaskActive ? onTogglePlay() : null}
          >
            <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="absolute inset-0">
              <defs>
                <linearGradient id="goldProgressGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#fcf6ba" /><stop offset="50%" stopColor="#bf953f" /><stop offset="100%" stopColor="#aa771c" />
                </linearGradient>
              </defs>
              <circle cx={center} cy={center} r={radius} fill="transparent" stroke="rgba(255,255,255,0.05)" strokeWidth="1" />
              {renderTicks()}
              <circle 
                cx={center} cy={center} r={radius} fill="transparent" 
                stroke="url(#goldProgressGrad)" strokeWidth="6" 
                strokeDasharray={dashArray} strokeDashoffset={dashOffset} 
                strokeLinecap="round" transform={`rotate(-90 ${center} ${center})`} 
                className={`transition-all duration-150 ease-linear ${!isPlaying && isTaskActive ? 'animate-pulse-gentle opacity-70' : ''}`} 
              />
            </svg>

            <div className="flex flex-col items-center z-10 select-none">
              <div className="flex items-baseline gap-1">
                <span className={`font-bold text-transparent bg-clip-text bg-gold-metal tracking-tighter drop-shadow-[0_0_20px_rgba(229,185,75,0.6)] transition-all ${isLargeText ? 'text-8xl' : 'text-7xl'}`}>
                  {taskProgress || 0}
                </span>
                {isTaskActive && <span className={`font-bold text-gold-main/30 transition-all ${isLargeText ? 'text-3xl' : 'text-2xl'}`}>/{taskTarget}</span>}
              </div>

              {isTaskActive ? (
                <div className="mt-4 flex flex-col items-center">
                   <span className="material-symbols-outlined text-gold-main text-2xl animate-pulse">
                     {isPlaying ? 'pause' : 'play_arrow'}
                   </span>
                   <p className={`font-bold text-gold-light mt-1 uppercase tracking-[0.6em] font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>
                     {isPlaying ? '正在播放' : '已暂停'}
                   </p>
                </div>
              ) : (
                <p className={`font-bold text-gold-main/60 mt-4 uppercase tracking-[0.6em] font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>请设定遍数</p>
              )}
            </div>
          </div>

          {/* 停止/重置按钮 - 仅在任务激活时显示 */}
          {isTaskActive && (
            <button 
              onClick={(e) => { e.stopPropagation(); onStopTask(); }}
              className={`mt-4 px-6 py-2 rounded-full border-2 border-gold-dark/40 text-stone-300 font-bold font-serif tracking-[0.4em] uppercase hover:text-gold-main hover:border-gold-main/60 bg-black/40 transition-all flex items-center gap-2 ${isLargeText ? 'text-sm' : 'text-[10px]'}`}
            >
              <span className="material-symbols-outlined text-sm">stop</span>
              结束本轮播放
            </button>
          )}
        </div>

        {/* 快速设定按钮 */}
        <div className="grid grid-cols-2 gap-4 w-full max-w-[340px] px-2 mb-4">
          {presets.map((p) => (
            <button key={p} onClick={() => onUpdateTarget(p)} className={`h-16 rounded-2xl flex flex-col items-center justify-center transition-all duration-300 border font-serif active:scale-95 relative overflow-hidden group ${taskTarget === p ? 'bg-gold-metal text-[#2C1E12] border-gold-light font-bold shadow-xl shadow-gold-main/20 scale-105 z-10' : 'bg-white/[0.04] text-stone-300 border-white/10 hover:bg-white/[0.08]'}`}>
              <span className={`tracking-widest relative z-10 transition-all ${isLargeText ? 'text-2xl' : 'text-xl'}`}>{p}遍</span>
            </button>
          ))}
        </div>
        <div className={`mt-2 text-stone-400 tracking-[0.4em] font-serif text-center opacity-60 italic font-bold transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>都摄六根，净念相继</div>
      </div>
    </div>
  );
}

import React from 'react';
import { TRACKS } from '../constants';
import { ZenQuote } from '../services/zenQuoteService';

interface ProfileProps {
  stats: {
    installDate: string;
    totalCompletions: number;
    dailyLogs: { [date: string]: { [trackId: string]: number } };
  };
  zenQuote: ZenQuote;
  onRefreshQuote: () => void;
  isLargeText: boolean;
  onToggleLargeText: () => void;
  onOpenShare: () => void;
}

// Convert to default exported function to ensure standard module compatibility
export default function Profile({ 
  stats, 
  zenQuote, 
  onRefreshQuote, 
  isLargeText, 
  onToggleLargeText, 
  onOpenShare 
}: ProfileProps) {
  const today = new Date().toISOString().split('T')[0];
  const todayStats: Record<string, number> = stats.dailyLogs[today] || {};

  const calculateDays = () => {
    const start = new Date(stats.installDate).getTime();
    const now = new Date().getTime();
    const diff = Math.floor((now - start) / (1000 * 60 * 60 * 24));
    return diff + 1;
  };

  const todayItems = (Object.entries(todayStats) as [string, number][])
    .map(([trackId, count]) => {
      const track = TRACKS.find(t => t.id === trackId);
      return {
        title: track?.title || '自定义曲目',
        subtitle: track?.subtitle || '',
        count
      };
    })
    .sort((a, b) => b.count - a.count);

  return (
    <div className="flex-1 flex flex-col overflow-y-auto pb-32 pt-20">
      {/* 头部：修行者信息与极简结缘天数 */}
      <div className="px-8 pb-12 flex flex-col items-center text-center">
        <div className="relative mb-8">
          <div className="absolute inset-[-15px] bg-gold-main/10 blur-3xl rounded-full"></div>
          <div className="w-20 h-20 rounded-full badge-texture flex items-center justify-center text-[#2C1E12] border-2 border-gold-dark/40 shadow-2xl relative z-10">
             <span className="material-symbols-outlined text-4xl font-bold">person</span>
          </div>
        </div>

        <div className="space-y-2">
          <h3 className={`font-bold text-gold-light tracking-[0.4em] font-serif uppercase transition-all drop-shadow-lg ${isLargeText ? 'text-3xl' : 'text-xl'}`}>
            净土行人
          </h3>
          <p className={`text-stone-300 font-bold tracking-[0.2em] font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>
            已使用此APP {calculateDays()} 日
          </p>
        </div>
      </div>

      {/* 核心：智慧语录（作为界面视觉中心） */}
      <div className="px-10 mb-16">
        <div className="relative px-4 py-8 flex flex-col items-center">
          <span className="absolute top-0 left-0 text-gold-main/30 text-5xl font-serif">“</span>
          <div className="px-4">
            <p className={`text-stone-100 font-bold tracking-widest leading-[2.2] font-serif text-center transition-all drop-shadow-sm ${isLargeText ? 'text-2xl' : 'text-[18px]'}`}>
              {zenQuote.text}
            </p>
            <p className={`text-gold-main font-bold tracking-[0.2em] font-serif mt-6 text-right transition-all ${isLargeText ? 'text-lg' : 'text-[13px]'}`}>
              —— {zenQuote.source}
            </p>
          </div>
          <span className="absolute bottom-0 right-0 text-gold-main/30 text-5xl font-serif rotate-180">“</span>

          <div className="flex items-center justify-center gap-8 mt-10">
            <button 
              onClick={onRefreshQuote} 
              className={`text-stone-300 font-bold uppercase tracking-[0.4em] hover:text-gold-main transition-all flex items-center gap-1.5 ${isLargeText ? 'text-sm' : 'text-[10px]'}`}
            >
              <span className="material-symbols-outlined text-sm font-bold">refresh</span>
              刷新
            </button>
            <button 
              onClick={onOpenShare} 
              className={`text-stone-300 font-bold uppercase tracking-[0.4em] hover:text-gold-main transition-all flex items-center gap-1.5 ${isLargeText ? 'text-sm' : 'text-[10px]'}`}
            >
              <span className="material-symbols-outlined text-sm font-bold">share</span>
              分享
            </button>
          </div>
        </div>
      </div>

      {/* 功课列表：只保留今日每项曲目的记录 */}
      <div className="px-8 space-y-6">
        <div className="flex items-center justify-between border-b border-white/10 pb-4">
           <h4 className={`text-gold-main/80 font-bold tracking-[0.3em] font-serif uppercase transition-all ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>今日播放记录</h4>
        </div>

        <div className="space-y-1">
          {todayItems.length > 0 ? (
            todayItems.map((item, idx) => (
              <div key={idx} className="flex items-center justify-between py-4 group border-b border-white/[0.03] last:border-0">
                <div className="flex flex-col">
                  <span className={`text-stone-100 font-bold font-serif tracking-wide group-hover:text-gold-main transition-all ${isLargeText ? 'text-lg' : 'text-base'}`}>
                    {item.title}
                  </span>
                  <span className={`text-stone-400 font-bold tracking-widest mt-1 opacity-90 transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>
                    {item.subtitle}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <span className={`text-gold-main font-display font-bold transition-all drop-shadow-[0_0_5px_rgba(229,185,75,0.3)] ${isLargeText ? 'text-2xl' : 'text-xl'}`}>{item.count}</span>
                  <span className={`text-stone-400 font-bold font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[10px]'}`}>遍</span>
                </div>
              </div>
            ))
          ) : (
            <div className="py-12 flex flex-col items-center justify-center opacity-30 text-stone-500">
               <span className="material-symbols-outlined text-4xl mb-3">quiet_times</span>
               <p className={`font-bold tracking-[0.4em] uppercase transition-all ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>今日虚度，尚未用功</p>
            </div>
          )}
        </div>
      </div>

      {/* 底部设置：极简布局 */}
      <div className="mt-16 px-8 mb-8">
        <div className="pt-8 border-t border-white/10 flex items-center justify-between">
          <div className="flex flex-col">
            <span className={`text-stone-300 font-bold tracking-[0.3em] uppercase transition-all ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>大字模式</span>
            <span className={`text-stone-500 font-bold mt-1 transition-all ${isLargeText ? 'text-[10px]' : 'text-[9px]'}`}>开启后文字显示更加清晰</span>
          </div>
          <button 
            onClick={onToggleLargeText}
            className={`w-11 h-6 rounded-full transition-all relative ${isLargeText ? 'bg-gold-main shadow-[0_0_10px_rgba(229,185,75,0.4)]' : 'bg-stone-800'}`}
          >
            <div className={`absolute top-1 w-4 h-4 rounded-full transition-all shadow-sm ${isLargeText ? 'left-6 bg-[#2C1E12]' : 'left-1 bg-stone-400'}`}></div>
          </button>
        </div>
      </div>

      {/* 最后的留白感 */}
      <div className="mt-8 text-center">
        <p className={`text-[#3d2b1f] font-bold tracking-[0.8em] font-serif uppercase opacity-50 transition-all ${isLargeText ? 'text-[11px]' : 'text-[9px]'}`}>
          万缘放下 · 一心念佛
        </p>
      </div>
    </div>
  );
}

