  ];

  return (
    <nav className="fixed bottom-0 w-full max-w-md left-1/2 -translate-x-1/2 bg-[#0a0604]/98 border-t border-gold-dark/20 px-8 pt-4 pb-8 flex justify-between items-center backdrop-blur-xl z-30 shadow-[0_-15px_50px_rgba(0,0,0,0.8)]">
      {items.map((item) => (
        <div
          key={item.id}
          onClick={() => onViewChange(item.id)}
          className="flex flex-col items-center gap-1.5 group cursor-pointer"
        >
          <span className={`material-symbols-outlined text-[26px] transition-all group-active:scale-90 ${activeView === item.id ? 'text-gold-main fill-1 drop-shadow-[0_0_8px_rgba(229,185,75,0.4)]' : 'text-stone-400 group-hover:text-stone-300'}`}>
            {item.icon}
          </span>
          <span className={`text-[10px] font-bold tracking-widest font-serif ${activeView === item.id ? 'text-gold-main' : 'text-stone-400 group-hover:text-stone-300'}`}>
            {item.label}
          </span>
        </div>
      ))}
    </nav>
  );
};

export default BottomNav;

import React, { useRef, useEffect } from 'react';
import { Track } from '../types';

interface PlayerProps {
  track: Track;
  isPlaying: boolean;
  onTogglePlay: () => void;
  onNext: () => void;
  onPrev: () => void;
  currentTime: number;
  duration: number;
  volume: number;
  setVolume: (vol: number) => void;
  isLargeText: boolean;
}

const Player: React.FC<PlayerProps> = ({ 
  track, isPlaying, onTogglePlay, onNext, onPrev, 
  currentTime, duration, volume, setVolume, isLargeText
}) => {
  const lastVolumeRef = useRef(volume > 0 ? volume : 0.65);

  useEffect(() => {
    if (volume > 0) {
      lastVolumeRef.current = volume;
    }
  }, [volume]);

  const handleMuteToggle = () => {
    if (volume > 0) {
      setVolume(0);
    } else {
      setVolume(lastVolumeRef.current);
    }
  };

  const formatSeconds = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60);
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const progressPercent = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <main className="flex-1 flex flex-col justify-between px-8 pt-12 pb-28 relative z-10">
      <div className="flex-1 flex flex-col justify-center items-center py-4">
        <div className="relative w-full max-w-[340px] flex items-center justify-center">

          <button 
            onClick={onPrev}
            className="absolute -left-10 z-30 w-14 h-14 rounded-full flex items-center justify-center text-gold-main/70 hover:text-gold-light hover:bg-white/10 active:scale-90 transition-all focus:outline-none backdrop-blur-sm border border-white/10 shadow-lg group"
            aria-label="上一曲"
          >
            <span className="material-symbols-outlined text-[40px] transition-transform group-hover:-translate-x-1">chevron_left</span>
          </button>

          <div className="relative w-64 h-64 sm:w-80 sm:h-80">
            {/* 佛光背景动效 */}
            <div className={`absolute inset-0 rounded-full bg-gold-main/30 blur-[60px] transition-all duration-1000 ${isPlaying ? 'scale-125 opacity-40 animate-aura-breath' : 'scale-95 opacity-0'}`}></div>

            <div className="relative w-full h-full rounded-full gold-ring shadow-[0_0_60px_rgba(0,0,0,0.8)]">
              <div className="w-full h-full rounded-full overflow-hidden bg-[#0c0805] relative flex items-center justify-center border-[4px] border-[#0D0805]">
                <img 
                  alt={track.title}
                  className={`w-full h-full object-cover relative z-10 transition-transform duration-[10000ms] ease-in-out ${isPlaying ? 'scale-110 rotate-2' : 'scale-100 rotate-0'}`} 
                  src={track.imageUrl} 
                />
                <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-transparent via-white/10 to-transparent pointer-events-none z-20"></div>
              </div>
            </div>
          </div>

          <button 
            onClick={onNext}
            className="absolute -right-10 z-30 w-14 h-14 rounded-full flex items-center justify-center text-gold-main/70 hover:text-gold-light hover:bg-white/10 active:scale-90 transition-all focus:outline-none backdrop-blur-sm border border-white/10 shadow-lg group"
            aria-label="下一曲"
          >
            <span className="material-symbols-outlined text-[40px] transition-transform group-hover:translate-x-1">chevron_right</span>
          </button>
        </div>

        <div className="mt-12 text-center space-y-3">
          <h2 className={`text-gold-glow font-bold tracking-[0.25em] font-serif transition-all duration-500 ${isLargeText ? 'text-4xl' : 'text-2xl'}`}>
            {track.title}
          </h2>
          <p className={`text-stone-400 font-light tracking-[0.2em] font-serif italic opacity-90 transition-all ${isLargeText ? 'text-lg' : 'text-sm'}`}>
            {track.subtitle}
          </p>
        </div>
      </div>

      <div className="w-full max-w-[320px] mx-auto space-y-12">
        <div className="space-y-4">
          <div className="relative h-1.5 w-full bg-stone-900 rounded-full overflow-visible">
            <div 
              className="absolute top-0 left-0 h-full bg-gold-metal shadow-[0_0_15px_rgba(229,185,75,0.8)] transition-all duration-300 rounded-full" 
              style={{ width: `${progressPercent}%` }}
            />
            <div 
              className="absolute top-1/2 -translate-y-1/2 w-3.5 h-3.5 bg-white rounded-full shadow-[0_0_15px_white] transition-all duration-300"
              style={{ left: `${progressPercent}%`, transform: `translate(-50%, -50%)` }}
            ></div>
          </div>
          <div className="flex justify-between text-[11px] text-stone-400 font-display tracking-widest font-bold">
            <span>{formatSeconds(currentTime)}</span>
            <span>{formatSeconds(duration)}</span>
          </div>
        </div>

        <div className="flex flex-col items-center gap-10">
          <div className="relative">
            {isPlaying && (
              <div className="absolute inset-0 rounded-full border-2 border-gold-main/20 animate-[ping_3s_linear_infinite] scale-150 pointer-events-none"></div>
            )}
            <button 
              onClick={onTogglePlay}
              className="relative w-24 h-24 rounded-full bg-gold-metal flex items-center justify-center shadow-[0_15px_45px_rgba(0,0,0,0.9),inset_0_-4px_8px_rgba(0,0,0,0.5)] active:scale-95 transition-all border-4 border-[#2C1E12] z-10 group overflow-hidden"
            >
              <div className="absolute inset-0 bg-gradient-to-tr from-black/30 via-transparent to-white/20 opacity-50 group-hover:opacity-100 transition-opacity pointer-events-none"></div>
              <span className="material-symbols-outlined text-[#2C1E12] text-[68px] select-none transition-transform group-hover:scale-110">
                {isPlaying ? 'pause' : 'play_arrow'}
              </span>
            </button>
          </div>

          <div className="w-full flex items-center gap-4 px-5 py-4 bg-black/60 backdrop-blur-2xl rounded-2xl border border-white/10 shadow-inner group">
            <button 
              onClick={handleMuteToggle}
              className="flex items-center justify-center focus:outline-none transition-transform active:scale-90"
              title={volume === 0 ? "取消静音" : "静音"}
            >
              <span className={`material-symbols-outlined text-[20px] font-bold transition-colors ${volume === 0 ? 'text-red-500' : 'text-stone-400 hover:text-gold-main'}`}>
                {volume === 0 ? 'volume_off' : volume < 0.5 ? 'volume_down' : 'volume_up'}
              </span>
            </button>

            <div className="flex-1 relative flex items-center h-4">
              <div className="absolute w-full h-1 bg-stone-800 rounded-full pointer-events-none"></div>
              <div 
                className="absolute h-1 bg-gold-main rounded-full pointer-events-none transition-all duration-75"
                style={{ width: `${volume * 100}%` }}
              ></div>
              <input 
                type="range"
                min="0"
                max="1"
                step="0.01"
                value={volume}
                onChange={(e) => setVolume(parseFloat(e.target.value))}
                className="absolute w-full h-6 opacity-0 cursor-pointer z-10"
              />
              <div 
                className="absolute w-4 h-4 bg-gold-light rounded-full border-2 border-gold-dark shadow-[0_0_10px_rgba(0,0,0,0.5)] transition-all duration-75 pointer-events-none"
                style={{ left: `calc(${volume * 100}% - 8px)` }}
              ></div>
            </div>
            <span className="text-[10px] text-stone-300 font-display w-6 text-right font-bold">{Math.round(volume * 100)}</span>
          </div>
        </div>
      </div>
    </main>
  );
};

export default Player;

import React, { useState, useEffect, useRef } from 'react';
import { Track } from '../types';
import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
  isLargeText?: boolean;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';
const AUDIO_CACHE_NAME = 'zen-chant-audio';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId, isLargeText }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');

  // 离线同步状态
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'completed'>('idle');
  const [syncProgress, setSyncProgress] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }

    // 检查缓存状态
    checkCacheStatus();
  }, []);

  const checkCacheStatus = async () => {
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      const keys = await cache.keys();
      // 如果已缓存数量等于官方曲目数量，标记为已完成
      if (keys.length >= TRACKS.length) {
        setSyncStatus('completed');
      }
    } catch (e) {
      console.error("Cache check failed", e);
    }
  };

  const handleOfflineSync = async () => {
    if (syncStatus === 'syncing') return;

    setSyncStatus('syncing');
    setSyncProgress(0);

    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      let count = 0;

      for (const track of TRACKS) {
        try {
          // 检查是否已缓存
          const match = await cache.match(track.audioUrl);
          if (!match) {
            await cache.add(track.audioUrl);
          }
        } catch (err) {
          console.warn(`Failed to sync track: ${track.title}`, err);
        }
        count++;
        setSyncProgress(Math.round((count / TRACKS.length) * 100));
      }

      setSyncStatus('completed');
    } catch (e) {
      console.error("Sync failed", e);
      setSyncStatus('idle');
      alert("同步失败，请检查网络连接后重试。");
    }
  };

  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
    localStorage.setItem(CUSTOM_TRACKS_KEY, JSON.stringify(tracks));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewTrackUrl(url);
      if (!newTrackTitle) {
        setNewTrackTitle(file.name.replace(/\.[^/.]+$/, ""));
      }
    }
  };

  const handleAddTrack = () => {
    if (!newTrackTitle || !newTrackUrl) return;

    const newTrack: Track = {
      id: `custom_${Date.now()}`,
      code: `Z${(customTracks.length + 1).toString().padStart(2, '0')}`,
      title: newTrackTitle,
      subtitle: addMethod === 'file' ? '本地上传' : '网络链接',
      section: 'CUSTOM',
      imageUrl: 'https://www.shouyueliang.org/wp-content/uploads/2021/04/1623587633-v500-4-1.gif',
      audioUrl: newTrackUrl
    };

    saveCustomTracks([...customTracks, newTrack]);
    setShowAddModal(false);
    setNewTrackTitle('');
    setNewTrackUrl('');
  };

  const removeTrack = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = customTracks.filter(t => t.id !== id);
    saveCustomTracks(updated);
  };

  return (
    <div className="flex flex-col h-full bg-dark-gradient overflow-hidden pt-10">
      {/* 顶部标签切换 */}
      <div className="flex-none bg-transparent px-6 mb-2">
        <div className="flex gap-4">
          <button 
            onClick={() => setActiveTab('official')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'official' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
          >
            <p className={`font-bold tracking-[0.1em] font-serif transition-all ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>官方曲目</p>
          </button>
          <button 
            onClick={() => setActiveTab('custom')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'custom' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
          >
            <p className={`font-bold tracking-[0.1em] font-serif transition-all ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>自定义</p>
          </button>
        </div>
      </div>

      {/* 离线同步状态条 (仅在官方曲目页显示) */}
      {activeTab === 'official' && (
        <div className="px-6 py-3">
          <div className="bg-black/60 border border-white/10 rounded-2xl p-3 flex items-center justify-between shadow-inner">
            <div className="flex items-center gap-3">
              <span className={`material-symbols-outlined text-xl ${syncStatus === 'completed' ? 'text-green-400' : 'text-gold-main'}`}>
                {syncStatus === 'syncing' ? 'sync' : syncStatus === 'completed' ? 'cloud_done' : 'cloud_download'}
              </span>
              <div>
                <p className={`text-stone-300 font-bold font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[11px]'}`}>
                  {syncStatus === 'syncing' ? `正在离线同步 (${syncProgress}%)` : syncStatus === 'completed' ? '已离线 (无网亦可播放)' : '未离线 (建议同步以支持离线)'}
                </p>
                {syncStatus === 'syncing' && (
                  <div className="w-32 h-1 bg-stone-900 rounded-full mt-1 overflow-hidden">
                    <div className="h-full bg-gold-main transition-all duration-300 shadow-[0_0_8px_rgba(229,185,75,0.6)]" style={{ width: `${syncProgress}%` }}></div>
                  </div>
                )}
              </div>
            </div>
            {syncStatus !== 'completed' && (
              <button 
                onClick={handleOfflineSync}
                disabled={syncStatus === 'syncing'}
                className={`px-3 py-1 bg-gold-main/20 border border-gold-main/40 rounded-lg text-gold-main font-bold tracking-widest uppercase hover:bg-gold-main/30 disabled:opacity-50 transition-all ${isLargeText ? 'text-xs' : 'text-[10px]'}`}
              >
                {syncStatus === 'syncing' ? '同步中' : '开始同步'}
              </button>
            )}
          </div>
        </div>
      )}

      {/* 滚动列表 */}
      <div className="flex-1 overflow-y-auto pb-32 scroll-smooth">
        {activeTab === 'official' ? (
          SECTIONS.map((section) => (
            <div key={section.id} className="mb-2">
              <div className="sticky top-0 z-30 bg-[#0d0805]/98 backdrop-blur-xl px-5 py-3 border-b border-gold-main/10 shadow-lg">
                <div className="flex items-center gap-3">
                  <span className="bg-gold-main/20 border border-gold-main/40 text-gold-main text-[10px] font-bold px-2 py-0.5 rounded tracking-widest font-display">
                    {section.code}
                  </span>
                  <h3 className={`text-gold-light font-bold font-serif tracking-wider transition-all ${isLargeText ? 'text-xl' : 'text-base'}`}>{section.name}</h3>
                </div>
              </div>

              <div className="flex flex-col divide-y divide-white/5 px-2">
                {TRACKS.filter(t => t.section === section.code).map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.05] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.1]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className={`badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#2C1E12] text-sm font-display shadow-xl border border-[#7c6428]/50 transition-transform ${currentTrackId === track.id ? 'scale-110 rotate-3' : ''}`}>
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        <p className={`font-bold font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-light' : 'text-stone-200 group-hover:text-gold-main'} ${isLargeText ? 'text-xl' : 'text-[17px]'}`}>
                          {track.title}
                        </p>
                        <p className={`text-stone-400 tracking-wider font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'}`}>{track.subtitle}</p>
                      </div>
                    </div>
                    <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-stone-500 group-hover:text-gold-main'}`}>
                      {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          ))
        ) : (
          <div className="px-2 py-4 space-y-4">
            <button 
              onClick={() => setShowAddModal(true)}
              className="w-full flex items-center justify-center gap-3 py-4 rounded-xl border-2 border-dashed border-gold-main/40 text-gold-main hover:bg-gold-main/10 transition-colors group shadow-lg shadow-black/40"
            >
              <span className="material-symbols-outlined text-2xl group-hover:scale-110 transition-transform">add_circle</span>
              <span className={`font-bold tracking-widest font-serif transition-all ${isLargeText ? 'text-xl' : 'text-base'}`}>添加自定义曲目</span>
            </button>

            <div className="flex flex-col divide-y divide-white/5">
              {customTracks.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 opacity-40 text-gold-light">
                  <span className="material-symbols-outlined text-6xl mb-4">music_off</span>
                  <p className={`tracking-widest font-serif transition-all ${isLargeText ? 'text-lg' : 'text-sm'}`}>暂无自定义曲目</p>
                </div>
              ) : (
                customTracks.map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.05] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.1]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className="badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#2C1E12] text-sm font-display shadow-lg border border-[#7c6428]/50">
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        <p className={`font-bold font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-light' : 'text-stone-200 group-hover:text-gold-main'} ${isLargeText ? 'text-xl' : 'text-[17px]'}`}>
                          {track.title}
                        </p>
                        <p className={`text-stone-400 tracking-wider font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'}`}>{track.subtitle}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={(e) => removeTrack(e, track.id)}
                        className="text-red-500/50 hover:text-red-400 p-2 transition-colors"
                      >
                        <span className="material-symbols-outlined text-xl">delete</span>
                      </button>
                      <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-stone-500 group-hover:text-gold-main'}`}>
                        {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                      </span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 backdrop-blur-xl bg-black/70">
          <div className="w-full max-w-sm bg-surface-dark border border-gold-main/30 rounded-[2.5rem] p-8 shadow-2xl">
            <h3 className={`text-gold-light font-bold font-serif mb-6 text-center tracking-widest transition-all ${isLargeText ? 'text-2xl' : 'text-xl'}`}>添加修行曲目</h3>
            <div className="space-y-6">
              <div className="space-y-2">
                <label className={`text-stone-400 font-bold uppercase tracking-widest font-serif ml-1 transition-all ${isLargeText ? 'text-xs' : 'text-[10px]'}`}>曲目名称</label>
                <input 
                  type="text" 
                  value={newTrackTitle}
                  onChange={(e) => setNewTrackTitle(e.target.value)}
                  placeholder="请输入曲目名称"
                  className="w-full bg-black/40 border border-gold-main/30 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none placeholder:text-stone-600"
                />
              </div>
              <div className="space-y-3">
                <div className="flex gap-2">
                  <button onClick={() => setAddMethod('url')} className={`flex-1 py-2 rounded-lg font-bold font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'} ${addMethod === 'url' ? 'bg-gold-main/30 text-gold-main border border-gold-main/50' : 'bg-black/40 text-stone-500 border border-white/5'}`}>网络链接</button>
                  <button onClick={() => setAddMethod('file')} className={`flex-1 py-2 rounded-lg font-bold font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'} ${addMethod === 'file' ? 'bg-gold-main/30 text-gold-main border border-gold-main/50' : 'bg-black/40 text-stone-500 border border-white/5'}`}>本地文件</button>
                </div>
                {addMethod === 'url' ? (
                  <input 
                    type="text" 
                    value={newTrackUrl}
                    onChange={(e) => setNewTrackUrl(e.target.value)}
                    placeholder="https://example.com/audio.mp3"
                    className="w-full bg-black/40 border border-gold-main/30 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none placeholder:text-stone-600"
                  />
                ) : (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full bg-black/40 border border-dashed border-gold-main/30 rounded-xl px-4 py-6 text-center cursor-pointer hover:bg-white/5 transition-colors">
                    <span className={`text-gold-main font-bold font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'}`}>{newTrackUrl ? '已选择音频' : '点击上传本地音频'}</span>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="audio/*" className="hidden" />
                  </div>
                )}
              </div>
              <div className="flex gap-3 pt-4">
                <button onClick={() => setShowAddModal(false)} className={`flex-1 py-3 rounded-xl border border-white/10 text-stone-300 font-bold font-serif transition-all hover:bg-white/5 ${isLargeText ? 'text-base' : 'text-sm'}`}>取消</button>
                <button onClick={handleAddTrack} disabled={!newTrackTitle || !newTrackUrl} className={`flex-1 py-3 rounded-xl bg-gold-metal text-[#2C1E12] font-bold font-serif transition-all shadow-lg active:scale-95 disabled:opacity-30 ${isLargeText ? 'text-base' : 'text-sm'}`}>确认添加</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

