const CACHE_NAME = 'zen-chant-v4'; // 升级版本
const AUDIO_CACHE = 'zen-chant-audio';

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME && cacheName !== AUDIO_CACHE) {
            return caches.delete(cacheName);
          }
        })
      );
    }).then(() => clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // 针对音频资源的特殊优化逻辑
  if (url.hostname.includes('jdcloud-oss.com') || url.pathname.endsWith('.mp3')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(AUDIO_CACHE);

        // 关键修复 1: 统一编码匹配
        // 浏览器请求的 URL 可能已经被编码，我们确保使用原始字符串匹配
        const cachedResponse = await cache.match(event.request.url, {
          ignoreSearch: true,
          ignoreVary: true
        });

        if (cachedResponse) {
          /**
           * 关键修复 2: 解决移动端 Range 请求死锁
           * 如果浏览器发起了 Range 请求（bytes=0-），
           * 但我们缓存的是 no-cors 的不透明响应（status 0/200）。
           * 我们直接返回缓存，浏览器在发现返回的是完整 200 响应后，
           * 通常会放弃 Range 校验并正常播放。
           */
          return cachedResponse;
        }

        /**
         * 关键修复 3: 如果没命中缓存，发起网络请求
         * 对于音频，我们创建一个干净的请求，移除可能导致 OSS 拒绝的头部
         */
        try {
          const netRequest = new Request(event.request.url, {
            method: 'GET',
            headers: new Headers(), // 剥离 Range, Origin 等敏感头
            mode: 'no-cors',
            credentials: 'omit'
          });
          return await fetch(netRequest);
        } catch (err) {
          // 如果彻底断网且没缓存，返回一个空的合成响应
          return new Response(null, { status: 404 });
        }
      })()
    );
    return;
  }

  // UI 静态资源处理
  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      if (cachedResponse) return cachedResponse;
      return fetch(event.request).then((networkResponse) => {
        if (event.request.method === 'GET' && networkResponse.status === 200) {
          const responseToCache = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, responseToCache);
          });
        }
        return networkResponse;
      });
    })
  );
});

