const CACHE_NAME = 'zen-chant-v5'; // 升级版本
const AUDIO_CACHE = 'zen-chant-audio';

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME && cacheName !== AUDIO_CACHE) {
            return caches.delete(cacheName);
          }
        })
      );
    }).then(() => clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // 针对音频资源的拦截逻辑
  if (url.hostname.includes('jdcloud-oss.com') || url.pathname.endsWith('.mp3')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(AUDIO_CACHE);

        // 尝试从缓存匹配（忽略 Range 头进行查找）
        const cachedResponse = await cache.match(event.request.url, {
          ignoreSearch: true,
          ignoreVary: true
        });

        if (cachedResponse) {
          // 如果浏览器发起了 Range 请求
          if (event.request.headers.has('Range')) {
            // 在有 CORS 的情况下，我们直接返回 200 响应。
            // 现代浏览器在获取到完整的 200 缓存响应后，能够自行处理内部的分段读取。
            return cachedResponse;
          }
          return cachedResponse;
        }

        // 没命中缓存，发起带 CORS 的网络请求
        try {
          const response = await fetch(event.request);
          // 如果是在线播放时触发的下载，顺便存入缓存
          if (response.status === 200) {
            const responseToCache = response.clone();
            cache.put(event.request.url, responseToCache);
          }
          return response;
        } catch (err) {
          return new Response(null, { status: 404 });
        }
      })()
    );
    return;
  }

  // UI 静态资源处理
  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      if (cachedResponse) return cachedResponse;
      return fetch(event.request).then((networkResponse) => {
        if (event.request.method === 'GET' && networkResponse.status === 200) {
          const responseToCache = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, responseToCache);
          });
        }
        return networkResponse;
      });
    })
  );
});

import React, { useState, useEffect, useRef } from 'react';
import { Track } from '../types';
import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
  isLargeText?: boolean;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';
const AUDIO_CACHE_NAME = 'zen-chant-audio';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId, isLargeText }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');

  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'completed' | 'partial'>('idle');
  const [syncProgress, setSyncProgress] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }
    checkCacheStatus();
  }, []);

  const checkCacheStatus = async () => {
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      const keys = await cache.keys();
      const cachedUrlStrings = new Set(keys.map(request => request.url));

      const officialUrls = TRACKS.map(t => new URL(t.audioUrl, window.location.origin).href);
      const cachedOfficialCount = officialUrls.filter(url => cachedUrlStrings.has(url)).length;

      if (cachedOfficialCount === TRACKS.length) {
        setSyncStatus('completed');
        setSyncProgress(100);
      } else if (cachedOfficialCount > 0) {
        setSyncStatus('partial');
        setSyncProgress(Math.round((cachedOfficialCount / TRACKS.length) * 100));
      } else {
        setSyncStatus('idle');
        setSyncProgress(0);
      }
    } catch (e) {
      console.error("Cache check failed", e);
    }
  };

  const handleOfflineSync = async () => {
    if (syncStatus === 'syncing') return;

    setSyncStatus('syncing');

    let errorCount = 0;
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);

      if (syncStatus === 'idle') {
        const keys = await cache.keys();
        for (const key of keys) await cache.delete(key);
      }

      let processedCount = 0;
      for (const track of TRACKS) {
        try {
          const normUrl = new URL(track.audioUrl, window.location.origin).href;
          const match = await cache.match(normUrl);

          if (!match) {
            // 重要：改为使用 cors 模式。这要求 OSS 必须配置好 CORS 规则
            const response = await fetch(track.audioUrl, {
              mode: 'cors',
              credentials: 'omit',
              cache: 'reload'
            });

            if (!response.ok && response.type !== 'opaque') {
              throw new Error(`下载失败: ${response.status}`);
            }

            await cache.put(normUrl, response);
          }
        } catch (err) {
          console.error(`曲目同步失败: ${track.title}`, err);
          errorCount++;
        }

        processedCount++;
        setSyncProgress(Math.round((processedCount / TRACKS.length) * 100));
        await new Promise(resolve => setTimeout(resolve, 50));
      }

      await checkCacheStatus();

      if (errorCount > 0) {
        alert(`提示：有 ${errorCount} 首曲目同步失败。这通常是由于 OSS 的 CORS 规则未生效或网络波动引起。请检查控制台设置后重试。`);
      }
    } catch (e) {
      console.error("同步异常:", e);
      setSyncStatus('partial');
    }
  };

  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
    localStorage.setItem(CUSTOM_TRACKS_KEY, JSON.stringify(tracks));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewTrackUrl(url);
      if (!newTrackTitle) {
        setNewTrackTitle(file.name.replace(/\.[^/.]+$/, ""));
      }
    }
  };

  const handleAddTrack = () => {
    if (!newTrackTitle || !newTrackUrl) return;

    const newTrack: Track = {
      id: `custom_${Date.now()}`,
      code: `Z${(customTracks.length + 1).toString().padStart(2, '0')}`,
      title: newTrackTitle,
      subtitle: addMethod === 'file' ? '本地上传' : '网络链接',
      section: 'CUSTOM',
      imageUrl: 'https://www.shouyueliang.org/wp-content/uploads/2021/04/1623587633-v500-4-1.gif',
      audioUrl: newTrackUrl
    };

    saveCustomTracks([...customTracks, newTrack]);
    setShowAddModal(false);
    setNewTrackTitle('');
    setNewTrackUrl('');
  };

  const removeTrack = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = customTracks.filter(t => t.id !== id);
