import React, { useState, useEffect, useRef } from 'react';
import { View, Track } from './types';
import { TRACKS } from './constants';
import BottomNav from './components/BottomNav';
import Player from './components/Player';
import Playlist from './components/Playlist';
import Settings from './components/Settings';
import Profile from './components/Profile';
import MeritAnimation from './components/MeritAnimation';
import ShareCard from './components/ShareCard';
import { getZenQuote, ZenQuote } from './services/zenQuoteService';

const STATS_KEY = 'zen_chant_user_stats';
const CONFIG_KEY = 'zen_chant_config';

const App: React.FC = () => {
  const [view, setView] = useState<View>(View.PLAYER);
  const [currentTrack, setCurrentTrack] = useState<Track>(TRACKS[0]);
  const [isPlaying, setIsPlaying] = useState(true); 
  const [zenQuote, setZenQuote] = useState<ZenQuote>(getZenQuote());
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.65);
  const [isSingleLoop, setIsSingleLoop] = useState(true); 

  // 功德目标与进度
  const [taskTarget, setTaskTarget] = useState(0);
  const [taskProgress, setTaskProgress] = useState(0);
  const [showMerit, setShowMerit] = useState(false);
  const [showShare, setShowShare] = useState(false);

  // 配置项
  const [isLargeText, setIsLargeText] = useState(() => {
    const saved = localStorage.getItem(CONFIG_KEY);
    return saved ? JSON.parse(saved).isLargeText : false;
  });

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    localStorage.setItem(CONFIG_KEY, JSON.stringify({ isLargeText }));
  }, [isLargeText]);

  // 初始化统计数据
  const [stats, setStats] = useState(() => {
    const saved = localStorage.getItem(STATS_KEY);
    if (saved) return JSON.parse(saved);
    return {
      installDate: new Date().toISOString(),
      totalCompletions: 0,
      dailyLogs: {} 
    };
  });

  useEffect(() => {
    localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  }, [stats]);

  const recordCompletion = (trackId: string) => {
    const today = new Date().toISOString().split('T')[0];
    setStats(prev => {
      const newDailyLogs = { ...prev.dailyLogs };
      if (!newDailyLogs[today]) newDailyLogs[today] = {};
      newDailyLogs[today][trackId] = (newDailyLogs[today][trackId] || 0) + 1;

      return {
        ...prev,
        totalCompletions: prev.totalCompletions + 1,
        dailyLogs: newDailyLogs
      };
    });
  };

  const isTaskActive = taskTarget > 0;

  useEffect(() => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.play().catch(() => setIsPlaying(false));
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume, currentTrack, view]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.load();
      if (isPlaying) {
        audioRef.current.play().catch(() => {});
      }
    }
    setTaskProgress(isTaskActive ? 1 : 0);
  }, [currentTrack.id]);

  const handleTrackSelect = (track: Track) => {
    setCurrentTrack(track);
    setIsPlaying(true);
    setView(View.PLAYER);
    setTaskTarget(0);
    setTaskProgress(0);
  };

  const handleNext = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const nextTrack = TRACKS[(idx + 1) % TRACKS.length];
      setCurrentTrack(nextTrack);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const idx = TRACKS.findIndex(t => t.id === currentTrack.id);
    if (idx !== -1) {
      const prevTrack = TRACKS[(idx - 1 + TRACKS.length) % TRACKS.length];
      setCurrentTrack(prevTrack);
      setIsPlaying(true);
    }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration || 0);
    }
  };

  const handleEnded = () => {
    recordCompletion(currentTrack.id);
    if (taskTarget > 0) {
      if (taskProgress < taskTarget) {
        setTaskProgress(prev => prev + 1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
          audioRef.current.play();
        }
      } else {
        setIsPlaying(false);
        setTaskTarget(0);
        setTaskProgress(0);
        setShowMerit(true); // 触发功德圆满动画
      }
    } else if (!isSingleLoop) {
      handleNext();
    }
  };

  const updateTaskTarget = (target: number) => {
    if (taskProgress === 0) {
        setTaskProgress(1);
        if (audioRef.current) {
          audioRef.current.currentTime = 0;
        }
    }
    setTaskTarget(target);
    setIsSingleLoop(false);
    setIsPlaying(true);
    if (audioRef.current && audioRef.current.paused) {
      audioRef.current.play();
    }
  };

  const stopTask = () => {
    setTaskTarget(0);
    setTaskProgress(0);
    setIsPlaying(false);
  };

  const handleRefreshQuote = () => {
    setZenQuote(getZenQuote());
  };

  const renderContent = () => {
    switch (view) {
      case View.PLAYER:
        return (
          <Player 
            track={currentTrack} 
            isPlaying={isPlaying} 
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            currentTime={currentTime}
            duration={duration}
            volume={volume}
            setVolume={setVolume}
            isLargeText={isLargeText}
          />
        );
      case View.PLAYLIST:
        return (
          <Playlist 
            currentTrackId={currentTrack.id} 
            onTrackSelect={handleTrackSelect}
            isLargeText={isLargeText}
          />
        );
      case View.TIMER:
        return (
          <Settings 
            currentTrack={currentTrack} 
            isPlaying={isPlaying}
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onNext={handleNext}
            onPrev={handlePrev}
            onUpdateTarget={updateTaskTarget}
            onStopTask={stopTask}
            taskProgress={taskProgress}
            taskTarget={taskTarget}
            currentTime={currentTime}
            duration={duration}
            isLargeText={isLargeText}
          />
        );
      case View.PROFILE:
        return (
          <Profile 
            stats={stats} 
            zenQuote={zenQuote} 
            onRefreshQuote={handleRefreshQuote}
            isLargeText={isLargeText}
            onToggleLargeText={() => setIsLargeText(!isLargeText)}
            onOpenShare={() => setShowShare(true)}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex flex-col w-full max-w-md mx-auto min-h-screen relative shadow-2xl bg-zen-dark overflow-hidden">
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute inset-0 bg-wood-grain mix-blend-overlay opacity-20"></div>
        <div className="absolute top-1/4 -left-1/4 w-[150%] h-1/2 bg-gradient-to-r from-transparent via-white/5 to-transparent blur-[100px] animate-smoke-flow rotate-12"></div>
        <div className="absolute bottom-1/4 -right-1/4 w-[150%] h-1/2 bg-gradient-to-l from-transparent via-gold-main/5 to-transparent blur-[80px] animate-smoke-flow -rotate-6 animation-delay-5000"></div>
      </div>

      <audio 
        ref={audioRef}
        src={currentTrack.audioUrl}
        onTimeUpdate={handleTimeUpdate}
        onEnded={handleEnded}
        crossOrigin="anonymous"
        loop={isSingleLoop && taskTarget === 0} 
      />

      {renderContent()}

      <BottomNav activeView={view} onViewChange={setView} />

      {showMerit && <MeritAnimation onComplete={() => setShowMerit(false)} />}
      {showShare && <ShareCard quote={zenQuote} onClose={() => setShowShare(false)} />}
    </div>
  );
};

export default App;

const CACHE_NAME = 'zen-chant-v6'; 
const AUDIO_CACHE = 'zen-chant-audio';

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          // 强制清理所有旧缓存，确保 CORS 生效后的新数据纯净
          if (cacheName !== CACHE_NAME && cacheName !== AUDIO_CACHE) {
            return caches.delete(cacheName);
          }
        })
      );
    }).then(() => clients.claim())
  );
});

// 处理 Range 请求的辅助函数
async function handleRangeRequest(request, cachedResponse) {
  const rangeHeader = request.headers.get('Range');
  if (!rangeHeader) return cachedResponse;

  const arrayBuffer = await cachedResponse.arrayBuffer();
  const ranges = rangeHeader.match(/bytes=(\d+)-(\d+)?/);
  const start = parseInt(ranges[1], 10);
  const end = ranges[2] ? parseInt(ranges[2], 10) : arrayBuffer.byteLength - 1;

  const chunk = arrayBuffer.slice(start, end + 1);
  return new Response(chunk, {
    status: 206,
    statusText: 'Partial Content',
    headers: new Headers(cachedResponse.headers)
  });
}

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // 针对音频资源的拦截
  if (url.hostname.includes('jdcloud-oss.com') || url.pathname.endsWith('.mp3')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(AUDIO_CACHE);
        const cachedResponse = await cache.match(event.request.url, {
          ignoreSearch: true,
          ignoreVary: true
        });

        if (cachedResponse) {
          // 关键点：如果浏览器请求分段，我们利用 CORS 拿到的完整数据模拟分段返回
          try {
            return await handleRangeRequest(event.request, cachedResponse);
          } catch (e) {
            return cachedResponse;
          }
        }

        // 没命中缓存，发起请求
        try {
          // 既然已经开了 CORS，这里直接 fetch 即可，浏览器会自动处理
          const response = await fetch(event.request);

          // 仅在完全下载成功（200）时存入缓存，206 请求不在此处全量缓存
          if (response.status === 200) {
            const responseToCache = response.clone();
            cache.put(event.request.url, responseToCache);
          }
          return response;
        } catch (err) {
          return new Response(null, { status: 404 });
        }
      })()
    );
    return;
  }

  // 默认 UI 静态资源缓存策略
  event.respondWith(
    caches.match(event.request).then((res) => {
      return res || fetch(event.request).then((networkRes) => {
        if (event.request.method === 'GET' && networkRes.status === 200) {
          const cacheCopy = networkRes.clone();
          caches.open(CACHE_NAME).then(c => c.put(event.request, cacheCopy));
        }
        return networkRes;
      });
    })
  );
});

import React, { useState, useEffect, useRef } from 'react';
import { Track } from '../types';
import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
  isLargeText?: boolean;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';
const AUDIO_CACHE_NAME = 'zen-chant-audio';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId, isLargeText }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');

  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'completed' | 'partial'>('idle');
  const [syncProgress, setSyncProgress] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }
    checkCacheStatus();
  }, []);

  const checkCacheStatus = async () => {
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      const keys = await cache.keys();
      const cachedUrlStrings = new Set(keys.map(request => request.url));

      const officialUrls = TRACKS.map(t => new URL(t.audioUrl, window.location.origin).href);
      const cachedOfficialCount = officialUrls.filter(url => cachedUrlStrings.has(url)).length;

      if (cachedOfficialCount === TRACKS.length) {
        setSyncStatus('completed');
        setSyncProgress(100);
      } else if (cachedOfficialCount > 0) {
        setSyncStatus('partial');
        setSyncProgress(Math.round((cachedOfficialCount / TRACKS.length) * 100));
      } else {
        setSyncStatus('idle');
        setSyncProgress(0);
      }
    } catch (e) {
      console.error("Cache check failed", e);
    }
  };

  const handleOfflineSync = async () => {
    if (syncStatus === 'syncing') return;

    setSyncStatus('syncing');

    let errorCount = 0;
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);

      // 重要：如果是从 idle 或 partial 开始，先清空旧的可能导致问题的缓存
      if (syncStatus !== 'partial') {
        const keys = await cache.keys();
        for (const key of keys) await cache.delete(key);
      }

      let processedCount = 0;
      for (const track of TRACKS) {
        try {
          const normUrl = new URL(track.audioUrl, window.location.origin).href;
          const match = await cache.match(normUrl);

          if (!match) {
            // 使用严格的 CORS 模式获取文件
            const response = await fetch(track.audioUrl, {
              mode: 'cors',
              credentials: 'omit',
              cache: 'reload'
            });

            if (!response.ok) {
              throw new Error(`HTTP ${response.status}`);
            }

            // 写入缓存。因为是 CORS 模式，响应不再是“不透明”的
            await cache.put(normUrl, response);
          }
        } catch (err) {
          console.error(`曲目同步失败: ${track.title}`, err);
          errorCount++;
        }

        processedCount++;
        setSyncProgress(Math.round((processedCount / TRACKS.length) * 100));
        // 给 I/O 留一点时间
        await new Promise(resolve => setTimeout(resolve, 30));
      }

      await checkCacheStatus();

      if (errorCount > 0) {
        alert(`同步完成，但有 ${errorCount} 首失败。请确认京东云 OSS 的 CORS 设置中 'Allowed Origin' 包含当前域名，且 'Exposed Headers' 包含 Content-Range。`);
      }
    } catch (e) {
      console.error("同步异常:", e);
      setSyncStatus('partial');
    }
  };

  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
    localStorage.setItem(CUSTOM_TRACKS_KEY, JSON.stringify(tracks));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewTrackUrl(url);
      if (!newTrackTitle) {
        setNewTrackTitle(file.name.replace(/\.[^/.]+$/, ""));
      }
    }
  };

  const handleAddTrack = () => {
    if (!newTrackTitle || !newTrackUrl) return;

    const newTrack: Track = {
      id: `custom_${Date.now()}`,
      code: `Z${(customTracks.length + 1).toString().padStart(2, '0')}`,
      title: newTrackTitle,
      subtitle: addMethod === 'file' ? '本地上传' : '网络链接',
      section: 'CUSTOM',
      imageUrl: 'https://www.shouyueliang.org/wp-content/uploads/2021/04/1623587633-v500-4-1.gif',
      audioUrl: newTrackUrl
    };

    saveCustomTracks([...customTracks, newTrack]);
    setShowAddModal(false);
    setNewTrackTitle('');
    setNewTrackUrl('');
  };

  const removeTrack = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = customTracks.filter(t => t.id !== id);
    saveCustomTracks(updated);
  };

  return (
    <div className="flex flex-col h-full bg-dark-gradient overflow-hidden pt-10">
      <div className="flex-none bg-transparent px-6 mb-2">
        <div className="flex gap-4">
          <button 
            onClick={() => setActiveTab('official')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'official' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
          >
            <p className={`font-bold tracking-[0.1em] font-serif transition-all ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>官方曲目</p>
          </button>
          <button 
            onClick={() => setActiveTab('custom')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'custom' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
          >
            <p className={`font-bold tracking-[0.1em] font-serif transition-all ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>自定义</p>
          </button>
        </div>
      </div>

      {activeTab === 'official' && (
        <div className="px-6 py-3">
          <div className="bg-black/60 border border-white/10 rounded-2xl p-4 flex items-center justify-between shadow-inner">
            <div className="flex items-center gap-4">
              <div className={`relative flex items-center justify-center w-10 h-10 rounded-full bg-black/40 border ${syncStatus === 'completed' ? 'border-green-500/50 text-green-400' : 'border-gold-main/30 text-gold-main'}`}>
                {syncStatus === 'syncing' ? (
                   <span className="material-symbols-outlined text-2xl animate-spin">sync</span>
                ) : syncStatus === 'completed' ? (
                   <span className="material-symbols-outlined text-2xl">cloud_done</span>
                ) : (
                   <span className="material-symbols-outlined text-2xl">cloud_download</span>
                )}
                {syncStatus === 'syncing' && (
                  <svg className="absolute inset-0 w-full h-full -rotate-90">
                    <circle cx="20" cy="20" r="18" fill="none" stroke="currentColor" strokeWidth="2" strokeDasharray="113.1" strokeDashoffset={113.1 - (113.1 * syncProgress) / 100} className="opacity-40" />
                  </svg>
                )}
              </div>
              <div>
                <p className={`font-bold font-serif transition-all ${isLargeText ? 'text-sm' : 'text-[12px]'} ${syncStatus === 'completed' ? 'text-green-400' : 'text-stone-200'}`}>
                  {syncStatus === 'syncing' ? `正在下载离线数据...` : syncStatus === 'completed' ? '已离线 (无网亦可播放)' : '未同步 (建议点击同步)'}
                </p>
                <p className="text-stone-500 text-[10px] mt-0.5">
                  {syncStatus === 'syncing' ? `进度：${syncProgress}%` : syncStatus === 'completed' ? '15首曲目已全部存入本地' : '同步后可在飞行模式下使用'}
                </p>
              </div>
            </div>
            {syncStatus !== 'completed' && (
              <button 
                onClick={handleOfflineSync}
                disabled={syncStatus === 'syncing'}
                className={`px-4 py-2 bg-gold-main/20 border border-gold-main/40 rounded-xl text-gold-main font-bold tracking-widest uppercase hover:bg-gold-main/30 active:scale-95 disabled:opacity-30 transition-all ${isLargeText ? 'text-xs' : 'text-[11px]'}`}
              >
                {syncStatus === 'syncing' ? '同步中' : syncStatus === 'partial' ? '继续同步' : '开始同步'}
              </button>
            )}
          </div>
        </div>
      )}

      <div className="flex-1 overflow-y-auto pb-32 scroll-smooth">
        {activeTab === 'official' ? (
          SECTIONS.map((section) => (
            <div key={section.id} className="mb-2">
              <div className="sticky top-0 z-30 bg-[#0d0805]/98 backdrop-blur-xl px-5 py-3 border-b border-gold-main/10 shadow-lg">
                <div className="flex items-center gap-3">
                  <span className="bg-gold-main/20 border border-gold-main/40 text-gold-main text-[10px] font-bold px-2 py-0.5 rounded tracking-widest font-display">
                    {section.code}
                  </span>
                  <h3 className={`text-gold-light font-bold font-serif tracking-wider transition-all ${isLargeText ? 'text-xl' : 'text-base'}`}>{section.name}</h3>
                </div>
              </div>

              <div className="flex flex-col divide-y divide-white/5 px-2">
                {TRACKS.filter(t => t.section === section.code).map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.05] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.1]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className={`badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#2C1E12] text-sm font-display shadow-xl border border-[#7c6428]/50 transition-transform ${currentTrackId === track.id ? 'scale-110 rotate-3' : ''}`}>
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        <p className={`font-bold font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-light' : 'text-stone-200 group-hover:text-gold-main'} ${isLargeText ? 'text-xl' : 'text-[17px]'}`}>
                          {track.title}
                        </p>
                        <p className={`text-stone-400 tracking-wider font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'}`}>{track.subtitle}</p>
                      </div>
                    </div>
                    <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-stone-500 group-hover:text-gold-main'}`}>
                      {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          ))
        ) : (
          <div className="px-2 py-4 space-y-4">
            <button 
              onClick={() => setShowAddModal(true)}
              className="w-full flex items-center justify-center gap-3 py-4 rounded-xl border-2 border-dashed border-gold-main/40 text-gold-main hover:bg-gold-main/10 transition-colors group shadow-lg shadow-black/40"
            >
              <span className="material-symbols-outlined text-2xl group-hover:scale-110 transition-transform">add_circle</span>
              <span className={`font-bold tracking-widest font-serif transition-all ${isLargeText ? 'text-xl' : 'text-base'}`}>添加自定义曲目</span>
            </button>

            <div className="flex flex-col divide-y divide-white/5">
              {customTracks.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 opacity-40 text-gold-light">
                  <span className="material-symbols-outlined text-6xl mb-4">music_off</span>
                  <p className={`tracking-widest font-serif transition-all ${isLargeText ? 'text-lg' : 'text-sm'}`}>暂无自定义曲目</p>
                </div>
              ) : (
                customTracks.map((track) => (
                  <div 
                    key={track.id}
                    onClick={() => onTrackSelect(track)}
                    className={`group flex items-center gap-4 px-3 py-4 justify-between hover:bg-white/[0.05] cursor-pointer rounded-lg transition-colors my-1 ${currentTrackId === track.id ? 'bg-white/[0.1]' : ''}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className="badge-texture flex items-center justify-center rounded-full shrink-0 size-11 font-bold text-[#2C1E12] text-sm font-display shadow-lg border border-[#7c6428]/50">
                        {track.code}
                      </div>
                      <div className="flex flex-col">
                        <p className={`font-bold font-serif tracking-wide transition-colors ${currentTrackId === track.id ? 'text-gold-light' : 'text-stone-200 group-hover:text-gold-main'} ${isLargeText ? 'text-xl' : 'text-[17px]'}`}>
                          {track.title}
                        </p>
                        <p className={`text-stone-400 tracking-wider font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'}`}>{track.subtitle}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={(e) => removeTrack(e, track.id)}
                        className="text-red-500/50 hover:text-red-400 p-2 transition-colors"
                      >
                        <span className="material-symbols-outlined text-xl">delete</span>
                      </button>
                      <span className={`material-symbols-outlined text-3xl transition-colors ${currentTrackId === track.id ? 'text-gold-main' : 'text-stone-500 group-hover:text-gold-main'}`}>
                        {currentTrackId === track.id ? 'pause_circle' : 'play_circle'}
                      </span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 backdrop-blur-xl bg-black/70">
          <div className="w-full max-w-sm bg-surface-dark border border-gold-main/30 rounded-[2.5rem] p-8 shadow-2xl">
            <h3 className={`text-gold-light font-bold font-serif mb-6 text-center tracking-widest transition-all ${isLargeText ? 'text-2xl' : 'text-xl'}`}>添加修行曲目</h3>
            <div className="space-y-6">
              <div className="space-y-2">
                <label className={`text-stone-400 font-bold uppercase tracking-widest font-serif ml-1 transition-all ${isLargeText ? 'text-xs' : 'text-[10px]'}`}>曲目名称</label>
                <input 
                  type="text" 
                  value={newTrackTitle}
                  onChange={(e) => setNewTrackTitle(e.target.value)}
                  placeholder="请输入曲目名称"
                  className="w-full bg-black/40 border border-gold-main/30 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none placeholder:text-stone-600"
                />
              </div>
              <div className="space-y-3">
                <div className="flex gap-2">
                  <button onClick={() => setAddMethod('url')} className={`flex-1 py-2 rounded-lg font-bold font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'} ${addMethod === 'url' ? 'bg-gold-main/30 text-gold-main border border-gold-main/50' : 'bg-black/40 text-stone-500 border border-white/5'}`}>网络链接</button>
                  <button onClick={() => setAddMethod('file')} className={`flex-1 py-2 rounded-lg font-bold font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'} ${addMethod === 'file' ? 'bg-gold-main/30 text-gold-main border border-gold-main/50' : 'bg-black/40 text-stone-500 border border-white/5'}`}>本地文件</button>
                </div>
                {addMethod === 'url' ? (
                  <input 
                    type="text" 
                    value={newTrackUrl}
                    onChange={(e) => setNewTrackUrl(e.target.value)}
                    placeholder="https://example.com/audio.mp3"
                    className="w-full bg-black/40 border border-gold-main/30 rounded-xl px-4 py-3 text-gold-light focus:border-gold-main outline-none placeholder:text-stone-600"
                  />
                ) : (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full bg-black/40 border border-dashed border-gold-main/30 rounded-xl px-4 py-6 text-center cursor-pointer hover:bg-white/5 transition-colors">
                    <span className={`text-gold-main font-bold font-serif transition-all ${isLargeText ? 'text-sm' : 'text-xs'}`}>{newTrackUrl ? '已选择音频' : '点击上传本地音频'}</span>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="audio/*" className="hidden" />
                  </div>
                )}
              </div>
              <div className="flex gap-3 pt-4">
                <button onClick={() => setShowAddModal(false)} className={`flex-1 py-3 rounded-xl border border-white/10 text-stone-300 font-bold font-serif transition-all hover:bg-white/5 ${isLargeText ? 'text-base' : 'text-sm'}`}>取消</button>
                <button onClick={handleAddTrack} disabled={!newTrackTitle || !newTrackUrl} className={`flex-1 py-3 rounded-xl bg-gold-metal text-[#2C1E12] font-bold font-serif transition-all shadow-lg active:scale-95 disabled:opacity-30 ${isLargeText ? 'text-base' : 'text-sm'}`}>确认添加</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Playlist;

const CACHE_NAME = 'zen-chant-v7'; // 再次升级版本以强制更新逻辑
const AUDIO_CACHE = 'zen-chant-audio';

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(
      keys.map((key) => {
        if (key !== CACHE_NAME && key !== AUDIO_CACHE) return caches.delete(key);
      })
    )).then(() => clients.claim())
  );
});

/**
 * 核心：模拟流媒体服务器的分段响应 (206 Partial Content)
 */
async function getRangeResponse(request, cachedResponse) {
  const rangeHeader = request.headers.get('Range');
  if (!rangeHeader) return cachedResponse;

  const arrayBuffer = await cachedResponse.arrayBuffer();
  const bytes = rangeHeader.match(/^bytes=(\d+)-(\d+)?$/);
  if (!bytes) return cachedResponse;

  const start = parseInt(bytes[1], 10);
  const total = arrayBuffer.byteLength;
  const end = bytes[2] ? parseInt(bytes[2], 10) : total - 1;

  const chunk = arrayBuffer.slice(start, end + 1);

  // 必须构造符合规范的 206 头部
  const responseHeaders = new Headers(cachedResponse.headers);
  responseHeaders.set('Content-Range', `bytes ${start}-${end}/${total}`);
  responseHeaders.set('Content-Length', chunk.byteLength.toString());
  responseHeaders.set('Accept-Ranges', 'bytes');

  return new Response(chunk, {
    status: 206,
    statusText: 'Partial Content',
    headers: responseHeaders
  });
}

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // 匹配音频资源
  if (url.hostname.includes('jdcloud-oss.com') || url.pathname.endsWith('.mp3')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(AUDIO_CACHE);
        // 使用 ignoreSearch 确保 URL 匹配精准
        const cachedResponse = await cache.match(event.request.url, { 
          ignoreSearch: true,
          ignoreVary: true 
        });

        if (cachedResponse) {
          // 如果命中了缓存，针对浏览器的 Range 请求进行模拟分段
          return getRangeResponse(event.request, cachedResponse);
        }

        // 没命中缓存，走网络请求
        try {
          const networkResponse = await fetch(event.request);
          // 只有完整的 200 响应才存入离线库
          if (networkResponse.status === 200) {
            const cacheCopy = networkResponse.clone();
            cache.put(event.request.url, cacheCopy);
          }
          return networkResponse;
        } catch (err) {
          // 断网且没缓存的情况
          return new Response('Offline and not cached', { status: 503 });
        }
      })()
    );
    return;
  }

  // 其他 UI 资源
  event.respondWith(
    caches.match(event.request).then((res) => {
      return res || fetch(event.request).then((netRes) => {
        if (event.request.method === 'GET' && netRes.status === 200) {
          const copy = netRes.clone();
          caches.open(CACHE_NAME).then(c => c.put(event.request, copy));
        }
        return netRes;
      });
    })
  );
});

import React, { useState, useEffect, useRef } from 'react';
import { Track } from '../types';
import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
  isLargeText?: boolean;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';
const AUDIO_CACHE_NAME = 'zen-chant-audio';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId, isLargeText }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');

  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'completed' | 'partial'>('idle');
  const [syncProgress, setSyncProgress] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }
    checkCacheStatus();
  }, []);

  const checkCacheStatus = async () => {
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      const keys = await cache.keys();
      const cachedUrlStrings = new Set(keys.map(request => request.url));

      const officialUrls = TRACKS.map(t => new URL(t.audioUrl, window.location.origin).href);
      const cachedOfficialCount = officialUrls.filter(url => cachedUrlStrings.has(url)).length;

      if (cachedOfficialCount === TRACKS.length) {
        setSyncStatus('completed');
        setSyncProgress(100);
      } else if (cachedOfficialCount > 0) {
        setSyncStatus('partial');
        setSyncProgress(Math.round((cachedOfficialCount / TRACKS.length) * 100));
      } else {
        setSyncStatus('idle');
        setSyncProgress(0);
      }
    } catch (e) {
      console.error("Cache check failed", e);
    }
  };

  const handleOfflineSync = async () => {
    if (syncStatus === 'syncing') return;

    setSyncStatus('syncing');

    let errorCount = 0;
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);

      // 开始同步前先检查网络
      if (!navigator.onLine) {
        alert('请连接网络后再进行同步。');
        setSyncStatus('idle');
        return;
      }

      let processedCount = 0;
      for (const track of TRACKS) {
        try {
          // 使用统一格式的 URL 作为缓存 Key
          const normUrl = new URL(track.audioUrl, window.location.origin).href;
          const match = await cache.match(normUrl);

          if (!match) {
            // mode: 'cors' 确保我们获取的是可以被 JS 读取 body 的响应
            const response = await fetch(track.audioUrl, {
              mode: 'cors',
              credentials: 'omit',
              cache: 'reload'
            });

            if (!response.ok) throw new Error(`HTTP ${response.status}`);

            // 存入缓存
            await cache.put(normUrl, response);
          }
        } catch (err) {
          console.error(`同步失败: ${track.title}`, err);
          errorCount++;
        }

        processedCount++;
        setSyncProgress(Math.round((processedCount / TRACKS.length) * 100));
        await new Promise(resolve => setTimeout(resolve, 20));
      }

      await checkCacheStatus();

      if (errorCount > 0) {
        alert(`同步结束，但有 ${errorCount} 首曲目下载失败。请确认京东云 OSS 的 CORS 规则中包含当前站点的 Origin。`);
      } else {
        alert('全部曲目已同步至本地，现在可以在无网络环境下使用了。');
      }
    } catch (e) {
      console.error("同步异常:", e);
      setSyncStatus('partial');
    }
  };

  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
