const CACHE_NAME = 'zen-chant-v8'; 
const AUDIO_CACHE = 'zen-chant-audio';

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(
      keys.map((key) => {
        if (key !== CACHE_NAME && key !== AUDIO_CACHE) return caches.delete(key);
      })
    )).then(() => clients.claim())
  );
});

/**
 * 核心：模拟流媒体服务器的分段响应 (206 Partial Content)
 */
async function getRangeResponse(request, cachedResponse) {
  // 如果缓存响应是非法的（不透明响应），无法读取其 arrayBuffer
  if (!cachedResponse || cachedResponse.status === 0) {
    return cachedResponse;
  }

  const rangeHeader = request.headers.get('Range');
  if (!rangeHeader) return cachedResponse;

  try {
    const arrayBuffer = await cachedResponse.arrayBuffer();
    const bytes = rangeHeader.match(/^bytes=(\d+)-(\d+)?$/);
    if (!bytes) return cachedResponse;

    const start = parseInt(bytes[1], 10);
    const total = arrayBuffer.byteLength;
    const end = bytes[2] ? parseInt(bytes[2], 10) : total - 1;

    const chunk = arrayBuffer.slice(start, end + 1);

    // 构造 206 头部
    const responseHeaders = new Headers(cachedResponse.headers);
    responseHeaders.set('Content-Range', `bytes ${start}-${end}/${total}`);
    responseHeaders.set('Content-Length', chunk.byteLength.toString());
    responseHeaders.set('Accept-Ranges', 'bytes');

    // 确保 Content-Type 存在，这对移动端播放至关重要
    if (!responseHeaders.has('Content-Type')) {
      responseHeaders.set('Content-Type', 'audio/mpeg');
    }

    return new Response(chunk, {
      status: 206,
      statusText: 'Partial Content',
      headers: responseHeaders
    });
  } catch (err) {
    console.error('Range processing failed:', err);
    // 发生错误时尝试返回原始 200 响应作为保底
    return cachedResponse;
  }
}

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // 针对京东云 OSS 音频或 .mp3 后缀的拦截
  if (url.hostname.includes('jdcloud-oss.com') || url.pathname.endsWith('.mp3')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(AUDIO_CACHE);
        // ignoreSearch 对处理带参数的 OSS URL 很重要
        const cachedResponse = await cache.match(event.request.url, { 
          ignoreSearch: true,
          ignoreVary: true 
        });

        if (cachedResponse) {
          // 如果命中了缓存，进行分段处理
          return getRangeResponse(event.request, cachedResponse);
        }

        // 没命中缓存，走网络
        try {
          const networkResponse = await fetch(event.request);
          // 仅缓存状态正常的响应
          if (networkResponse.status === 200) {
            const cacheCopy = networkResponse.clone();
            cache.put(event.request.url, cacheCopy);
          }
          return networkResponse;
        } catch (err) {
          return new Response(null, { status: 503 });
        }
      })()
    );
    return;
  }

  // UI 静态资源缓存策略 (Stale-While-Revalidate)
  event.respondWith(
    caches.match(event.request).then((res) => {
      const fetchPromise = fetch(event.request).then((networkRes) => {
        if (event.request.method === 'GET' && networkRes.status === 200) {
          const copy = networkRes.clone();
          caches.open(CACHE_NAME).then(c => c.put(event.request, copy));
        }
        return networkRes;
      }).catch(() => null);
      return res || fetchPromise;
    })
  );
});

import React, { useState, useEffect, useRef } from 'react';
import { Track } from '../types';
import { TRACKS, SECTIONS } from '../constants';

interface PlaylistProps {
  onTrackSelect: (track: Track) => void;
  currentTrackId: string;
  isLargeText?: boolean;
}

const CUSTOM_TRACKS_KEY = 'zen_chant_custom_tracks';
const AUDIO_CACHE_NAME = 'zen-chant-audio';

const Playlist: React.FC<PlaylistProps> = ({ onTrackSelect, currentTrackId, isLargeText }) => {
  const [activeTab, setActiveTab] = useState<'official' | 'custom'>('official');
  const [customTracks, setCustomTracks] = useState<Track[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTrackTitle, setNewTrackTitle] = useState('');
  const [newTrackUrl, setNewTrackUrl] = useState('');
  const [addMethod, setAddMethod] = useState<'url' | 'file'>('url');

  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'completed' | 'partial'>('idle');
  const [syncProgress, setSyncProgress] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(CUSTOM_TRACKS_KEY);
    if (saved) {
      try {
        setCustomTracks(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse custom tracks', e);
      }
    }
    checkCacheStatus();
  }, []);

  const checkCacheStatus = async () => {
    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      const keys = await cache.keys();

      let validCount = 0;
      const officialUrls = TRACKS.map(t => new URL(t.audioUrl, window.location.origin).href);

      for (const url of officialUrls) {
        const response = await cache.match(url);
        // 关键校验：必须存在且不能是“不透明响应”(status 0)
        if (response && response.status !== 0) {
          validCount++;
        }
      }

      if (validCount === TRACKS.length) {
        setSyncStatus('completed');
        setSyncProgress(100);
      } else if (validCount > 0) {
        setSyncStatus('partial');
        setSyncProgress(Math.round((validCount / TRACKS.length) * 100));
      } else {
        setSyncStatus('idle');
        setSyncProgress(0);
      }
    } catch (e) {
      console.error("Cache check failed", e);
    }
  };

  const handleOfflineSync = async () => {
    if (syncStatus === 'syncing') return;

    setSyncStatus('syncing');

    try {
      const cache = await caches.open(AUDIO_CACHE_NAME);
      let processedCount = 0;
      let errorCount = 0;

      for (const track of TRACKS) {
        const normUrl = new URL(track.audioUrl, window.location.origin).href;
        const existing = await cache.match(normUrl);

        // 如果已存在且是有效响应（状态码 200），则跳过
        if (existing && existing.status === 200) {
          processedCount++;
          setSyncProgress(Math.round((processedCount / TRACKS.length) * 100));
          continue;
        }

        // 否则重新下载（如果是状态码 0 的坏响应，这会覆盖它）
        try {
          const response = await fetch(track.audioUrl, {
            mode: 'cors',
            credentials: 'omit',
            cache: 'no-cache' // 强制绕过可能的坏缓存重新从京东云拉取
          });

          if (response.ok) {
            await cache.put(normUrl, response);
          } else {
            errorCount++;
          }
        } catch (err) {
          errorCount++;
        }

        processedCount++;
        setSyncProgress(Math.round((processedCount / TRACKS.length) * 100));
        await new Promise(r => setTimeout(r, 50));
      }

      await checkCacheStatus();
      if (errorCount > 0) {
        alert(`同步完成，但有 ${errorCount} 首失败。请确认网络状况后重试。`);
      }
    } catch (e) {
      console.error("Sync error:", e);
      setSyncStatus('partial');
    }
  };

  const saveCustomTracks = (tracks: Track[]) => {
    setCustomTracks(tracks);
    localStorage.setItem(CUSTOM_TRACKS_KEY, JSON.stringify(tracks));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewTrackUrl(url);
      if (!newTrackTitle) {
        setNewTrackTitle(file.name.replace(/\.[^/.]+$/, ""));
      }
    }
  };

  const handleAddTrack = () => {
    if (!newTrackTitle || !newTrackUrl) return;

    const newTrack: Track = {
      id: `custom_${Date.now()}`,
      code: `Z${(customTracks.length + 1).toString().padStart(2, '0')}`,
      title: newTrackTitle,
      subtitle: addMethod === 'file' ? '本地上传' : '网络链接',
      section: 'CUSTOM',
      imageUrl: 'https://www.shouyueliang.org/wp-content/uploads/2021/04/1623587633-v500-4-1.gif',
      audioUrl: newTrackUrl
    };

    saveCustomTracks([...customTracks, newTrack]);
    setShowAddModal(false);
    setNewTrackTitle('');
    setNewTrackUrl('');
  };

  const removeTrack = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = customTracks.filter(t => t.id !== id);
    saveCustomTracks(updated);
  };

  return (
    <div className="flex flex-col h-full bg-dark-gradient overflow-hidden pt-10">
      <div className="flex-none bg-transparent px-6 mb-2">
        <div className="flex gap-4">
          <button 
            onClick={() => setActiveTab('official')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'official' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
          >
            <p className={`font-bold tracking-[0.1em] font-serif transition-all ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>官方曲目</p>
          </button>
          <button 
            onClick={() => setActiveTab('custom')}
            className={`flex-1 flex flex-col items-center border-b-2 pb-3 transition-all ${activeTab === 'custom' ? 'border-gold-main text-gold-main' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
          >
            <p className={`font-bold tracking-[0.1em] font-serif transition-all ${isLargeText ? 'text-xl' : 'text-[16px]'}`}>自定义</p>
          </button>
        </div>
      </div>

      {activeTab === 'official' && (
        <div className="px-6 py-3">
          <div className="bg-black/60 border border-white/10 rounded-2xl p-4 flex items-center justify-between shadow-inner">
            <div className="flex items-center gap-4">
              <div className={`relative flex items-center justify-center w-10 h-10 rounded-full bg-black/40 border ${syncStatus === 'completed' ? 'border-green-500/50 text-green-400' : 'border-gold-main/30 text-gold-main'}`}>
                {syncStatus === 'syncing' ? (
